const TL_MONTHS = ["Oct '25","Nov '25","Dec '25","Jan '26","Feb '26","Mar '26","Apr '26"];
const TL_TOTAL  = TL_MONTHS.length;
// Today = March 19 → month-index 5, day 19 out of 30
const TL_TODAY_PCT = ((5 + 19 / 30) / TL_TOTAL) * 100;

type TLStatus = "done" | "progress" | "upcoming";
type TLStage  = { label: string; startM: number; startD: number; endM: number; endD: number; status: TLStatus; };
type TLTeam   = { team: string; short: string; bar: string; badge: string; stages: TLStage[]; };

function tlPct(m: number, d: number) { return ((m + d / 30) / TL_TOTAL) * 100; }

