// ─── Page: Venue ──────────────────────────────────────────────────────────────
type RoomCategory = "keynote" | "talk" | "workshop" | "social" | "interview";
type RoomStatus   = "booked"  | "pending" | "available";
type DaySchedule  = { day: string; from: string; to: string };
interface VenueRoom {
  id: string; category: string; capacity: number;
  status: RoomStatus; schedule: DaySchedule[];
  price: number; photo: string; notes: string;
}
const CONF_DAYS = ["Apr 15", "Apr 16", "Apr 17", "Apr 18"];
const categoryMeta: Record<RoomCategory, { label: string; color: string; bg: string }> = {
  keynote:   { label:"Keynote",   color:"text-purple-700", bg:"bg-purple-50" },
  talk:      { label:"Talk",      color:"text-blue-700",   bg:"bg-blue-50" },
  workshop:  { label:"Workshop",  color:"text-teal-700",   bg:"bg-teal-50" },
  social:    { label:"Social",    color:"text-rose-700",   bg:"bg-rose-50" },
  interview: { label:"Interview", color:"text-amber-700",  bg:"bg-amber-50" },
};
const photoGradients: Record<RoomCategory, string> = {
  keynote:   "from-purple-400 to-indigo-600",
  talk:      "from-blue-400 to-cyan-500",
  workshop:  "from-teal-400 to-emerald-500",
  social:    "from-rose-400 to-pink-500",
  interview: "from-amber-400 to-orange-500",
};

function getCatMeta(cat: string) {
  return (categoryMeta as Record<string, { label:string; color:string; bg:string }>)[cat] ?? { label: cat, color:"text-gray-700", bg:"bg-gray-100" };
}
function getCatGradient(cat: string) {
  return (photoGradients as Record<string, string>)[cat] ?? "from-gray-400 to-gray-500";
}

function scheduleLabel(s: DaySchedule[]): string {
  if (!s.length) return "—";
  if (s.length === 1) return `${s[0].day} · ${s[0].from}–${s[0].to}`;
  return `${s.length} days · ${s[0].from}–${s[0].to}`;
}

