            {t.k==="organizers" && ORG_FLIGHTS.filter(f=>f.status==="pending").length>0 && (
              <span className="ml-1.5 px-1.5 py-0.5 bg-amber-500 text-white text-[9px] font-bold rounded-full">
                {ORG_FLIGHTS.filter(f=>f.status==="pending").length}
              </span>
            )}
            {t.k==="speakers" && SPK_FLIGHTS.filter(f=>f.status==="pending"||f.status==="arranging").length>0 && (
              <span className="ml-1.5 px-1.5 py-0.5 bg-amber-500 text-white text-[9px] font-bold rounded-full">
                {SPK_FLIGHTS.filter(f=>f.status==="pending"||f.status==="arranging").length}
              </span>
            )}
