function timeToMin(date:string, time:string) {
  const days:Record<string,number> = {"Apr 14":0,"Apr 15":1,"Apr 16":2,"Apr 17":3,"Apr 18":4,"Apr 19":5};
  const [h,m] = time.split(":").map(Number);
  return (days[date]??0)*24*60 + h*60 + m;
}

function generateAirportAssignment(reqs:AirportReq[], vehicles:TrVehicle[]): TripAssignment[] {
  const sorted = (dir:"Arrival"|"Departure") =>
    [...reqs.filter(r=>r.direction===dir)].sort((a,b)=>timeToMin(a.date,a.time)-timeToMin(b.date,b.time));
  const avVehicles = [...vehicles].sort((a,b)=>b.capacity-a.capacity);
  const trips:TripAssignment[] = [];
  const makeTrips = (list:AirportReq[], dir:string) => {
    let remaining = [...list];
    let vIdx = 0;
    while (remaining.length > 0) {
      const first = remaining[0];
      const windowEnd = timeToMin(first.date, first.time) + 90;
      const inWindow = remaining.filter(r => timeToMin(r.date,r.time) <= windowEnd);
      const vehicle = avVehicles[vIdx % avVehicles.length];
      const passengers = inWindow.slice(0, vehicle.capacity);
      const last = passengers[passengers.length-1];
      trips.push({
        label:`Trip ${trips.length+1}`,
        direction:dir,
        date:first.date,
        timeWindow: passengers.length>1 ? `${first.time} – ${last.time}` : first.time,
        vehicle,
        passengers,
      });
      const taken = new Set(passengers.map(p=>p.id));
      remaining = remaining.filter(r=>!taken.has(r.id));
      vIdx++;
    }
  };
  makeTrips(sorted("Arrival"),   "Arrival");
  makeTrips(sorted("Departure"), "Departure");
  return trips;
}

