function AccommodationPage() {
  const [accomGroup, setAccomGroup] = useState<"scholars"|"spk-org">("scholars");
  const [tab, setTab] = useState<"scholars"|"single"|"pairing"|"rooms">("scholars");
  const [roomAssignGenerated, setRoomAssignGenerated] = useState(false);
  const [notifDismissed, setNotifDismissed] = useState(false);
  const [regenerated, setRegenerated] = useState(false);
  const [hotelNotifDismissed, setHotelNotifDismissed] = useState(false);
  const [hotelCancelled, setHotelCancelled]           = useState(false);

  const totalCapacity = ROOM_INVENTORY.reduce((a,r) => a + r.capacity, 0);
  const totalOccupied = ROOM_INVENTORY.reduce((a,r) => a + r.occupied, 0);

  const cancelledScholars = ACCOM_SCHOLARS.filter(s => s.status === "cancelled");
  const unassignedRooms   = ROOM_INVENTORY.filter(r => r.occupied < r.capacity);
  const freeBeds          = ROOM_INVENTORY.reduce((s,r) => s + (r.capacity - r.occupied), 0);

  // After regeneration, remove cancelled scholars from the assignment list
  const displayedAssignment = regenerated
    ? ROOM_ASSIGNMENT.map(r => ({
        ...r,
        occupants: r.occupants.filter(o =>
          !cancelledScholars.some(cs => cs.name === o.name)
        ),
      })).filter(r => r.occupants.length > 0)
    : ROOM_ASSIGNMENT;

  return (
    <div className="space-y-4">
      <SectionHeader title="Accommodation" sub="Marriott Downtown Dubai · Apr 14–19 2026"/>

      {/* ── Group tabs ── */}
      <div className="flex gap-0.5 border-b border-gray-200">
        {([
          {k:"scholars", label:"🎓 MenaML Scholars"},
          {k:"spk-org",  label:"🧑‍💼 Speakers & Organizers"},
        ] as const).map(t => (
          <button key={t.k} onClick={() => setAccomGroup(t.k)}
            className={`px-3 py-2 text-xs font-medium border-b-2 -mb-px transition-colors ${
              accomGroup===t.k ? "border-emerald-500 text-emerald-700 bg-white" : "border-transparent text-gray-500 hover:text-gray-700"
            }`}>{t.label}</button>
        ))}
      </div>

      {accomGroup === "scholars" && <>
      {/* ── Total cost tile ── */}
      {(() => {
        const scholarTotal = ACCOM_SCHOLARS
          .filter(s => s.status !== "cancelled")
          .reduce((a, s) => a + s.nights * (s.roomType === "Deluxe" ? 900 : 650), 0);
        const confirmedCount = ACCOM_SCHOLARS.filter(s => s.status === "confirmed").length;
        const pendingCount   = ACCOM_SCHOLARS.filter(s => s.status === "pending").length;
        return (
          <div className="grid grid-cols-3 gap-3">
            <div className="border border-emerald-200 bg-emerald-50 rounded-xl p-3">
              <p className="text-2xl font-bold text-emerald-700">{confirmedCount}</p>
              <p className="text-[10px] text-gray-500 mt-0.5">Confirmed bookings</p>
            </div>
            <div className="border border-amber-200 bg-amber-50 rounded-xl p-3">
              <p className="text-2xl font-bold text-amber-700">{pendingCount}</p>
              <p className="text-[10px] text-gray-500 mt-0.5">Pending bookings</p>
            </div>
            <div className="border border-gray-200 bg-white rounded-xl p-3">
              <p className="text-2xl font-bold text-gray-800">AED {scholarTotal.toLocaleString()}</p>
              <p className="text-[10px] text-gray-500 mt-0.5">Total accommodation cost</p>
            </div>
          </div>
        );
      })()}

      {/* ── Cancellation notification ── */}
      {cancelledScholars.length > 0 && !notifDismissed && (
        <div className={`rounded-xl border px-4 py-3.5 flex items-start gap-3 transition-colors ${
          regenerated
            ? "bg-emerald-50 border-emerald-200"
            : "bg-amber-50 border-amber-200"
        }`}>
          {/* Icon */}
          <div className={`mt-0.5 flex-shrink-0 w-7 h-7 rounded-full flex items-center justify-center text-sm ${
            regenerated ? "bg-emerald-100" : "bg-amber-100"
          }`}>
            {regenerated ? "✓" : "⚠"}
          </div>

          {/* Body */}
          <div className="flex-1 min-w-0">
            {regenerated ? (
              <>
                <p className="text-sm font-semibold text-emerald-800">Assignment regenerated</p>
                <p className="text-xs text-emerald-700 mt-0.5">
                  {cancelledScholars.map(s => s.name).join(", ")} removed from the list.
                  {" "}{unassignedRooms.length} room{unassignedRooms.length !== 1 ? "s" : ""} now show open slots ({freeBeds} bed{freeBeds !== 1 ? "s" : ""} unassigned).
                </p>
                <div className="mt-2 flex flex-wrap gap-1.5">
                  {unassignedRooms.map(r => (
                    <span key={r.id} className="text-[10px] font-semibold px-2 py-0.5 rounded-full border bg-white border-emerald-200 text-emerald-700">
                      Room {r.roomNumber} · {r.capacity - r.occupied} bed{r.capacity - r.occupied !== 1 ? "s" : ""} free
                    </span>
                  ))}
                </div>
              </>
            ) : (
              <>
                <p className="text-sm font-semibold text-amber-800">
                  {cancelledScholars.length} student cancellation{cancelledScholars.length !== 1 ? "s" : ""} — room assignment outdated
                </p>
                <p className="text-xs text-amber-700 mt-0.5">
                  <span className="font-semibold">{cancelledScholars.map(s => s.name).join(", ")}</span> cancelled their registration.
                  {" "}{unassignedRooms.length} room{unassignedRooms.length !== 1 ? "s" : ""} currently have open beds ({freeBeds} bed{freeBeds !== 1 ? "s" : ""} unassigned in total).
                  Regenerate the assignment list to reflect current bookings.
                </p>
                <div className="mt-2 flex flex-wrap gap-1.5">
                  {unassignedRooms.map(r => (
                    <span key={r.id} className="text-[10px] font-semibold px-2 py-0.5 rounded-full border bg-white border-amber-200 text-amber-700">
                      Room {r.roomNumber} · {r.capacity - r.occupied} bed{r.capacity - r.occupied !== 1 ? "s" : ""} free
                    </span>
                  ))}
                </div>
              </>
            )}
          </div>

          {/* Actions */}
          <div className="flex items-center gap-2 flex-shrink-0">
            {!regenerated && (
              <button
                onClick={() => { setRegenerated(true); setRoomAssignGenerated(true); }}
                className="flex items-center gap-1.5 text-xs font-semibold px-3 py-1.5 rounded-lg bg-amber-600 hover:bg-amber-700 text-white transition-colors">
                <RefreshCw size={11}/> Regenerate Assignment
              </button>
            )}
            <button onClick={() => setNotifDismissed(true)}
              className="text-gray-400 hover:text-gray-600 p-1 rounded hover:bg-white/60">
              <X size={13}/>
            </button>
          </div>
        </div>
      )}

      {/* Generate Assignment */}
      <div className="flex items-center gap-3">
        <button onClick={() => setRoomAssignGenerated(v => !v)}
          className={`flex items-center gap-1.5 text-xs font-semibold px-3 py-1.5 rounded-lg border transition-colors ${
            roomAssignGenerated
              ? "bg-emerald-600 text-white border-emerald-600 hover:bg-emerald-700"
              : "border-emerald-500 text-emerald-700 bg-white hover:bg-emerald-50"
          }`}>
          <span>📋</span> {roomAssignGenerated ? "Hide Assignment List" : "Generate Room Assignment List"}
        </button>
        {regenerated && (
          <span className="text-[11px] font-semibold text-emerald-600 flex items-center gap-1">
            <CheckCircle2 size={12}/> Regenerated — cancellations applied
          </span>
        )}
      </div>

      {roomAssignGenerated && (
        <div className="bg-white border border-gray-200 rounded-lg overflow-hidden">
          <div className="flex items-center justify-between px-4 py-3 border-b border-gray-100 bg-gray-50">
            <div>
              <h3 className="text-sm font-semibold text-gray-800">Room Assignment List</h3>
              <p className="text-[10px] text-gray-500 mt-0.5">Marriott Downtown Dubai · Apr 14–19 2026 · {displayedAssignment.length} rooms assigned{regenerated ? " · cancellations applied" : ""}</p>
            </div>
            <button className="flex items-center gap-1.5 text-[11px] font-medium text-gray-500 hover:text-gray-700 border border-gray-200 rounded-lg px-2.5 py-1.5 bg-white hover:bg-gray-50 transition-colors">
              ↓ Export CSV
            </button>
          </div>
          <table className="w-full text-xs border-collapse">
            <thead>
              <tr className="bg-gray-50 border-b border-gray-200">
                {["Room","Floor","Type","Gender","Guest 1 — Name","Guest 1 — Email","Guest 2 — Name","Guest 2 — Email"].map(h => (
                  <th key={h} className="text-left px-3 py-2.5 text-[11px] font-semibold text-gray-500">{h}</th>
                ))}
              </tr>
            </thead>
            <tbody>
              {displayedAssignment.map((r, i) => {
                const g1 = r.occupants[0];
                const g2 = r.occupants[1];
                const isSingle = r.occupants.length === 1;
                return (
                  <tr key={r.roomNumber} className={`border-b border-gray-50 hover:bg-gray-50 ${i%2===0?"bg-white":"bg-gray-50/20"}`}>
                    <td className="px-3 py-2.5 font-mono font-semibold text-gray-800">{r.roomNumber}</td>
                    <td className="px-3 py-2.5 text-gray-500">F{r.floor}</td>
                    <td className="px-3 py-2.5 text-gray-600">{r.type}</td>
                    <td className="px-3 py-2.5">
                      <span className={`text-[10px] font-medium px-2 py-0.5 rounded-full border ${
                        r.gender==="Female" ? "bg-pink-50 text-pink-600 border-pink-200"
                        : r.gender==="Male"  ? "bg-blue-50 text-blue-600 border-blue-200"
                        : "bg-gray-50 text-gray-400 border-gray-200"
                      }`}>{r.gender}</span>
                    </td>
                    <td className="px-3 py-2.5 font-medium text-gray-800">{g1?.name ?? "—"}</td>
                    <td className="px-3 py-2.5 text-gray-500 font-mono text-[10px]">{g1?.email ?? "—"}</td>
                    <td className="px-3 py-2.5">
                      {isSingle
                        ? <span className="text-[10px] italic text-gray-300">Single room</span>
                        : <span className="font-medium text-gray-800">{g2?.name ?? "—"}</span>}
                    </td>
                    <td className="px-3 py-2.5 text-gray-500 font-mono text-[10px]">
                      {isSingle ? "—" : (g2?.email ?? "—")}
                    </td>
                  </tr>
                );
              })}
            </tbody>
          </table>
        </div>
      )}

      {/* Tabs */}
      <div className="flex gap-0.5 border-b border-gray-200">
        {([
          {k:"scholars", label:"🏅 Scholarship Recipients"},
          {k:"single",   label:"🚪 Single Room Requests"},
          {k:"pairing",  label:"👥 Pairing Requests"},
          {k:"rooms",    label:"🏨 Room Inventory"},
        ] as const).map(t => (
          <button key={t.k} onClick={() => setTab(t.k)}
            className={`px-3 py-2 text-xs font-medium border-b-2 -mb-px transition-colors ${
              tab===t.k ? "border-emerald-500 text-emerald-700 bg-white" : "border-transparent text-gray-500 hover:text-gray-700"
            }`}>{t.label}</button>
        ))}
      </div>

      {/* ── Scholarship Recipients ── */}
      {tab === "scholars" && (
        <div className="bg-white border border-gray-200 rounded-lg overflow-hidden">
          <table className="w-full text-xs border-collapse">
            <thead>
              <tr className="bg-gray-50 border-b border-gray-200">
                {["Student","Affiliation","Country","Check-in","Check-out","Nights","Room Type","Cost","Status"].map(h => (
                  <th key={h} className="text-left px-3 py-2.5 text-[11px] font-semibold text-gray-500">{h}</th>
                ))}
              </tr>
            </thead>
            <tbody>
              {ACCOM_SCHOLARS.map((s, i) => (
                <tr key={s.id} className={`border-b border-gray-50 hover:bg-gray-50 ${i%2===0?"bg-white":"bg-gray-50/30"}`}>
                  <td className="px-3 py-2.5 font-semibold text-gray-800">{s.name}</td>
                  <td className="px-3 py-2.5 text-gray-600">{s.affiliation}</td>
                  <td className="px-3 py-2.5">
                    <span className="text-[10px] bg-gray-100 text-gray-600 rounded px-1.5 py-0.5 font-mono">{s.country}</span>
                  </td>
                  <td className="px-3 py-2.5 text-gray-500">{s.checkin}</td>
                  <td className="px-3 py-2.5 text-gray-500">{s.checkout}</td>
                  <td className="px-3 py-2.5 text-center font-medium text-gray-700">{s.nights}</td>
                  <td className="px-3 py-2.5 text-gray-600">{s.roomType}</td>
                  <td className="px-3 py-2.5">
                    {s.status === "cancelled"
                      ? <span className="text-[10px] text-gray-400">—</span>
                      : <span className="text-[10px] font-bold text-gray-800">
                          AED {(s.nights * (s.roomType === "Deluxe" ? 900 : 650)).toLocaleString()}
                        </span>}
                  </td>
                  <td className="px-3 py-2.5">
                    <span className={`text-[10px] font-medium px-2 py-0.5 rounded-full border ${
                      s.status==="confirmed" ? "bg-emerald-50 text-emerald-700 border-emerald-200"
                      : s.status==="pending" ? "bg-amber-50 text-amber-700 border-amber-200"
                      : "bg-red-50 text-red-500 border-red-200"
                    }`}>{s.status.charAt(0).toUpperCase()+s.status.slice(1)}</span>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      )}

      {/* ── Single Room Requests ── */}
      {tab === "single" && (
        <div className="space-y-2.5">
          {SINGLE_ROOM_REQS.map(r => (
            <div key={r.id} className={`rounded-lg border p-4 ${
              r.status==="approved" ? "border-emerald-200 bg-emerald-50/30"
              : r.status==="declined" ? "border-red-200 bg-red-50/20"
              : "border-gray-200 bg-white"
            }`}>
              <div className="flex items-start justify-between gap-4">
                <div className="flex-1 min-w-0">
                  <div className="flex items-center gap-2 flex-wrap">
                    <p className="text-sm font-semibold text-gray-800">{r.name}</p>
                    <span className="text-[10px] text-gray-500 bg-gray-100 rounded px-1.5 py-0.5">{r.affiliation}</span>
                    <span className={`text-[9px] font-bold uppercase tracking-wide px-1.5 py-0.5 rounded ${
                      r.priority==="high"   ? "bg-red-100 text-red-600"
                      : r.priority==="medium" ? "bg-amber-100 text-amber-600"
                      : "bg-gray-100 text-gray-500"
                    }`}>{r.priority} priority</span>
                  </div>
                  <p className="text-xs text-gray-600 mt-2 leading-relaxed italic">
                    <span className="text-gray-400 not-italic font-medium">Justification: </span>
                    {r.justification}
                  </p>
                </div>
                <span className={`flex-shrink-0 text-[11px] font-bold px-3 py-1.5 rounded-full border whitespace-nowrap ${
                  r.status==="approved" ? "bg-emerald-600 text-white border-emerald-600"
                  : r.status==="declined" ? "bg-white text-red-600 border-red-200"
                  : "bg-white text-amber-700 border-amber-300"
                }`}>
                  {r.status==="approved" ? "✓ Approved" : r.status==="declined" ? "✗ Declined" : "⏳ Pending"}
                </span>
              </div>
            </div>
          ))}
        </div>
      )}

      {/* ── Pairing Requests ── */}
      {tab === "pairing" && (
        <div className="bg-white border border-gray-200 rounded-lg overflow-hidden">
          <table className="w-full text-xs border-collapse">
            <thead>
              <tr className="bg-gray-50 border-b border-gray-200">
                {["Requester","Affiliation","Requested Pairing With","Note","Status"].map(h => (
                  <th key={h} className="text-left px-3 py-2.5 text-[11px] font-semibold text-gray-500">{h}</th>
                ))}
              </tr>
            </thead>
            <tbody>
              {PAIRING_REQS.map((r, i) => (
                <tr key={r.id} className={`border-b border-gray-50 hover:bg-gray-50 ${i%2===0?"bg-white":"bg-gray-50/20"}`}>
                  <td className="px-3 py-3 font-semibold text-gray-800">{r.requesterName}</td>
                  <td className="px-3 py-3 text-gray-500">{r.requesterAffil}</td>
                  <td className="px-3 py-3">
                    {r.requestedWith
                      ? <span className="font-medium text-blue-700">{r.requestedWith}</span>
                      : <span className="italic text-gray-400">Open request</span>}
                  </td>
                  <td className="px-3 py-3 text-gray-500 italic max-w-xs leading-relaxed">"{r.note}"</td>
                  <td className="px-3 py-3">
                    <span className={`text-[10px] font-semibold px-2 py-0.5 rounded-full border ${
                      r.status==="matched"   ? "bg-emerald-50 text-emerald-700 border-emerald-200"
                      : r.status==="unmatched" ? "bg-red-50 text-red-600 border-red-200"
                      : "bg-amber-50 text-amber-700 border-amber-200"
                    }`}>{r.status.charAt(0).toUpperCase()+r.status.slice(1)}</span>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      )}

      {/* ── Room Inventory ── */}
      {tab === "rooms" && (
        <div className="space-y-3">
          <div className="flex items-center justify-between">
            <div className="flex items-center gap-5 text-[10px] text-gray-500">
              <span className="flex items-center gap-1.5"><span className="w-2.5 h-2.5 rounded-full bg-pink-400 inline-block"/>Female</span>
              <span className="flex items-center gap-1.5"><span className="w-2.5 h-2.5 rounded-full bg-blue-400 inline-block"/>Male</span>
              <span className="flex items-center gap-1.5"><span className="w-2.5 h-2.5 rounded-full bg-violet-400 inline-block"/>Mixed</span>
              <span className="flex items-center gap-1.5"><span className="w-2.5 h-2.5 rounded-full bg-gray-200 inline-block"/>Unassigned</span>
            </div>
            <button className="flex items-center gap-1.5 text-xs font-semibold px-3 py-1.5 rounded-lg bg-emerald-600 text-white hover:bg-emerald-700 transition-colors shadow-sm">
              <Plus size={13}/> Add Room
            </button>
          </div>
          <div className="bg-white border border-gray-200 rounded-lg overflow-hidden">
            <table className="w-full text-xs border-collapse">
              <thead>
                <tr className="bg-gray-50 border-b border-gray-200">
                  {["Room","Floor","Type","Capacity","Gender"].map(h => (
                    <th key={h} className="text-left px-3 py-2.5 text-[11px] font-semibold text-gray-500">{h}</th>
                  ))}
                </tr>
              </thead>
              <tbody>
                {ROOM_INVENTORY.map((r, i) => (
                  <tr key={r.id} className={`border-b border-gray-50 hover:bg-gray-50 ${i%2===0?"bg-white":"bg-gray-50/20"}`}>
                    <td className="px-3 py-2.5 font-mono font-semibold text-gray-800">{r.roomNumber}</td>
                    <td className="px-3 py-2.5 text-gray-500">F{r.floor}</td>
                    <td className="px-3 py-2.5 text-gray-600">{r.type}</td>
                    <td className="px-3 py-2.5 text-center text-gray-700 font-medium">{r.capacity}</td>
                    <td className="px-3 py-2.5">
                      <span className={`text-[10px] font-medium px-2 py-0.5 rounded-full border ${
                        r.gender==="Female" ? "bg-pink-50 text-pink-600 border-pink-200"
                        : r.gender==="Male"  ? "bg-blue-50 text-blue-600 border-blue-200"
                        : r.gender==="Mixed" ? "bg-violet-50 text-violet-600 border-violet-200"
                        : "bg-gray-50 text-gray-400 border-gray-200"
                      }`}>{r.gender}</span>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        </div>
      )}
      </>}

      {/* ── Speakers & Organizers hotel bookings ── */}
      {accomGroup === "spk-org" && (() => {
        const confirmed   = SPK_ORG_HOTEL.filter(r=>r.hotelStatus==="confirmed").length;
        const pending_    = SPK_ORG_HOTEL.filter(r=>r.hotelStatus==="pending").length;
        const selfArr     = SPK_ORG_HOTEL.filter(r=>r.hotelStatus==="self-arranged").length;
        const totalCost   = SPK_ORG_HOTEL
          .filter(r=>r.hotelStatus!=="self-arranged")
          .reduce((a,r)=>a+r.nights*r.ratePerNight,0);
        const hStatusCls: Record<string,string> = {
          confirmed:      "bg-emerald-50 text-emerald-700 border-emerald-200",
          pending:        "bg-amber-50 text-amber-700 border-amber-200",
          "self-arranged":"bg-violet-50 text-violet-700 border-violet-200",
        };
        const roomTypeCls: Record<string,string> = {
          Standard: "bg-gray-100 text-gray-600 border-gray-200",
          Deluxe:   "bg-blue-50 text-blue-700 border-blue-200",
          Suite:    "bg-violet-50 text-violet-700 border-violet-200",
        };
        return (
          <div className="space-y-4">

            {/* ── Cancelled hotel notification ── */}
            {CANCELLED_SPK_ORG_HOTELS.length > 0 && !hotelNotifDismissed && (
              <div className={`rounded-xl border px-4 py-3.5 flex items-start gap-3 transition-colors ${
                hotelCancelled ? "bg-emerald-50 border-emerald-200" : "bg-red-50 border-red-200"
              }`}>
                {/* Icon */}
                <div className={`mt-0.5 flex-shrink-0 w-7 h-7 rounded-full flex items-center justify-center text-sm ${
                  hotelCancelled ? "bg-emerald-100" : "bg-red-100"
                }`}>
                  {hotelCancelled ? "✓" : "🏨"}
                </div>

                {/* Body */}
                <div className="flex-1 min-w-0">
                  {hotelCancelled ? (
                    <>
                      <p className="text-sm font-semibold text-emerald-800">Hotel booking cancelled</p>
                      <p className="text-xs text-emerald-700 mt-0.5">
                        The {CANCELLED_SPK_ORG_HOTELS[0].hotel} reservation for{" "}
                        <span className="font-semibold">{CANCELLED_SPK_ORG_HOTELS[0].name}</span> has been cancelled.
                        {" "}AED {CANCELLED_SPK_ORG_HOTELS[0].totalCost.toLocaleString()} released from the hotel budget.
                      </p>
                      <div className="mt-2 flex flex-wrap gap-1.5">
                        {CANCELLED_SPK_ORG_HOTELS.map(h => (
                          <span key={h.id} className="text-[10px] font-semibold px-2 py-0.5 rounded-full border bg-white border-emerald-200 text-emerald-700">
                            {h.name} · {h.roomType} · {h.checkin}–{h.checkout} · AED {h.totalCost.toLocaleString()}
                          </span>
                        ))}
                      </div>
                    </>
                  ) : (
                    <>
                      <p className="text-sm font-semibold text-red-800">
                        {CANCELLED_SPK_ORG_HOTELS.length} {CANCELLED_SPK_ORG_HOTELS.length === 1 ? "cancellation" : "cancellations"} — hotel booking needs to be cancelled
                      </p>
                      <p className="text-xs text-red-700 mt-0.5">
                        <span className="font-semibold">{CANCELLED_SPK_ORG_HOTELS.map(h=>h.name).join(", ")}</span>{" "}
                        cancelled their participation on {CANCELLED_SPK_ORG_HOTELS[0].cancelledOn}.
                        {" "}A confirmed {CANCELLED_SPK_ORG_HOTELS[0].roomType} room (AED {CANCELLED_SPK_ORG_HOTELS[0].ratePerNight}/night · {CANCELLED_SPK_ORG_HOTELS[0].nights} nights) is still active at {CANCELLED_SPK_ORG_HOTELS[0].hotel}.
                        Contact the hotel to release the booking.
                      </p>
                      <div className="mt-2 flex flex-wrap gap-1.5">
                        {CANCELLED_SPK_ORG_HOTELS.map(h => (
                          <span key={h.id} className="text-[10px] font-semibold px-2 py-0.5 rounded-full border bg-white border-red-200 text-red-700">
                            {h.name} · {h.roomType} · {h.checkin}–{h.checkout} · {h.hotel} · {h.hotelPhone}
                          </span>
                        ))}
                      </div>
                    </>
                  )}
                </div>

                {/* Actions */}
                <div className="flex items-center gap-2 flex-shrink-0">
                  {!hotelCancelled && (
                    <button
                      onClick={() => setHotelCancelled(true)}
                      className="text-xs px-3 py-1.5 rounded-lg bg-red-600 hover:bg-red-700 text-white font-semibold transition-colors"
                    >
                      Cancel Booking
                    </button>
                  )}
                  <button
                    onClick={() => setHotelNotifDismissed(true)}
                    className="text-gray-400 hover:text-gray-600 transition-colors text-lg leading-none"
                    title="Dismiss"
                  >×</button>
                </div>
              </div>
            )}

            {/* Summary tiles */}
            <div className="grid grid-cols-4 gap-3">
              {[
                {l:"Confirmed",     n:confirmed, txt:"text-emerald-700", bg:"bg-emerald-50", border:"border-emerald-200"},
                {l:"Pending",       n:pending_,  txt:"text-amber-700",   bg:"bg-amber-50",   border:"border-amber-200"},
                {l:"Self-arranged", n:selfArr,   txt:"text-violet-700",  bg:"bg-violet-50",  border:"border-violet-200"},
                {l:"Total hotel cost", n:`AED ${totalCost.toLocaleString()}`, txt:"text-gray-800", bg:"bg-white", border:"border-gray-200"},
              ].map(s=>(
                <div key={s.l} className={`border ${s.border} ${s.bg} rounded-xl p-3`}>
                  <p className={`text-xl font-bold ${s.txt}`}>{s.n}</p>
                  <p className="text-[10px] text-gray-500 mt-0.5">{s.l}</p>
                </div>
              ))}
            </div>

            {/* Table */}
            <div className="bg-white border border-gray-200 rounded-lg overflow-hidden">
              <div className="px-4 py-3 border-b border-gray-100 bg-gray-50 flex items-center justify-between">
                <div>
                  <h3 className="text-xs font-semibold text-gray-800">Hotel Booking Summary</h3>
                  <p className="text-[10px] text-gray-400 mt-0.5">Marriott Downtown Dubai · All speakers and organizers</p>
                </div>
                <button className="flex items-center gap-1.5 text-[11px] font-medium text-gray-500 hover:text-gray-700 border border-gray-200 rounded-lg px-2.5 py-1.5 bg-white hover:bg-gray-50 transition-colors">
                  ↓ Export CSV
                </button>
              </div>
              <table className="w-full text-xs border-collapse">
                <thead>
                  <tr className="bg-gray-50 border-b border-gray-100">
                    {["Name","Role","Type","Check-in","Check-out","Nights","Room Type","Rate/Night","Total Cost","Status"].map(h=>(
                      <th key={h} className="text-left px-3 py-2.5 text-[9px] font-bold text-gray-400 uppercase tracking-wide whitespace-nowrap">{h}</th>
                    ))}
                  </tr>
                </thead>
                <tbody>
                  {SPK_ORG_HOTEL.map((r,i)=>(
                    <tr key={r.id} className={`border-b border-gray-50 ${i%2===0?"bg-white":"bg-gray-50/30"}`}>
                      <td className="px-3 py-2.5">
                        <div className="flex items-center gap-2">
                          <div className={`w-6 h-6 rounded-full flex items-center justify-center text-white text-[8px] font-bold flex-shrink-0 ${r.personType==="organizer"?"bg-gradient-to-br from-blue-400 to-indigo-500":"bg-gradient-to-br from-purple-400 to-violet-500"}`}>
                            {r.name.split(" ").map((n:string)=>n[0]).join("").slice(0,2)}
                          </div>
                          <span className="text-[11px] font-semibold text-gray-800 whitespace-nowrap">{r.name}</span>
                        </div>
                      </td>
                      <td className="px-3 py-2.5 text-[10px] text-gray-500 max-w-[130px]"><span className="line-clamp-1">{r.role}</span></td>
                      <td className="px-3 py-2.5">
                        <span className={`text-[9px] font-bold px-1.5 py-0.5 rounded-full border ${r.personType==="organizer"?"bg-blue-50 text-blue-700 border-blue-200":"bg-violet-50 text-violet-700 border-violet-200"}`}>
                          {r.personType==="organizer"?"Organizer":"Speaker"}
                        </span>
                      </td>
                      <td className="px-3 py-2.5 text-[10px] text-gray-600 whitespace-nowrap">{r.checkin}</td>
                      <td className="px-3 py-2.5 text-[10px] text-gray-600 whitespace-nowrap">{r.checkout}</td>
                      <td className="px-3 py-2.5 text-center text-[10px] font-medium text-gray-700">{r.nights}</td>
                      <td className="px-3 py-2.5">
                        <span className={`text-[9px] font-bold px-1.5 py-0.5 rounded border ${roomTypeCls[r.roomType]}`}>{r.roomType}</span>
                      </td>
                      <td className="px-3 py-2.5 text-[10px] font-medium text-gray-700">
                        {r.hotelStatus==="self-arranged" ? <span className="text-gray-400">—</span> : `AED ${r.ratePerNight.toLocaleString()}`}
                      </td>
                      <td className="px-3 py-2.5">
                        {r.hotelStatus==="self-arranged"
                          ? <span className="text-[10px] text-gray-400">—</span>
                          : <span className="text-[10px] font-bold text-gray-800">AED {(r.nights*r.ratePerNight).toLocaleString()}</span>}
                      </td>
                      <td className="px-3 py-2.5">
                        <span className={`text-[9px] font-bold px-2 py-0.5 rounded-full border capitalize ${hStatusCls[r.hotelStatus]}`}>
                          {r.hotelStatus==="self-arranged"?"Self-arranged":r.hotelStatus==="confirmed"?"✓ Confirmed":"⏳ Pending"}
                        </span>
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          </div>
        );
      })()}
    </div>
  );
}

// ─── Page: Volunteers ─────────────────────────────────────────────────────────
