const IE_GRADIENTS = ["from-purple-400 to-indigo-500","from-emerald-400 to-teal-500","from-rose-400 to-pink-500","from-amber-400 to-orange-500","from-blue-400 to-cyan-500","from-violet-400 to-purple-500"];

const ie_judges = [
  {name:"Prof. Khaled Shaalan", org:"AUS Dubai",    expertise:"NLP & Arabic AI",              sessions:["S1","S2"], posters:3, status:"confirmed", grad:"from-violet-400 to-purple-500"},
  {name:"Dr. Maha Al-Yahya",   org:"KSU",           expertise:"Computational Linguistics",    sessions:["S1"],      posters:2, status:"confirmed", grad:"from-blue-400 to-cyan-500"},
  {name:"Dr. Fouad Zablith",   org:"AUB",           expertise:"Semantic Web, Knowledge Graphs",sessions:["S2"],     posters:1, status:"confirmed", grad:"from-teal-400 to-emerald-500"},
  {name:"Dr. Imen Saad",       org:"INSAT Tunis",   expertise:"ML & Data Mining",             sessions:[],          posters:0, status:"invited",   grad:"from-amber-400 to-orange-500"},
];
const ie_sponsors = [
  {company:"Microsoft MENA",  contact:"Layla Hassan",       role:"Partnership Lead",  tier:"Gold",   amount:50000, status:"confirmed", country:"UAE", grad:"from-blue-500 to-indigo-600"},
  {company:"KAUST",           contact:"Prof. Ali Al-Sunaidi",role:"Academic Director",tier:"Gold",   amount:35000, status:"confirmed", country:"SA",  grad:"from-emerald-500 to-teal-600"},
  {company:"AWS MENA",        contact:"Tariq Masri",        role:"Startup Relations", tier:"Silver", amount:25000, status:"confirmed", country:"UAE", grad:"from-amber-400 to-orange-500"},
  {company:"Flat6Labs",       contact:"Ghita Mezzour",      role:"CEO",               tier:"Silver", amount:20000, status:"confirmed", country:"MA",  grad:"from-rose-400 to-pink-500"},
  {company:"Aramco Digital",  contact:"Faisal Al-Owaisi",   role:"Innovation VP",     tier:"Bronze", amount:15000, status:"pending",   country:"SA",  grad:"from-gray-400 to-gray-500"},
  {company:"Careem",          contact:"Sarah Khalid",       role:"Engineering Lead",  tier:"Bronze", amount:10000, status:"confirmed", country:"AE",  grad:"from-violet-400 to-purple-500"},
];
const ie_vips = [
  {name:"H.E. Omar Sultan Al Olama", role:"Minister of State for AI",    org:"UAE Government",        country:"UAE", status:"confirmed", note:"Opening ceremony keynote"},
  {name:"Dr. Hala Al-Turki",         role:"Secretary General",           org:"Arab League Digital",   country:"SA",  status:"confirmed", note:"Panel: AI Policy in MENA"},
  {name:"Eng. Faisal Al-Aqeel",      role:"CEO",                         org:"SDAIA",                 country:"SA",  status:"pending",   note:"Invited — closing ceremony"},
  {name:"Dr. Tarek Kafafi",          role:"VP of Research",              org:"STDF Egypt",            country:"EG",  status:"invited",   note:"Workshop observer"},
  {name:"Leila El-Khalil",           role:"Minister of Education",       org:"Lebanese Government",   country:"LB",  status:"invited",   note:"Education & AI track"},
];
const TIER_STYLE:{[k:string]:{chip:string;border:string}} = {
  Gold:   {chip:"bg-amber-100 text-amber-700 border-amber-200",  border:"border-l-amber-400"},
  Silver: {chip:"bg-gray-100 text-gray-600 border-gray-200",     border:"border-l-gray-300"},
  Bronze: {chip:"bg-orange-100 text-orange-700 border-orange-200",border:"border-l-orange-300"},
};
const IE_STATUS_PILL:{[k:string]:string} = {
  confirmed:"bg-green-100 text-green-700",
  pending:  "bg-amber-100 text-amber-700",
  invited:  "bg-blue-100 text-blue-700",
};

type IeTab = "speakers"|"mentors"|"judges"|"sponsors"|"vips"|"all";
type SpkDraft = {name:string;org:string;country:string;talkTitle:string;talkType:string;sessionDate:string;sessionTime:string;sessionRoom:string;bio:string;formUrl:string;sendForm:boolean};
const EMPTY_SPK:SpkDraft = {name:"",org:"",country:"",talkTitle:"",talkType:"keynote",sessionDate:"",sessionTime:"",sessionRoom:"",bio:"",formUrl:"",sendForm:true};

function InvitedExpertsPage() {
  const [ieTab, setIeTab]         = useState<IeTab>("all");
  const [showAddSpk, setShowAddSpk] = useState(false);
  const [newSpk,  setNewSpk]      = useState<SpkDraft>(EMPTY_SPK);
  const [spkList, setSpkList]     = useState(speakers);
  const [formSent, setFormSent]   = useState(false);
  const [cancelled, setCancelled] = useState<Record<string,boolean>>({});
  function toggleCancel(tab:string,idx:number){
    setCancelled(p=>({...p,[`${tab}-${idx}`]:!p[`${tab}-${idx}`]}));
  }

  const [regDone, setRegDone]     = useState<Record<string,boolean>>({
    "speakers-0":true,"speakers-1":true,"speakers-2":true,"speakers-4":true,
    "mentors-0":true,"mentors-1":true,"mentors-4":true,
    "judges-0":true,"judges-1":true,
    "sponsors-0":true,"sponsors-1":true,"sponsors-2":true,"sponsors-3":true,"sponsors-5":true,
    "vips-0":true,"vips-1":true,
  });
  function toggleReg(tab:string,idx:number){
    setRegDone(p=>({...p,[`${tab}-${idx}`]:!p[`${tab}-${idx}`]}));
  }
  function RegBadge({tab,idx}:{tab:string;idx:number}){
    const done = !!regDone[`${tab}-${idx}`];
    return (
      <button onClick={()=>toggleReg(tab,idx)}
        className={`flex items-center gap-1 text-[9px] font-bold px-2 py-1 rounded-full border transition-all whitespace-nowrap ${
          done
            ?"bg-emerald-50 text-emerald-700 border-emerald-200 hover:bg-emerald-100"
            :"bg-gray-50 text-gray-400 border-gray-200 hover:bg-gray-100"
        }`}>
        {done?<CheckCircle2 size={9}/>:<div className="w-2 h-2 rounded-full border border-gray-300"/>}
        {done?"Registered":"Not registered"}
      </button>
    );
  }

  function submitSpeaker() {
    if(!newSpk.name.trim()||!newSpk.talkTitle.trim()) return;
    setSpkList(prev=>[...prev,{
      name:newSpk.name.trim(), org:newSpk.org.trim(),
      topic:`${newSpk.talkType[0].toUpperCase()+newSpk.talkType.slice(1)}: ${newSpk.talkTitle.trim()}`,
      country:newSpk.country.trim()||"—", status:"pending",
    }]);
    if(newSpk.sendForm && newSpk.formUrl.trim()) setFormSent(true);
    setNewSpk(EMPTY_SPK);
    setShowAddSpk(false);
  }

  const allTotal = spkList.length + mentors.length + ie_judges.length + ie_sponsors.length + ie_vips.length;
  const allReg   = Object.values(regDone).filter(Boolean).length;

  const headerSub:Record<IeTab,string> = {
    speakers: `${spkList.length} speakers confirmed`,
    mentors:  "Manage mentor sessions and bookings",
    judges:   `${ie_judges.length} poster session judges`,
    sponsors: `${ie_sponsors.length} sponsors · AED ${ie_sponsors.reduce((s,x)=>s+x.amount,0).toLocaleString()} pledged`,
    vips:     `${ie_vips.length} VIP guests invited`,
    all:      `${allTotal} guests total · ${allReg} registered`,
  };
  const headerAction:Record<IeTab,React.ReactNode> = {
    speakers: (
      <Button size="sm" onClick={()=>{setShowAddSpk(s=>!s);setFormSent(false);}}
        className={`text-xs gap-1.5 ${showAddSpk?"bg-gray-200 hover:bg-gray-300 text-gray-700":"bg-emerald-600 hover:bg-emerald-700 text-white"}`}>
        {showAddSpk?<><X size={13}/>Cancel</>:<><Plus size={13}/>Add Speaker</>}
      </Button>
    ),
    mentors:  <Button size="sm" className="bg-emerald-600 hover:bg-emerald-700 text-white text-xs gap-1.5"><Plus size={13}/>Add Mentor</Button>,
    judges:   <Button size="sm" className="bg-emerald-600 hover:bg-emerald-700 text-white text-xs gap-1.5"><Plus size={13}/>Invite Judge</Button>,
    sponsors: <Button size="sm" className="bg-emerald-600 hover:bg-emerald-700 text-white text-xs gap-1.5"><Plus size={13}/>Add Lead</Button>,
    vips:     <Button size="sm" className="bg-emerald-600 hover:bg-emerald-700 text-white text-xs gap-1.5"><Plus size={13}/>Add Guest</Button>,
    all:      <Button size="sm" variant="outline" className="text-xs gap-1.5"><Download size={12}/>Export list</Button>,
  };

  // ── Registration overview (computed here so it's always fresh) ──
  const regGroups = [
    {label:"Speakers", tab:"speakers", total:spkList.length,    color:"bg-purple-100 text-purple-700"},
    {label:"Mentors",  tab:"mentors",  total:mentors.length,    color:"bg-teal-100 text-teal-700"},
    {label:"Judges",   tab:"judges",   total:ie_judges.length,  color:"bg-violet-100 text-violet-700"},
    {label:"Sponsors", tab:"sponsors", total:ie_sponsors.length,color:"bg-amber-100 text-amber-700"},
    {label:"VIPs",     tab:"vips",     total:ie_vips.length,    color:"bg-rose-100 text-rose-700"},
  ].map(g=>({...g, reg:Array.from({length:g.total},(_,i)=>!!regDone[`${g.tab}-${i}`]).filter(Boolean).length}));
  const totalUnreg = regGroups.reduce((s,g)=>s+(g.total-g.reg),0);
  const grandTotal = regGroups.reduce((s,g)=>s+g.total,0);

  // ── Cancellations → open roles ──
  type OpenRole = {key:string; type:string; typeColor:string; name:string; openRole:string; detail:string};
  const cancelledRoles:OpenRole[] = Object.entries(cancelled)
    .filter(([,v])=>v)
    .map(([key])=>{
      const [tab,idxStr] = key.split("-");
      const idx = +idxStr;
      if(tab==="speakers"&&spkList[idx]){
        const s=spkList[idx];
        const topicParts = s.topic.split(": ");
        const talkType = topicParts.length>1 ? topicParts[0] : "Talk";
        const talkTitle = topicParts.length>1 ? topicParts.slice(1).join(": ") : s.topic;
        return {key,type:"Speaker",typeColor:"bg-purple-100 text-purple-700",name:s.name,openRole:`${talkType} slot open`,detail:`Topic: "${talkTitle}" · ${s.org}`};
      }
      if(tab==="mentors"&&mentors[idx]){
        const m=mentors[idx];
        return {key,type:"Mentor",typeColor:"bg-teal-100 text-teal-700",name:m.name,openRole:"Mentor slot open",detail:`Roundtable session · Expertise: ${m.expertise} · ${m.slots} session slot${m.slots!==1?"s":""} unfilled`};
      }
      if(tab==="judges"&&ie_judges[idx]){
        const j=ie_judges[idx];
        const posterStr = j.posters>0?`${j.posters} poster${j.posters!==1?"s":""} unassigned`:"no posters yet assigned";
        const sessionStr = j.sessions.length>0?j.sessions.join(", "):"unscheduled";
        return {key,type:"Judge",typeColor:"bg-violet-100 text-violet-700",name:j.name,openRole:`Judge needed — ${posterStr}`,detail:`Theme: ${j.expertise} · Session${j.sessions.length!==1?"s":""}: ${sessionStr}`};
      }
      if(tab==="sponsors"&&ie_sponsors[idx]){
        const sp=ie_sponsors[idx];
        return {key,type:"Sponsor",typeColor:"bg-amber-100 text-amber-700",name:sp.contact,openRole:`${sp.tier} sponsor gap`,detail:`AED ${sp.amount.toLocaleString()} pledged no longer secured · ${sp.company}`};
      }
      if(tab==="vips"&&ie_vips[idx]){
        const v=ie_vips[idx];
        return {key,type:"VIP",typeColor:"bg-rose-100 text-rose-700",name:v.name,openRole:"VIP slot vacant",detail:`${v.role} · ${v.org}${v.note?` · ${v.note}`:""}`};
      }
      return null;
    })
    .filter((x):x is OpenRole=>x!==null);

  return (
    <div className="space-y-5">
      <SectionHeader title="Invited Experts & Guests"
        sub={headerSub[ieTab]}
        action={headerAction[ieTab]}/>

      {/* ── Registration overview banner ── */}
      <div className={`rounded-xl border p-4 ${totalUnreg===0?"bg-emerald-50 border-emerald-200":"bg-amber-50 border-amber-200"}`}>
        <div className="flex items-start gap-3">
          <div className={`w-8 h-8 rounded-lg flex items-center justify-center flex-shrink-0 ${totalUnreg===0?"bg-emerald-100":"bg-amber-100"}`}>
            {totalUnreg===0
              ? <CheckCircle2 size={15} className="text-emerald-600"/>
              : <AlertCircle size={15} className="text-amber-600"/>
            }
          </div>
          <div className="flex-1 min-w-0">
            <div className="flex items-center justify-between gap-3 flex-wrap">
              <div>
                <p className={`text-xs font-bold ${totalUnreg===0?"text-emerald-800":"text-amber-800"}`}>
                  {totalUnreg===0
                    ? "All guests have completed registration"
                    : `${totalUnreg} guest${totalUnreg!==1?"s":""} yet to register`}
                </p>
                <p className={`text-[10px] mt-0.5 ${totalUnreg===0?"text-emerald-600":"text-amber-600"}`}>
                  {grandTotal-totalUnreg} of {grandTotal} registered across all groups
                </p>
              </div>
              {totalUnreg>0 && (
                <button className="flex items-center gap-1.5 text-[10px] font-bold px-3 py-1.5 bg-amber-600 hover:bg-amber-700 text-white rounded-lg transition-colors flex-shrink-0">
                  <Mail size={11}/>Send reminder to {totalUnreg}
                </button>
              )}
            </div>

            {/* Per-group breakdown */}
            <div className="flex flex-wrap gap-2 mt-3">
              {regGroups.map(g=>{
                const unreg = g.total - g.reg;
                return (
                  <button key={g.label} onClick={()=>setIeTab(g.tab as IeTab)}
                    className={`flex items-center gap-1.5 px-2.5 py-1.5 rounded-lg border text-[10px] font-semibold transition-colors ${
                      unreg===0
                        ?"bg-white border-gray-100 text-gray-400 hover:border-gray-200"
                        :"bg-white border-amber-200 text-gray-700 hover:border-amber-300"
                    }`}>
                    <span className={`text-[9px] font-bold px-1.5 py-0.5 rounded-full ${g.color}`}>{g.label}</span>
                    {unreg===0
                      ? <span className="text-emerald-600 font-bold">✓ all done</span>
                      : <span className="text-amber-700 font-bold">{unreg} pending</span>
                    }
                  </button>
                );
              })}
            </div>

            {/* Progress bar */}
            <div className="mt-3 space-y-1">
              <div className="h-1.5 bg-white/70 rounded-full overflow-hidden flex gap-0.5">
                {regGroups.map(g=>(
                  <div key={g.label} className="flex gap-0.5" style={{flex:g.total}}>
                    <div className="bg-emerald-400 h-full rounded-full transition-all" style={{width:`${g.total>0?(g.reg/g.total)*100:0}%`}}/>
                  </div>
                ))}
              </div>
              <div className="flex justify-between text-[9px] text-gray-400">
                <span>0%</span>
                <span className={`font-semibold ${totalUnreg===0?"text-emerald-600":"text-amber-600"}`}>
                  {Math.round(((grandTotal-totalUnreg)/grandTotal)*100)}% registered
                </span>
                <span>100%</span>
              </div>
            </div>
          </div>
        </div>
      </div>

      {/* ── Cancellations & open roles ── */}
      {cancelledRoles.length>0 && (
        <div className="bg-red-50 border border-red-200 rounded-xl overflow-hidden">
          {/* Header */}
          <div className="flex items-center justify-between px-4 py-2.5 bg-red-100/50 border-b border-red-200">
            <div className="flex items-center gap-2">
              <div className="w-5 h-5 rounded-md bg-red-500 flex items-center justify-center flex-shrink-0">
                <X size={11} className="text-white"/>
              </div>
              <p className="text-[11px] font-bold text-red-800">
                {cancelledRoles.length} cancellation{cancelledRoles.length!==1?"s":""} · open roles to fill
              </p>
            </div>
            <button onClick={()=>setIeTab("all")}
              className="text-[9px] font-bold text-red-600 hover:text-red-800 border border-red-200 px-2 py-1 rounded-lg bg-white hover:bg-red-50 transition-colors">
              View all →
            </button>
          </div>

          {/* Role rows */}
          <div className="divide-y divide-red-100">
            {cancelledRoles.map(r=>(
              <div key={r.key} className="flex items-start gap-3 px-4 py-3">
                {/* Type badge */}
                <span className={`text-[8px] font-bold px-1.5 py-0.5 rounded-full flex-shrink-0 mt-0.5 ${r.typeColor}`}>{r.type}</span>

                {/* Role info */}
                <div className="flex-1 min-w-0">
                  <div className="flex items-center gap-1.5">
                    <p className="text-[11px] font-bold text-red-800">{r.openRole}</p>
                  </div>
                  <p className="text-[10px] text-red-500 mt-0.5">{r.detail}</p>
                  <p className="text-[9px] text-gray-400 mt-0.5">Following cancellation of <span className="font-semibold">{r.name}</span></p>
                </div>

                {/* Action */}
                <button className="flex-shrink-0 text-[9px] font-bold px-2.5 py-1.5 rounded-lg bg-white border border-red-200 text-red-700 hover:bg-red-50 transition-colors whitespace-nowrap">
                  Find replacement
                </button>
              </div>
            ))}
          </div>
        </div>
      )}

      {/* Tabs */}
      <div className="flex gap-0.5 border-b border-gray-200 overflow-x-auto">
        {([
          {k:"all"      as IeTab, label:`📋 All Guests (${allTotal})`},
          {k:"speakers" as IeTab, label:`🎤 Speakers (${spkList.length})`},
          {k:"mentors"  as IeTab, label:`🎓 Mentors (${mentors.length})`},
          {k:"judges"   as IeTab, label:`⚖️ PS Judges (${ie_judges.length})`},
          {k:"sponsors" as IeTab, label:`🤝 Sponsors (${ie_sponsors.length})`},
          {k:"vips"     as IeTab, label:`⭐ VIP Guests (${ie_vips.length})`},
        ]).map(t=>(
          <button key={t.k} onClick={()=>setIeTab(t.k)}
            className={`px-3 py-2 text-xs font-medium border-b-2 -mb-px transition-colors whitespace-nowrap ${
              ieTab===t.k?"border-emerald-500 text-emerald-700":"border-transparent text-gray-500 hover:text-gray-700"
            }`}>{t.label}
          </button>
        ))}
      </div>

      {/* ── Speakers ── */}
      {ieTab==="speakers" && (
        <div className="space-y-2.5">

          {/* Form-sent banner */}
          {formSent && (
            <div className="flex items-center gap-2 px-3 py-2.5 bg-emerald-50 border border-emerald-200 rounded-xl">
              <CheckCircle2 size={13} className="text-emerald-600 flex-shrink-0"/>
              <p className="text-[11px] text-emerald-700 font-medium">Registration form link sent to the speaker's email.</p>
              <button onClick={()=>setFormSent(false)} className="ml-auto text-emerald-400 hover:text-emerald-600"><X size={12}/></button>
            </div>
          )}

          {/* Add Speaker form */}
          {showAddSpk && (
            <div className="bg-white border-2 border-emerald-200 rounded-xl overflow-hidden">
              {/* Form header */}
              <div className="px-4 py-3 bg-emerald-50 border-b border-emerald-100 flex items-center gap-2">
                <Mic2 size={13} className="text-emerald-600"/>
                <p className="text-xs font-bold text-emerald-800">New speaker details</p>
              </div>

              <div className="p-4 space-y-4">
                {/* ── Row 1: identity ── */}
                <div>
                  <p className="text-[9px] font-bold text-gray-400 uppercase tracking-wide mb-2">Speaker identity</p>
                  <div className="grid grid-cols-3 gap-3">
                    <div className="col-span-1 space-y-1">
                      <label className="text-[9px] font-bold text-gray-400 uppercase tracking-wide">Full name <span className="text-red-400">*</span></label>
                      <input value={newSpk.name} onChange={e=>setNewSpk(p=>({...p,name:e.target.value}))}
                        placeholder="e.g. Dr. Aisha Al-Mansoori"
                        className="w-full text-xs px-3 py-2 border border-gray-200 rounded-lg outline-none focus:ring-1 focus:ring-emerald-400"/>
                    </div>
                    <div className="space-y-1">
                      <label className="text-[9px] font-bold text-gray-400 uppercase tracking-wide">Organisation</label>
                      <input value={newSpk.org} onChange={e=>setNewSpk(p=>({...p,org:e.target.value}))}
                        placeholder="e.g. KAUST"
                        className="w-full text-xs px-3 py-2 border border-gray-200 rounded-lg outline-none focus:ring-1 focus:ring-emerald-400"/>
                    </div>
                    <div className="space-y-1">
                      <label className="text-[9px] font-bold text-gray-400 uppercase tracking-wide">Country</label>
                      <input value={newSpk.country} onChange={e=>setNewSpk(p=>({...p,country:e.target.value}))}
                        placeholder="e.g. SA"
                        className="w-full text-xs px-3 py-2 border border-gray-200 rounded-lg outline-none focus:ring-1 focus:ring-emerald-400"/>
                    </div>
                  </div>
                </div>

                {/* ── Row 2: talk details ── */}
                <div>
                  <p className="text-[9px] font-bold text-gray-400 uppercase tracking-wide mb-2">Talk details</p>
                  <div className="grid grid-cols-3 gap-3">
                    <div className="col-span-2 space-y-1">
                      <label className="text-[9px] font-bold text-gray-400 uppercase tracking-wide">Talk title <span className="text-red-400">*</span></label>
                      <input value={newSpk.talkTitle} onChange={e=>setNewSpk(p=>({...p,talkTitle:e.target.value}))}
                        placeholder="e.g. AI Frontiers in the Arab World"
                        className="w-full text-xs px-3 py-2 border border-gray-200 rounded-lg outline-none focus:ring-1 focus:ring-emerald-400"/>
                    </div>
                    <div className="space-y-1">
                      <label className="text-[9px] font-bold text-gray-400 uppercase tracking-wide">Talk type</label>
                      <select value={newSpk.talkType} onChange={e=>setNewSpk(p=>({...p,talkType:e.target.value}))}
                        className="w-full text-xs px-3 py-2 border border-gray-200 rounded-lg outline-none focus:ring-1 focus:ring-emerald-400 bg-white">
                        {["Keynote","Invited Talk","Panel","Workshop","Tutorial"].map(t=><option key={t} value={t.toLowerCase()}>{t}</option>)}
                      </select>
                    </div>
                  </div>
                </div>

                {/* ── Row 3: session scheduling ── */}
                <div>
                  <p className="text-[9px] font-bold text-gray-400 uppercase tracking-wide mb-2">Session scheduling</p>
                  <div className="grid grid-cols-3 gap-3">
                    <div className="space-y-1">
                      <label className="text-[9px] font-bold text-gray-400 uppercase tracking-wide">Date</label>
                      <input type="date" value={newSpk.sessionDate} onChange={e=>setNewSpk(p=>({...p,sessionDate:e.target.value}))}
                        className="w-full text-xs px-3 py-2 border border-gray-200 rounded-lg outline-none focus:ring-1 focus:ring-emerald-400 bg-white"/>
                    </div>
                    <div className="space-y-1">
                      <label className="text-[9px] font-bold text-gray-400 uppercase tracking-wide">Time slot</label>
                      <input type="time" value={newSpk.sessionTime} onChange={e=>setNewSpk(p=>({...p,sessionTime:e.target.value}))}
                        className="w-full text-xs px-3 py-2 border border-gray-200 rounded-lg outline-none focus:ring-1 focus:ring-emerald-400 bg-white"/>
                    </div>
                    <div className="space-y-1">
                      <label className="text-[9px] font-bold text-gray-400 uppercase tracking-wide">Room / hall</label>
                      <input value={newSpk.sessionRoom} onChange={e=>setNewSpk(p=>({...p,sessionRoom:e.target.value}))}
                        placeholder="e.g. Main Auditorium"
                        className="w-full text-xs px-3 py-2 border border-gray-200 rounded-lg outline-none focus:ring-1 focus:ring-emerald-400"/>
                    </div>
                  </div>
                </div>

                {/* ── Row 4: bio ── */}
                <div className="space-y-1">
                  <label className="text-[9px] font-bold text-gray-400 uppercase tracking-wide">Short bio (optional)</label>
                  <textarea value={newSpk.bio} onChange={e=>setNewSpk(p=>({...p,bio:e.target.value}))}
                    rows={2} placeholder="Brief speaker biography for the programme…"
                    className="w-full text-xs px-3 py-2 border border-gray-200 rounded-lg outline-none focus:ring-1 focus:ring-emerald-400 resize-none"/>
                </div>

                {/* ── Row 5: registration form ── */}
                <div className="bg-blue-50 border border-blue-100 rounded-xl p-3 space-y-2">
                  <div className="flex items-center gap-1.5">
                    <ExternalLink size={11} className="text-blue-500"/>
                    <p className="text-[10px] font-bold text-blue-800">Registration form</p>
                  </div>
                  <p className="text-[10px] text-blue-600">Paste your Google Form link — it will be emailed to the speaker so they can complete travel details, dietary requirements, and A/V preferences.</p>
                  <input value={newSpk.formUrl} onChange={e=>setNewSpk(p=>({...p,formUrl:e.target.value}))}
                    placeholder="https://docs.google.com/forms/d/…"
                    className="w-full text-xs px-3 py-2 border border-blue-200 rounded-lg outline-none focus:ring-1 focus:ring-blue-400 bg-white font-mono"/>
                  <label className="flex items-center gap-2 cursor-pointer">
                    <input type="checkbox" checked={newSpk.sendForm} onChange={e=>setNewSpk(p=>({...p,sendForm:e.target.checked}))}
                      className="rounded border-blue-300 text-blue-500 focus:ring-blue-400"/>
                    <span className="text-[10px] text-blue-700 font-medium">Send form link to speaker upon saving</span>
                  </label>
                </div>

                {/* ── Actions ── */}
                <div className="flex items-center gap-2 pt-1">
                  <button onClick={()=>{setShowAddSpk(false);setNewSpk(EMPTY_SPK);}}
                    className="text-[10px] font-semibold px-3 py-1.5 border border-gray-200 text-gray-500 rounded-lg hover:bg-gray-50">Discard</button>
                  <button onClick={submitSpeaker}
                    className={`ml-auto flex items-center gap-1.5 text-[10px] font-bold px-4 py-1.5 rounded-lg text-white transition-colors ${
                      newSpk.name.trim()&&newSpk.talkTitle.trim()
                        ?"bg-emerald-600 hover:bg-emerald-700"
                        :"bg-gray-300 cursor-not-allowed"
                    }`}>
                    <CheckCircle2 size={11}/>
                    {newSpk.sendForm&&newSpk.formUrl.trim()?"Save & send form":"Save speaker"}
                  </button>
                </div>
              </div>
            </div>
          )}

          {/* Speaker list */}
          {spkList.map((s,i)=>(
            <Card key={i} className="border-gray-100 shadow-none hover:shadow-sm transition-shadow">
              <CardContent className="p-3.5 flex items-center gap-4">
                <div className={`w-10 h-10 rounded-full bg-gradient-to-br ${IE_GRADIENTS[i%IE_GRADIENTS.length]} flex items-center justify-center text-white text-xs font-bold flex-shrink-0`}>
                  {s.name.split(" ").map(n=>n[0]).join("").slice(0,2)}
                </div>
                <div className="flex-1 min-w-0">
                  <div className="text-xs font-semibold text-gray-800">{s.name}</div>
                  <div className="text-[11px] text-gray-500 mt-0.5">{s.org} · {s.topic}</div>
                </div>
                <span className="text-[11px] text-gray-400">{s.country}</span>
                <Pill label={s.status} color={IE_STATUS_PILL[s.status]??IE_STATUS_PILL.invited}/>
                <RegBadge tab="speakers" idx={i}/>
                <div className="flex gap-1.5">
                  <button className="text-gray-400 hover:text-gray-600"><Mail size={13}/></button>
                  <button className="text-gray-400 hover:text-gray-600"><Edit size={13}/></button>
                </div>
              </CardContent>
            </Card>
          ))}
        </div>
      )}

      {/* ── Mentors ── */}
      {ieTab==="mentors" && (
        <div className="space-y-3">
          {mentors.map((m,i)=>(
            <Card key={i} className="border-gray-100 shadow-none">
              <CardContent className="p-4 flex items-center gap-4">
                <div className="w-10 h-10 rounded-full bg-gradient-to-br from-teal-400 to-emerald-500 flex items-center justify-center text-white text-xs font-bold flex-shrink-0">
                  {m.name.split(" ").map(n=>n[0]).join("").slice(0,2)}
                </div>
                <div className="flex-1 min-w-0">
                  <div className="text-xs font-semibold text-gray-800">{m.name}</div>
                  <div className="text-[11px] text-gray-500 mt-0.5">{m.org} · {m.expertise}</div>
                </div>
                <div className="text-right">
                  <div className="text-sm font-bold text-gray-900">{m.booked}<span className="text-xs font-normal text-gray-400">/{m.slots}</span></div>
                  <div className="text-[10px] text-gray-400">slots booked</div>
                </div>
                <div className="w-20">
                  <div className="w-full h-1.5 bg-gray-100 rounded-full overflow-hidden">
                    <div className={`h-full rounded-full ${m.booked===m.slots?"bg-red-400":"bg-teal-400"}`} style={{width:`${(m.booked/m.slots)*100}%`}}/>
                  </div>
                </div>
                <Pill label={m.booked===m.slots?"full":"open"} color={m.booked===m.slots?"bg-red-100 text-red-600":"bg-teal-100 text-teal-700"}/>
                <RegBadge tab="mentors" idx={i}/>
              </CardContent>
            </Card>
          ))}
        </div>
      )}

      {/* ── Poster Session Judges ── */}
      {ieTab==="judges" && (
        <div className="space-y-2.5">
          <div className="flex items-center gap-2 px-3 py-2 bg-violet-50 border border-violet-100 rounded-lg">
            <Info size={12} className="text-violet-500 flex-shrink-0"/>
            <p className="text-[10px] text-violet-700">Judges are assigned to evaluate poster submissions and submit scores via the rubric form. Session availability is managed in the Poster Session workflow.</p>
          </div>
          {ie_judges.map((j,i)=>(
            <Card key={i} className="border-gray-100 shadow-none hover:shadow-sm transition-shadow">
              <CardContent className="p-4 flex items-center gap-4">
                <div className={`w-10 h-10 rounded-full bg-gradient-to-br ${j.grad} flex items-center justify-center text-white text-xs font-bold flex-shrink-0`}>
                  {j.name.split(" ").map(n=>n[0]).join("").slice(0,2)}
                </div>
                <div className="flex-1 min-w-0">
                  <div className="text-xs font-semibold text-gray-800">{j.name}</div>
                  <div className="text-[11px] text-gray-500 mt-0.5">{j.org} · {j.expertise}</div>
                  {j.sessions.length>0 && (
                    <div className="flex gap-1 mt-1">
                      {j.sessions.map(s=>(
                        <span key={s} className="text-[9px] font-bold px-1.5 py-0.5 bg-violet-100 text-violet-700 rounded-full">{s}</span>
                      ))}
                      <span className="text-[9px] text-gray-400">{j.posters} poster{j.posters!==1?"s":""} assigned</span>
                    </div>
                  )}
                </div>
                <Pill label={j.status} color={IE_STATUS_PILL[j.status]??IE_STATUS_PILL.invited}/>
                <RegBadge tab="judges" idx={i}/>
                <div className="flex gap-1.5">
                  <button className="text-gray-400 hover:text-gray-600"><Mail size={13}/></button>
                  <button className="text-gray-400 hover:text-gray-600"><Edit size={13}/></button>
                </div>
              </CardContent>
            </Card>
          ))}
        </div>
      )}

      {/* ── Sponsors ── */}
      {ieTab==="sponsors" && (
        <div className="space-y-3">
          {/* Tier summary */}
          <div className="grid grid-cols-3 gap-2">
            {(["Gold","Silver","Bronze"] as const).map(tier=>{
              const ts = ie_sponsors.filter(s=>s.tier===tier);
              const total = ts.reduce((s,x)=>s+x.amount,0);
              return (
                <div key={tier} className={`border-l-4 ${TIER_STYLE[tier].border} bg-white border border-gray-100 rounded-xl p-3`}>
                  <p className={`text-[9px] font-bold px-1.5 py-0.5 rounded-full border inline-block mb-1.5 ${TIER_STYLE[tier].chip}`}>{tier}</p>
                  <p className="text-sm font-bold text-gray-800">{ts.length} sponsor{ts.length!==1?"s":""}</p>
                  <p className="text-[10px] text-gray-500">AED {total.toLocaleString()}</p>
                </div>
              );
            })}
          </div>

          {ie_sponsors.map((sp,i)=>(
            <Card key={i} className={`border-gray-100 shadow-none hover:shadow-sm transition-shadow border-l-4 ${TIER_STYLE[sp.tier].border}`}>
              <CardContent className="p-4 flex items-center gap-4">
                <div className={`w-10 h-10 rounded-xl bg-gradient-to-br ${sp.grad} flex items-center justify-center text-white text-xs font-bold flex-shrink-0`}>
                  {sp.company.slice(0,2).toUpperCase()}
                </div>
                <div className="flex-1 min-w-0">
                  <div className="flex items-center gap-2">
                    <div className="text-xs font-bold text-gray-800">{sp.company}</div>
                    <span className={`text-[9px] font-bold px-1.5 py-0.5 rounded-full border ${TIER_STYLE[sp.tier].chip}`}>{sp.tier}</span>
                  </div>
                  <div className="text-[11px] text-gray-500 mt-0.5">{sp.contact} · {sp.role}</div>
                </div>
                <div className="text-right">
                  <p className="text-xs font-bold text-gray-800">AED {sp.amount.toLocaleString()}</p>
                  <p className="text-[10px] text-gray-400">{sp.country}</p>
                </div>
                <Pill label={sp.status} color={IE_STATUS_PILL[sp.status]??IE_STATUS_PILL.invited}/>
                <RegBadge tab="sponsors" idx={i}/>
                <div className="flex gap-1.5">
                  <button className="text-gray-400 hover:text-gray-600"><Mail size={13}/></button>
                  <button className="text-gray-400 hover:text-gray-600"><Edit size={13}/></button>
                </div>
              </CardContent>
            </Card>
          ))}
        </div>
      )}

      {/* ── VIP Guests ── */}
      {ieTab==="vips" && (
        <div className="space-y-2.5">
          <div className="flex items-center gap-2 px-3 py-2 bg-amber-50 border border-amber-100 rounded-lg">
            <AlertCircle size={12} className="text-amber-500 flex-shrink-0"/>
            <p className="text-[10px] text-amber-700">VIP guests require dedicated liaison and protocol briefing. Coordinate with the event host team for airport transfers and seating arrangements.</p>
          </div>
          {ie_vips.map((v,i)=>(
            <Card key={i} className="border-gray-100 shadow-none hover:shadow-sm transition-shadow">
              <CardContent className="p-4 flex items-center gap-4">
                <div className={`w-10 h-10 rounded-full bg-gradient-to-br ${IE_GRADIENTS[(i+2)%IE_GRADIENTS.length]} flex items-center justify-center text-white text-xs font-bold flex-shrink-0`}>
                  {v.name.replace(/^H\.E\.\s+|^Dr\.\s+|^Eng\.\s+/,"").split(" ").map(n=>n[0]).join("").slice(0,2)}
                </div>
                <div className="flex-1 min-w-0">
                  <div className="flex items-center gap-1.5">
                    <span className="text-amber-400 text-xs">⭐</span>
                    <div className="text-xs font-bold text-gray-800">{v.name}</div>
                  </div>
                  <div className="text-[11px] text-gray-500 mt-0.5">{v.role} · {v.org}</div>
                  {v.note && <div className="text-[10px] text-gray-400 mt-0.5 italic">{v.note}</div>}
                </div>
                <span className="text-[11px] text-gray-400 flex-shrink-0">{v.country}</span>
                <Pill label={v.status} color={IE_STATUS_PILL[v.status]??IE_STATUS_PILL.invited}/>
                <RegBadge tab="vips" idx={i}/>
                <div className="flex gap-1.5">
                  <button className="text-gray-400 hover:text-gray-600"><Mail size={13}/></button>
                  <button className="text-gray-400 hover:text-gray-600"><Edit size={13}/></button>
                </div>
              </CardContent>
            </Card>
          ))}
        </div>
      )}

      {/* ── All Guests ── */}
      {ieTab==="all" && (()=>{
        const TYPE_BADGE:{[k:string]:string} = {
          Speaker: "bg-purple-100 text-purple-700 border-purple-200",
          Mentor:  "bg-teal-100 text-teal-700 border-teal-200",
          Judge:   "bg-violet-100 text-violet-700 border-violet-200",
          Sponsor: "bg-amber-100 text-amber-700 border-amber-200",
          VIP:     "bg-rose-100 text-rose-700 border-rose-200",
        };
        const rows:{tab:string;idx:number;avatar:string;name:string;sub:string;country:string;status:string;type:string;grad:string}[] = [
          ...spkList.map((s,i)=>({tab:"speakers",idx:i,avatar:s.name.split(" ").map(n=>n[0]).join("").slice(0,2),name:s.name,sub:`${s.org} · ${s.topic}`,country:s.country,status:s.status,type:"Speaker",grad:IE_GRADIENTS[i%IE_GRADIENTS.length]})),
          ...mentors.map((m,i)=>({tab:"mentors",idx:i,avatar:m.name.split(" ").map(n=>n[0]).join("").slice(0,2),name:m.name,sub:`${m.org} · ${m.expertise}`,country:"—",status:m.booked===m.slots?"full":"open",type:"Mentor",grad:"from-teal-400 to-emerald-500"})),
          ...ie_judges.map((j,i)=>({tab:"judges",idx:i,avatar:j.name.split(" ").map(n=>n[0]).join("").slice(0,2),name:j.name,sub:`${j.org} · ${j.expertise}`,country:"—",status:j.status,type:"Judge",grad:j.grad})),
          ...ie_sponsors.map((sp,i)=>({tab:"sponsors",idx:i,avatar:sp.company.slice(0,2).toUpperCase(),name:sp.contact,sub:`${sp.company} · ${sp.role}`,country:sp.country,status:sp.status,type:"Sponsor",grad:sp.grad})),
          ...ie_vips.map((v,i)=>({tab:"vips",idx:i,avatar:v.name.replace(/^H\.E\.\s+|^Dr\.\s+|^Eng\.\s+/,"").split(" ").map(n=>n[0]).join("").slice(0,2),name:v.name,sub:`${v.role} · ${v.org}`,country:v.country,status:v.status,type:"VIP",grad:IE_GRADIENTS[(i+2)%IE_GRADIENTS.length]})),
        ];
        const isCanc  = (r:{tab:string;idx:number}) => !!cancelled[`${r.tab}-${r.idx}`];
        const activeRows = rows.filter(r=>!isCanc(r));
        const cancRows   = rows.filter(r=>isCanc(r));
        const regCount   = activeRows.filter(r=>!!regDone[`${r.tab}-${r.idx}`]).length;

        function GuestRow({r, idx}:{r:typeof rows[0]; idx:number}){
          const isCancelled = isCanc(r);
          return (
            <tr key={`${r.tab}-${r.idx}`}
              className={`border-b border-gray-50 transition-colors ${
                isCancelled
                  ?"bg-red-50/40 opacity-60"
                  :idx%2===0?"bg-white":"bg-gray-50/30"
              }`}>
              <td className="px-4 py-2.5">
                <div className="flex items-center gap-2.5">
                  <div className={`w-7 h-7 rounded-full bg-gradient-to-br ${r.grad} flex items-center justify-center text-white text-[9px] font-bold flex-shrink-0 ${isCancelled?"grayscale":""}`}>
                    {r.avatar}
                  </div>
                  <span className={`text-[11px] font-semibold ${isCancelled?"line-through text-gray-400":"text-gray-800"}`}>{r.name}</span>
                </div>
              </td>
              <td className="px-3 py-2.5">
                <span className={`text-[10px] line-clamp-1 ${isCancelled?"text-gray-300":"text-gray-500"}`}>{r.sub}</span>
              </td>
              <td className="px-3 py-2.5 text-center">
                {isCancelled
                  ? <span className="text-[9px] font-bold px-1.5 py-0.5 rounded-full border bg-red-50 text-red-400 border-red-200">Cancelled</span>
                  : <span className={`text-[9px] font-bold px-1.5 py-0.5 rounded-full border ${TYPE_BADGE[r.type]}`}>{r.type}</span>
                }
              </td>
              <td className={`px-3 py-2.5 text-center text-[10px] ${isCancelled?"text-gray-300":"text-gray-400"}`}>{r.country}</td>
              <td className="px-3 py-2.5 text-center">
                {!isCancelled && <Pill label={r.status} color={IE_STATUS_PILL[r.status]??IE_STATUS_PILL.invited}/>}
              </td>
              <td className="px-3 py-2.5 text-center">
                {!isCancelled && <RegBadge tab={r.tab} idx={r.idx}/>}
              </td>
              <td className="px-3 py-2.5 text-right">
                <div className="flex items-center justify-end gap-1.5">
                  {!isCancelled && <button className="text-gray-400 hover:text-gray-600"><Mail size={12}/></button>}
                  <button onClick={()=>toggleCancel(r.tab,r.idx)}
                    className={`text-[9px] font-bold px-2 py-1 rounded-lg border transition-colors whitespace-nowrap ${
                      isCancelled
                        ?"border-gray-200 text-gray-500 hover:bg-gray-50"
                        :"border-red-200 text-red-500 hover:bg-red-50"
                    }`}>
                    {isCancelled?"Restore":"Cancel"}
                  </button>
                </div>
              </td>
            </tr>
          );
        }

        return (
          <div className="space-y-3">
            {/* Summary stat row */}
            <div className="grid grid-cols-5 gap-2">
              {(["Speaker","Mentor","Judge","Sponsor","VIP"] as const).map(type=>{
                const typeRows = activeRows.filter(r=>r.type===type);
                const typeReg  = typeRows.filter(r=>!!regDone[`${r.tab}-${r.idx}`]).length;
                return (
                  <div key={type} className="bg-white border border-gray-100 rounded-xl p-3 text-center">
                    <p className="text-lg font-bold text-gray-800">{typeRows.length}</p>
                    <span className={`text-[9px] font-bold px-1.5 py-0.5 rounded-full border inline-block mt-0.5 mb-1 ${TYPE_BADGE[type]}`}>{type}s</span>
                    <p className="text-[9px] text-gray-400">{typeReg}/{typeRows.length} registered</p>
                  </div>
                );
              })}
            </div>

            {/* Progress bar */}
            <div className="bg-white border border-gray-100 rounded-xl p-3 space-y-1.5">
              <div className="flex justify-between text-[10px]">
                <span className="font-semibold text-gray-600">Overall registration progress</span>
                <span className="font-bold text-emerald-700">{regCount} / {activeRows.length} registered</span>
              </div>
              <div className="h-2 bg-gray-100 rounded-full overflow-hidden">
                <div className="h-full bg-emerald-400 rounded-full transition-all"
                  style={{width:`${activeRows.length>0?Math.round((regCount/activeRows.length)*100):0}%`}}/>
              </div>
              <p className="text-[9px] text-gray-400">
                {activeRows.length>0?Math.round((regCount/activeRows.length)*100):0}% complete
                {cancRows.length>0 && <span className="ml-2 text-red-400">· {cancRows.length} cancelled</span>}
              </p>
            </div>

            {/* Master table */}
            <div className="bg-white border border-gray-200 rounded-xl overflow-hidden">
              <table className="w-full text-xs">
                <thead>
                  <tr className="bg-gray-50 border-b border-gray-100">
                    <th className="text-left px-4 py-2.5 text-[9px] font-bold text-gray-400 uppercase tracking-wide">Name</th>
                    <th className="text-left px-3 py-2.5 text-[9px] font-bold text-gray-400 uppercase tracking-wide">Role / Organisation</th>
                    <th className="text-center px-3 py-2.5 text-[9px] font-bold text-gray-400 uppercase tracking-wide">Type</th>
                    <th className="text-center px-3 py-2.5 text-[9px] font-bold text-gray-400 uppercase tracking-wide">Country</th>
                    <th className="text-center px-3 py-2.5 text-[9px] font-bold text-gray-400 uppercase tracking-wide">Status</th>
                    <th className="text-center px-3 py-2.5 text-[9px] font-bold text-gray-400 uppercase tracking-wide">Registration</th>
                    <th className="text-center px-3 py-2.5 text-[9px] font-bold text-gray-400 uppercase tracking-wide">Action</th>
                  </tr>
                </thead>
                <tbody>
                  {activeRows.map((r,idx)=><GuestRow key={`${r.tab}-${r.idx}`} r={r} idx={idx}/>)}
                  {cancRows.length>0 && (
                    <tr className="border-b border-gray-50">
                      <td colSpan={7} className="px-4 py-1.5 bg-red-50/30">
                        <p className="text-[9px] font-bold text-red-400 uppercase tracking-wide">{cancRows.length} cancelled</p>
                      </td>
                    </tr>
                  )}
                  {cancRows.map((r,idx)=><GuestRow key={`${r.tab}-${r.idx}-canc`} r={r} idx={idx}/>)}
                </tbody>
                <tfoot>
                  <tr className="border-t border-gray-200 bg-gray-50">
                    <td colSpan={4} className="px-4 py-2 text-[10px] font-semibold text-gray-500">{activeRows.length} active · {cancRows.length} cancelled</td>
                    <td className="px-3 py-2 text-center text-[10px] font-bold text-emerald-700" colSpan={2}>{regCount} registered</td>
                    <td/>
                  </tr>
                </tfoot>
              </table>
            </div>
          </div>
        );
      })()}
    </div>
  );
}

