function MentorRoundTablesPage() {
  // ── state ──────────────────────────────────────────────────────────────────
  const [mentors]      = useState<RegMentor[]>(INIT_REG_MENTORS);
  const [sessions,     setSessions]  = useState<MRTSess[]>(INIT_MRT_SESS);
  const [topics,       setTopics]    = useState<MRTTopic[]>(INIT_MRT_TOPICS);
  const [matches,      setMatches]   = useState<MRTMatch[]>(INIT_MRT_MATCHES);
  const [mrStep,       setMrStep]    = useState<1|2|3>(1);
  const [selSessId,    setSelSessId] = useState("s1");
  const [mentorsOpen,  setMentorsOpen]  = useState(true);
  const [showSessForm, setShowSessForm] = useState(false);
  const [editSessId,   setEditSessId]   = useState<string|null>(null);
  const [sessDraft,    setSessDraft]    = useState<Omit<MRTSess,"id">>(BLANK_SESS);
  const [showTopicForm,setShowTopicForm]= useState(false);
  const [editTopicId,  setEditTopicId]  = useState<string|null>(null);
  const [topicDraft,   setTopicDraft]   = useState(BLANK_TOPIC_D);
  const [genSessIds,   setGenSessIds]   = useState<Set<string>>(new Set(["s1","s2"]));
  const [showGenModal, setShowGenModal] = useState(false);
  const [genLoading,   setGenLoading]   = useState(false);
  const [genPhase,     setGenPhase]     = useState(0); // 0=scanning 1=clustering 2=ranking
  const [genSuggs,     setGenSuggs]     = useState<{topic:string;interest:number;careers:Record<string,number>}[]>([]);
  const [genSelected,  setGenSelected]  = useState<Set<number>>(new Set());
  const [autoFlash,    setAutoFlash]    = useState(false);

  // ── derived ────────────────────────────────────────────────────────────────
  const selSess       = sessions.find(s=>s.id===selSessId) || sessions[0];
  const sessTopics    = topics.filter(t=>t.sessId===selSessId).sort((a,b)=>a.tableNum-b.tableNum);
  const totalTables   = selSess?.numTables ?? 0;
  const topicsCount   = sessTopics.length;
  const tableSlack    = totalTables - topicsCount; // positive = unfilled slots; negative = over capacity
  const sessDate      = selSess?.date ?? "";
  const availMentors  = mentors.filter(m=>m.avail.includes(sessDate));
  const unmatchedTopics = sessTopics.filter(t=>!matches.find(m=>m.topicId===t.id&&m.mentorId));

  function mentorAlloc(mid:string) {
    return matches.filter(m=>sessTopics.some(t=>t.id===m.topicId)&&m.mentorId===mid).length;
  }

  // ── session handlers ───────────────────────────────────────────────────────
  function openAddSess()      { setSessDraft({...BLANK_SESS}); setEditSessId(null); setShowSessForm(true); }
  function openEditSess(s:MRTSess) { setSessDraft({name:s.name,date:s.date,time:s.time,location:s.location,numTables:s.numTables,studentsPerTable:s.studentsPerTable}); setEditSessId(s.id); setShowSessForm(true); }
  function saveSess() {
    if(editSessId) setSessions(ss=>ss.map(s=>s.id===editSessId?{...sessDraft,id:editSessId}:s));
    else { const nid="s"+Date.now(); setSessions(ss=>[...ss,{...sessDraft,id:nid}]); }
    setShowSessForm(false);
  }

  // ── topic handlers ─────────────────────────────────────────────────────────
  function openAddTopic()            { setTopicDraft({...BLANK_TOPIC_D}); setEditTopicId(null); setShowTopicForm(true); }
  function openEditTopic(t:MRTTopic) { setTopicDraft({topic:t.topic,interest:t.interest}); setEditTopicId(t.id); setShowTopicForm(true); }
  function saveTopic() {
    if(editTopicId) { setTopics(ts=>ts.map(t=>t.id===editTopicId?{...t,...topicDraft}:t)); }
    else {
      const nextNum = sessTopics.length + 1;
      const nid="tp"+Date.now();
      setTopics(ts=>[...ts,{...topicDraft,id:nid,sessId:selSessId,tableNum:nextNum,source:"manual"}]);
      setMatches(ms=>[...ms,{topicId:nid,mentorId:null}]);
    }
    setShowTopicForm(false);
  }
  function generateTopics() {
    if(genSessIds.has(selSessId)) return;
    // Aggregate topic preferences from registration forms for this session
    const sessRegs = INIT_MRT_REGS.filter(r=>r.sessId===selSessId);
    const topicMap:Record<string,{count:number;careers:Record<string,number>}> = {};
    for(const reg of sessRegs) {
      for(const pref of reg.prefs) {
        if(!topicMap[pref]) topicMap[pref]={count:0,careers:{}};
        topicMap[pref].count++;
        topicMap[pref].careers[reg.career]=(topicMap[pref].careers[reg.career]||0)+1;
      }
    }
    const sorted = Object.entries(topicMap)
      .map(([topic,{count,careers}])=>({topic,interest:count,careers}))
      .sort((a,b)=>b.interest-a.interest);
    setGenSuggs(sorted);
    // Pre-select the top N topics matching the session's table count
    setGenSelected(new Set(sorted.slice(0,totalTables).map((_,i)=>i)));
    setGenPhase(0);
    setGenLoading(true);
    setShowGenModal(true);
    // Animate through analysis phases, then reveal results
    setTimeout(()=>setGenPhase(1), 600);
    setTimeout(()=>setGenPhase(2), 1200);
    setTimeout(()=>{ setGenLoading(false); setGenPhase(3); }, 1900);
  }

  function confirmGenTopics() {
    const toAdd = genSuggs.filter((_,i)=>genSelected.has(i));
    const base = sessTopics.length;
    const newTopics:MRTTopic[] = toAdd.map((s,i)=>({
      id:"gn"+Date.now()+"_"+i,
      sessId:selSessId,
      tableNum:base+i+1,
      topic:s.topic,
      interest:s.interest,
      source:"generated" as const,
    }));
    setTopics(ts=>[...ts,...newTopics]);
    setMatches(ms=>[...ms,...newTopics.map(t=>({topicId:t.id,mentorId:null}))]);
    setGenSessIds(s=>new Set([...s,selSessId]));
    setShowGenModal(false);
  }

  // ── match handlers ─────────────────────────────────────────────────────────
  function setMatchMentor(topicId:string, mentorId:string|null) {
    setMatches(ms=>{ const ex=ms.find(m=>m.topicId===topicId); return ex?ms.map(m=>m.topicId===topicId?{...m,mentorId}:m):[...ms,{topicId,mentorId}]; });
  }
  function autoMatch() {
    const KW:Record<string,string[]> = {m1:["phd","vision","deep"],m2:["llm","language","nlp","career"],m3:["women","linguistics"],m4:["llm","language","industry"],m5:["startup","venture","mena","business"],m6:["phd","research","writing","publishing","machine"],m7:["women","vision"],m8:["academia","industry","knowledge"]};
    setMatches(ms=>ms.map(m=>{
      const topic=topics.find(t=>t.id===m.topicId);
      if(!topic||m.mentorId) return m;
      const tl=topic.topic.toLowerCase();
      for(const [mid,kws] of Object.entries(KW)){
        const mn=mentors.find(x=>x.id===mid);
        if(!mn||!mn.avail.includes(sessDate)) continue;
        if(kws.some(kw=>tl.includes(kw))&&mentorAlloc(mid)<mn.maxTables) return {...m,mentorId:mid};
      }
      return m;
    }));
    setAutoFlash(true); setTimeout(()=>setAutoFlash(false),2500);
  }

  // ── missing profiles ───────────────────────────────────────────────────────
  const missingProfiles = [...new Set(unmatchedTopics.flatMap(t=>{
    const tl=t.topic.toLowerCase();
    if(tl.includes("rl")||tl.includes("robotics")) return ["RL / Robotics practitioner"];
    if(tl.includes("social")||tl.includes("policy")) return ["AI Policy / Social good researcher"];
    if(tl.includes("career")||tl.includes("industry")) return ["Industry AI professional"];
    return ["Expert in: "+t.topic.split(" ").slice(0,4).join(" ")];
  }))];

  // ── render ─────────────────────────────────────────────────────────────────
  return (
    <div className="space-y-4">
      <SectionHeader title="Mentorship Round Tables" sub="Structured small-group mentoring sessions during conference lunch breaks"/>

      {/* ── Registered Mentors panel ─────────────────────────────────────── */}
      <div className="bg-white border border-gray-100 rounded-xl overflow-hidden">
        <button onClick={()=>setMentorsOpen(o=>!o)}
          className="w-full flex items-center justify-between px-4 py-3 hover:bg-gray-50 transition-colors">
          <div className="flex items-center gap-2">
            <Users size={14} className="text-emerald-600"/>
            <span className="text-xs font-bold text-gray-800">Registered Mentors</span>
            <span className="text-[10px] text-gray-400">({mentors.length} people opted in as mentors)</span>
          </div>
          <ChevronDown size={13} className={`text-gray-400 transition-transform ${mentorsOpen?"rotate-180":""}`}/>
        </button>
        {mentorsOpen && (
          <div className="border-t border-gray-100 overflow-x-auto">
            <table className="w-full text-[10px] border-collapse min-w-[780px]">
              <thead>
                <tr className="bg-gray-50 border-b border-gray-100 text-gray-500 font-semibold text-left">
                  <th className="px-3 py-2">Name</th>
                  <th className="px-3 py-2">Organisation</th>
                  <th className="px-3 py-2">Other roles</th>
                  <th className="px-3 py-2">Expertise</th>
                  <th className="px-3 py-2">Available</th>
                  <th className="px-3 py-2 text-center">Max tables</th>
                </tr>
              </thead>
              <tbody className="divide-y divide-gray-50">
                {mentors.map(m=>(
                  <tr key={m.id} className="hover:bg-gray-50 transition-colors">
                    <td className="px-3 py-2 font-semibold text-gray-800 whitespace-nowrap">{m.name}</td>
                    <td className="px-3 py-2 text-gray-500 whitespace-nowrap">{m.org}</td>
                    <td className="px-3 py-2">
                      <div className="flex flex-wrap gap-1">
                        {m.roles.map(r=><span key={r} className={`text-[8px] font-bold px-1.5 py-0.5 rounded-full ${MRT_ROLE_CLS[r]}`}>{r}</span>)}
                      </div>
                    </td>
                    <td className="px-3 py-2">
                      <div className="flex flex-wrap gap-1">
                        {m.expertise.map(e=><span key={e} className="text-[8px] px-1.5 py-0.5 rounded-full bg-slate-100 text-slate-600">{e}</span>)}
                      </div>
                    </td>
                    <td className="px-3 py-2 text-gray-500 whitespace-nowrap">{m.avail.join(", ")}</td>
                    <td className="px-3 py-2 text-center font-bold text-gray-700">{m.maxTables}</td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        )}
      </div>

      {/* ── Step tabs ────────────────────────────────────────────────────── */}
      <div className="flex items-center gap-0 bg-gray-100 rounded-xl p-1">
        {([{n:1,label:"1 · Add Sessions"},{n:2,label:"2 · Topics"},{n:3,label:"3 · Match Mentors"}] as {n:1|2|3,label:string}[]).map(({n,label})=>(
          <button key={n} onClick={()=>setMrStep(n)}
            className={`flex-1 py-1.5 text-[10px] font-bold rounded-lg transition-colors ${mrStep===n?"bg-white text-emerald-700 shadow-sm":"text-gray-500 hover:text-gray-700"}`}>{label}</button>
        ))}
      </div>

      {/* ══════════════════════════════════════════════════════════════════ */}
      {/* STEP 1 – Sessions                                                */}
      {/* ══════════════════════════════════════════════════════════════════ */}
      {mrStep===1 && (
        <div className="space-y-3">
          <div className="flex items-center justify-between">
            <p className="text-[10px] text-gray-500">Define the mentorship sessions (time blocks). Topics and mentor assignments are set in the next steps.</p>
            <button onClick={openAddSess} className="flex items-center gap-1 px-3 py-1.5 bg-emerald-600 hover:bg-emerald-700 text-white text-[10px] font-bold rounded-lg transition-colors"><Plus size={11}/>Add Session</button>
          </div>
          <div className="bg-white border border-gray-100 rounded-xl overflow-hidden">
            <table className="w-full text-[10px] border-collapse">
              <thead>
                <tr className="bg-gray-50 border-b border-gray-100 text-gray-500 font-semibold text-left">
                  <th className="px-3 py-2.5">Session name</th>
                  <th className="px-3 py-2.5">Date</th>
                  <th className="px-3 py-2.5">Time</th>
                  <th className="px-3 py-2.5">Location</th>
                  <th className="px-3 py-2.5 text-center">Tables</th>
                  <th className="px-3 py-2.5 text-center">Students/table</th>
                  <th className="px-3 py-2.5 text-center">Total capacity</th>
                  <th className="px-3 py-2.5 text-center">Topics</th>
                  <th className="px-3 py-2.5 w-14"/>
                </tr>
              </thead>
              <tbody className="divide-y divide-gray-50">
                {sessions.map(s=>{
                  const tcount=topics.filter(t=>t.sessId===s.id).length;
                  return (
                    <tr key={s.id} className="hover:bg-gray-50 transition-colors">
                      <td className="px-3 py-2.5 font-semibold text-gray-800">{s.name}</td>
                      <td className="px-3 py-2.5 text-gray-500 font-mono whitespace-nowrap">{s.date}</td>
                      <td className="px-3 py-2.5 text-gray-500 font-mono whitespace-nowrap">{s.time}</td>
                      <td className="px-3 py-2.5 text-gray-500">{s.location}</td>
                      <td className="px-3 py-2.5 text-center font-bold text-gray-700">{s.numTables}</td>
                      <td className="px-3 py-2.5 text-center text-gray-600">{s.studentsPerTable}</td>
                      <td className="px-3 py-2.5 text-center font-bold text-emerald-600">{s.numTables*s.studentsPerTable}</td>
                      <td className="px-3 py-2.5 text-center">
                        <span className={`font-bold ${tcount===0?"text-gray-300":tcount<=s.numTables?"text-emerald-600":"text-amber-600"}`}>{tcount}</span>
                      </td>
                      <td className="px-3 py-2.5">
                        <div className="flex gap-2 justify-end">
                          <button onClick={()=>openEditSess(s)} className="text-gray-400 hover:text-emerald-600 transition-colors"><Edit size={12}/></button>
                          <button onClick={()=>{setSessions(ss=>ss.filter(x=>x.id!==s.id));setTopics(ts=>ts.filter(t=>t.sessId!==s.id));setMatches(ms=>ms.filter(m=>!topics.filter(t=>t.sessId===s.id).some(t=>t.id===m.topicId)));}} className="text-gray-400 hover:text-red-400 transition-colors"><Trash2 size={12}/></button>
                        </div>
                      </td>
                    </tr>
                  );
                })}
                {sessions.length===0&&<tr><td colSpan={9} className="px-4 py-8 text-center text-gray-400">No sessions yet. Add one to get started.</td></tr>}
              </tbody>
            </table>
          </div>
          {/* Add/edit session modal */}
          {showSessForm&&(
            <div className="fixed inset-0 z-50 flex items-center justify-center" style={{background:"rgba(0,0,0,0.4)"}}>
              <div className="bg-white rounded-2xl shadow-2xl w-full max-w-lg mx-4 overflow-hidden">
                <div className="flex items-center justify-between px-5 py-3.5 bg-emerald-50 border-b border-emerald-100">
                  <p className="text-sm font-bold text-emerald-900">{editSessId?"Edit Session":"Add Session"}</p>
                  <button onClick={()=>setShowSessForm(false)} className="text-gray-400 hover:text-gray-600">✕</button>
                </div>
                <div className="p-5 space-y-3">
                  <div>
                    <label className="block text-[10px] font-bold text-gray-600 mb-1">Session name *</label>
                    <input value={sessDraft.name} onChange={e=>setSessDraft(d=>({...d,name:e.target.value}))} placeholder="e.g. Day 1 Mentorship Lunch"
                      className="w-full text-xs px-3 py-2 border border-gray-200 rounded-lg focus:outline-none focus:border-emerald-400"/>
                  </div>
                  <div className="grid grid-cols-2 gap-3">
                    <div>
                      <label className="block text-[10px] font-bold text-gray-600 mb-1">Date</label>
                      <select value={sessDraft.date} onChange={e=>setSessDraft(d=>({...d,date:e.target.value}))}
                        className="w-full text-xs px-2 py-2 border border-gray-200 rounded-lg focus:outline-none focus:border-emerald-400 bg-white">
                        {["Apr 15","Apr 16","Apr 17","Apr 18"].map(d=><option key={d}>{d}</option>)}
                      </select>
                    </div>
                    <div>
                      <label className="block text-[10px] font-bold text-gray-600 mb-1">Time</label>
                      <input value={sessDraft.time} onChange={e=>setSessDraft(d=>({...d,time:e.target.value}))} placeholder="12:30–13:30"
                        className="w-full text-xs px-3 py-2 border border-gray-200 rounded-lg focus:outline-none focus:border-emerald-400"/>
                    </div>
                  </div>
                  <div>
                    <label className="block text-[10px] font-bold text-gray-600 mb-1">Location</label>
                    <input value={sessDraft.location} onChange={e=>setSessDraft(d=>({...d,location:e.target.value}))} placeholder="Conference Lobby"
                      className="w-full text-xs px-3 py-2 border border-gray-200 rounded-lg focus:outline-none focus:border-emerald-400"/>
                  </div>
                  <div className="grid grid-cols-2 gap-3">
                    <div>
                      <label className="block text-[10px] font-bold text-gray-600 mb-1">Number of tables</label>
                      <input type="number" min={1} value={sessDraft.numTables} onChange={e=>setSessDraft(d=>({...d,numTables:+e.target.value}))}
                        className="w-full text-xs px-3 py-2 border border-gray-200 rounded-lg focus:outline-none focus:border-emerald-400 text-center"/>
                    </div>
                    <div>
                      <label className="block text-[10px] font-bold text-gray-600 mb-1">Students per table</label>
                      <input type="number" min={1} value={sessDraft.studentsPerTable} onChange={e=>setSessDraft(d=>({...d,studentsPerTable:+e.target.value}))}
                        className="w-full text-xs px-3 py-2 border border-gray-200 rounded-lg focus:outline-none focus:border-emerald-400 text-center"/>
                    </div>
                  </div>
                </div>
                <div className="flex gap-3 justify-end px-5 py-3.5 bg-gray-50 border-t border-gray-100">
                  <button onClick={()=>setShowSessForm(false)} className="px-4 py-2 text-xs font-semibold text-gray-600 bg-white border border-gray-200 rounded-lg hover:bg-gray-100">Cancel</button>
                  <button onClick={saveSess} disabled={!sessDraft.name.trim()}
                    className={`px-5 py-2 text-xs font-bold rounded-lg transition-colors ${sessDraft.name.trim()?"bg-emerald-600 hover:bg-emerald-700 text-white":"bg-gray-200 text-gray-400 cursor-not-allowed"}`}>
                    {editSessId?"Save Changes":"Add Session"}
                  </button>
                </div>
              </div>
            </div>
          )}
        </div>
      )}

      {/* ══════════════════════════════════════════════════════════════════ */}
      {/* STEP 2 – Topics                                                  */}
      {/* ══════════════════════════════════════════════════════════════════ */}
      {mrStep===2 && (
        <div className="space-y-3">
          {/* session picker + generate button */}
          <div className="flex items-center gap-3 flex-wrap">
            <div className="flex items-center gap-2">
              <label className="text-[10px] font-bold text-gray-600 whitespace-nowrap">Session:</label>
              <select value={selSessId} onChange={e=>setSelSessId(e.target.value)}
                className="text-xs px-2 py-1.5 border border-gray-200 rounded-lg focus:outline-none focus:border-emerald-400 bg-white">
                {sessions.map(s=><option key={s.id} value={s.id}>{s.name} ({s.date})</option>)}
              </select>
            </div>
            <button onClick={generateTopics}
              className={`flex items-center gap-1.5 px-3 py-1.5 text-[10px] font-bold rounded-lg transition-colors ${genSessIds.has(selSessId)?"bg-gray-100 text-gray-400 cursor-not-allowed":"bg-violet-600 hover:bg-violet-700 text-white"}`}
              disabled={genSessIds.has(selSessId)}>
              <Zap size={10}/>{genSessIds.has(selSessId)?"Topics generated":"Generate from registrations"}
            </button>
            <button onClick={openAddTopic} className="flex items-center gap-1 px-3 py-1.5 text-[10px] font-bold bg-emerald-600 hover:bg-emerald-700 text-white rounded-lg transition-colors"><Plus size={11}/>Add topic</button>
          </div>

          {/* stat pills */}
          <div className="flex gap-2 flex-wrap items-center">
            {[
              {label:"Topics assigned",  val:topicsCount,  cls:"bg-violet-50 text-violet-700 border-violet-200"},
              {label:"Tables in session",val:totalTables,  cls:"bg-blue-50 text-blue-700 border-blue-200"},
              {label:tableSlack<0?"Over capacity":tableSlack===0?"Full":"Unfilled slots", val:Math.abs(tableSlack),
               cls:tableSlack<0?"bg-red-50 text-red-600 border-red-200":tableSlack===0?"bg-emerald-50 text-emerald-700 border-emerald-200":"bg-amber-50 text-amber-700 border-amber-200"},
            ].map(p=>(
              <div key={p.label} className={`border rounded-xl px-3 py-1.5 flex items-center gap-2 ${p.cls}`}>
                <span className="text-base font-bold">{p.val}</span>
                <span className="text-[9px] font-semibold">{p.label}</span>
              </div>
            ))}
            {tableSlack<0&&<span className="flex items-center gap-1 text-[9px] text-red-500"><AlertTriangle size={10}/>{Math.abs(tableSlack)} topic{Math.abs(tableSlack)>1?"s":""} exceed table count — remove topics or increase session size.</span>}
            {tableSlack>0&&<span className="text-[9px] text-amber-600">{tableSlack} table{tableSlack>1?"s":""} still need a topic assigned.</span>}
            {tableSlack===0&&topicsCount>0&&<span className="text-[9px] text-emerald-600 font-semibold">All tables have topics.</span>}
          </div>

          {/* topics table */}
          <div className="bg-white border border-gray-100 rounded-xl overflow-hidden">
            <table className="w-full text-[10px] border-collapse">
              <thead>
                <tr className="bg-gray-50 border-b border-gray-100 text-gray-500 font-semibold text-left">
                  <th className="px-3 py-2.5 w-14 text-center">Table #</th>
                  <th className="px-3 py-2.5 flex-1">Topic</th>
                  <th className="px-3 py-2.5 w-36">Registrant interest</th>
                  <th className="px-3 py-2.5 w-24">Source</th>
                  <th className="px-3 py-2.5 w-14"/>
                </tr>
              </thead>
              <tbody className="divide-y divide-gray-50">
                {sessTopics.map(t=>(
                  <tr key={t.id} className="hover:bg-gray-50 transition-colors">
                    <td className="px-3 py-2.5 text-center font-bold text-gray-400">#{t.tableNum}</td>
                    <td className="px-3 py-2.5 font-semibold text-gray-800">{t.topic}</td>
                    <td className="px-3 py-2.5">
                      <div className="flex items-center gap-2">
                        <div className="flex-1 h-1.5 bg-gray-100 rounded-full overflow-hidden">
                          <div className="h-full bg-violet-400 rounded-full" style={{width:`${Math.min(100,t.interest*1.5)}%`}}/>
                        </div>
                        <span className="font-mono text-gray-600 w-6 text-right">{t.interest}</span>
                      </div>
                    </td>
                    <td className="px-3 py-2.5">
                      <span className={`text-[8px] font-bold px-1.5 py-0.5 rounded-full ${t.source==="generated"?"bg-violet-100 text-violet-700":"bg-emerald-100 text-emerald-700"}`}>{t.source}</span>
                    </td>
                    <td className="px-3 py-2.5">
                      <div className="flex gap-2 justify-end">
                        <button onClick={()=>openEditTopic(t)} className="text-gray-400 hover:text-emerald-600"><Edit size={12}/></button>
                        <button onClick={()=>setTopics(ts=>ts.filter(x=>x.id!==t.id))} className="text-gray-400 hover:text-red-400"><Trash2 size={12}/></button>
                      </div>
                    </td>
                  </tr>
                ))}
                {sessTopics.length===0&&<tr><td colSpan={5} className="px-4 py-8 text-center text-gray-400">No topics yet — generate from registrations or add manually.</td></tr>}
              </tbody>
            </table>
          </div>

          {/* add/edit topic modal */}
          {showTopicForm&&(
            <div className="fixed inset-0 z-50 flex items-center justify-center" style={{background:"rgba(0,0,0,0.4)"}}>
              <div className="bg-white rounded-2xl shadow-2xl w-full max-w-sm mx-4 overflow-hidden">
                <div className="flex items-center justify-between px-5 py-3.5 bg-violet-50 border-b border-violet-100">
                  <p className="text-sm font-bold text-violet-900">{editTopicId?"Edit Topic":"Add Topic"}</p>
                  <button onClick={()=>setShowTopicForm(false)} className="text-gray-400 hover:text-gray-600">✕</button>
                </div>
                <div className="p-5 space-y-3">
                  <div>
                    <label className="block text-[10px] font-bold text-gray-600 mb-1">Topic *</label>
                    <input value={topicDraft.topic} onChange={e=>setTopicDraft(d=>({...d,topic:e.target.value}))} placeholder="e.g. Getting into a PhD in ML/AI"
                      className="w-full text-xs px-3 py-2 border border-gray-200 rounded-lg focus:outline-none focus:border-violet-400"/>
                  </div>
                  <div>
                    <label className="block text-[10px] font-bold text-gray-600 mb-1">Interest (registrants)</label>
                    <input type="number" min={0} value={topicDraft.interest} onChange={e=>setTopicDraft(d=>({...d,interest:+e.target.value}))}
                      className="w-full text-xs px-3 py-2 border border-gray-200 rounded-lg focus:outline-none focus:border-violet-400 text-center"/>
                  </div>
                  {!editTopicId && (
                    <p className="text-[9px] text-gray-400">Topic will be assigned to table #{sessTopics.length+1} in this session.</p>
                  )}
                </div>
                <div className="flex gap-3 justify-end px-5 py-3.5 bg-gray-50 border-t border-gray-100">
                  <button onClick={()=>setShowTopicForm(false)} className="px-4 py-2 text-xs font-semibold text-gray-600 bg-white border border-gray-200 rounded-lg hover:bg-gray-100">Cancel</button>
                  <button onClick={saveTopic} disabled={!topicDraft.topic.trim()}
                    className={`px-5 py-2 text-xs font-bold rounded-lg transition-colors ${topicDraft.topic.trim()?"bg-violet-600 hover:bg-violet-700 text-white":"bg-gray-200 text-gray-400 cursor-not-allowed"}`}>
                    {editTopicId?"Save Changes":"Add Topic"}
                  </button>
                </div>
              </div>
            </div>
          )}

          {/* ── Generate-topics modal ─────────────────────────────────── */}
          {showGenModal&&(
            <div className="fixed inset-0 z-50 flex items-center justify-center" style={{background:"rgba(0,0,0,0.45)"}}>
              <div className="bg-white rounded-2xl shadow-2xl w-full max-w-lg mx-4 overflow-hidden flex flex-col">

                {/* header */}
                <div className="flex items-center justify-between px-5 py-3.5 bg-violet-600 text-white">
                  <div className="flex items-center gap-2">
                    <Zap size={14}/>
                    <p className="text-sm font-bold">Generate Topics from Registration Forms</p>
                  </div>
                  {!genLoading&&<button onClick={()=>setShowGenModal(false)} className="text-white/70 hover:text-white text-lg leading-none">✕</button>}
                </div>

                {/* body */}
                {genLoading ? (
                  <div className="p-8 flex flex-col items-center gap-6">
                    <div className="w-12 h-12 rounded-full border-4 border-violet-200 border-t-violet-600 animate-spin"/>
                    <div className="w-full space-y-3">
                      {[
                        {label:`Scanning ${INIT_MRT_REGS.filter(r=>r.sessId===selSessId).length} registration forms…`, phase:0},
                        {label:"Clustering topic preferences…",  phase:1},
                        {label:"Ranking by interest score…",     phase:2},
                      ].map(step=>(
                        <div key={step.label} className={`flex items-center gap-3 transition-opacity duration-500 ${genPhase>=step.phase?"opacity-100":"opacity-25"}`}>
                          <div className={`w-4 h-4 rounded-full flex-shrink-0 flex items-center justify-center ${genPhase>step.phase?"bg-violet-600":genPhase===step.phase?"bg-violet-300 animate-pulse":"bg-gray-200"}`}>
                            {genPhase>step.phase&&<span className="text-white text-[8px] font-bold">✓</span>}
                          </div>
                          <span className={`text-xs ${genPhase>=step.phase?"text-gray-800 font-medium":"text-gray-400"}`}>{step.label}</span>
                        </div>
                      ))}
                    </div>
                  </div>
                ) : (
                  <div className="overflow-y-auto" style={{maxHeight:"420px"}}>
                    {/* context bar */}
                    <div className="px-5 py-3 bg-violet-50 border-b border-violet-100 flex items-center gap-3">
                      <span className="text-[10px] text-violet-700 font-semibold">
                        {INIT_MRT_REGS.filter(r=>r.sessId===selSessId).length} registrants analysed
                      </span>
                      <span className="text-violet-300">·</span>
                      <span className="text-[10px] text-violet-700">{selSess?.name}</span>
                      <span className="ml-auto text-[9px] text-violet-500">Top {totalTables} pre-selected to fill {totalTables} tables</span>
                    </div>

                    {/* results table */}
                    {genSuggs.length===0 ? (
                      <div className="p-8 text-center text-gray-400 text-xs">No registration data for this session yet.</div>
                    ) : (
                      <table className="w-full text-[10px] border-collapse">
                        <thead>
                          <tr className="bg-gray-50 border-b border-gray-100 text-gray-500 font-semibold text-left">
                            <th className="px-3 py-2.5 w-8"/>
                            <th className="px-3 py-2.5">Suggested topic</th>
                            <th className="px-3 py-2.5 w-24">Interest</th>
                            <th className="px-3 py-2.5 w-32">Career mix</th>
                          </tr>
                        </thead>
                        <tbody className="divide-y divide-gray-50">
                          {genSuggs.map((s,i)=>{
                            const checked=genSelected.has(i);
                            const topCareer=Object.entries(s.careers).sort((a,b)=>b[1]-a[1]).slice(0,2);
                            return (
                              <tr key={s.topic} className={`hover:bg-gray-50 transition-colors ${checked?"":"opacity-50"}`}>
                                <td className="px-3 py-2.5 text-center">
                                  <input type="checkbox" checked={checked} onChange={()=>{
                                    setGenSelected(prev=>{
                                      const next=new Set(prev);
                                      checked?next.delete(i):next.add(i);
                                      return next;
                                    });
                                  }} className="accent-violet-600 w-3.5 h-3.5 cursor-pointer"/>
                                </td>
                                <td className="px-3 py-2.5 font-semibold text-gray-800">{s.topic}</td>
                                <td className="px-3 py-2.5">
                                  <div className="flex items-center gap-2">
                                    <div className="flex-1 h-1.5 bg-gray-100 rounded-full overflow-hidden">
                                      <div className="h-full bg-violet-400 rounded-full transition-all" style={{width:`${Math.min(100,(s.interest/genSuggs[0].interest)*100)}%`}}/>
                                    </div>
                                    <span className="font-mono text-gray-600 w-4 text-right">{s.interest}</span>
                                  </div>
                                </td>
                                <td className="px-3 py-2.5">
                                  <div className="flex flex-wrap gap-0.5">
                                    {topCareer.map(([career,cnt])=>(
                                      <span key={career} className={`text-[7px] font-bold px-1.5 py-0.5 rounded-full ${MRT_CAREER_CLS[career]}`}>
                                        {MRT_CAREER_LABEL[career]} ×{cnt}
                                      </span>
                                    ))}
                                  </div>
                                </td>
                              </tr>
                            );
                          })}
                        </tbody>
                      </table>
                    )}
                  </div>
                )}

                {/* footer */}
                {!genLoading&&(
                  <div className="flex items-center justify-between px-5 py-3.5 bg-gray-50 border-t border-gray-100">
                    <span className="text-[10px] text-gray-500">{genSelected.size} topic{genSelected.size!==1?"s":""} selected</span>
                    <div className="flex gap-3">
                      <button onClick={()=>setShowGenModal(false)} className="px-4 py-2 text-xs font-semibold text-gray-600 bg-white border border-gray-200 rounded-lg hover:bg-gray-100">Cancel</button>
                      <button onClick={confirmGenTopics} disabled={genSelected.size===0}
                        className={`px-5 py-2 text-xs font-bold rounded-lg transition-colors ${genSelected.size>0?"bg-violet-600 hover:bg-violet-700 text-white":"bg-gray-200 text-gray-400 cursor-not-allowed"}`}>
                        Add {genSelected.size} topic{genSelected.size!==1?"s":""}
                      </button>
                    </div>
                  </div>
                )}
              </div>
            </div>
          )}

        </div>
      )}

      {/* ══════════════════════════════════════════════════════════════════ */}
      {/* STEP 3 – Match Mentors                                           */}
      {/* ══════════════════════════════════════════════════════════════════ */}
      {mrStep===3 && (
        <div className="space-y-3">
          {/* session picker + auto-match */}
          <div className="flex items-center gap-3 flex-wrap">
            <div className="flex items-center gap-2">
              <label className="text-[10px] font-bold text-gray-600 whitespace-nowrap">Session:</label>
              <select value={selSessId} onChange={e=>setSelSessId(e.target.value)}
                className="text-xs px-2 py-1.5 border border-gray-200 rounded-lg focus:outline-none focus:border-emerald-400 bg-white">
                {sessions.map(s=><option key={s.id} value={s.id}>{s.name} ({s.date})</option>)}
              </select>
            </div>
            <button onClick={autoMatch}
              className={`flex items-center gap-1.5 px-3 py-1.5 text-[10px] font-bold rounded-lg transition-colors ${autoFlash?"bg-emerald-600 text-white":"bg-violet-600 hover:bg-violet-700 text-white"}`}>
              <Zap size={10}/>{autoFlash?"Matched!":"Auto-match available mentors"}
            </button>
          </div>

          {/* stat pills */}
          <div className="flex gap-2 flex-wrap">
            {[
              {label:"Topics",    val:sessTopics.length,               cls:"bg-gray-50 text-gray-700 border-gray-200"},
              {label:"Matched",   val:sessTopics.length-unmatchedTopics.length, cls:"bg-emerald-50 text-emerald-700 border-emerald-200"},
              {label:"Unmatched", val:unmatchedTopics.length,          cls:unmatchedTopics.length>0?"bg-red-50 text-red-600 border-red-200":"bg-emerald-50 text-emerald-700 border-emerald-200"},
              {label:"Available mentors", val:availMentors.length,     cls:"bg-blue-50 text-blue-700 border-blue-200"},
            ].map(p=>(
              <div key={p.label} className={`border rounded-xl px-3 py-1.5 flex items-center gap-2 ${p.cls}`}>
                <span className="text-base font-bold">{p.val}</span>
                <span className="text-[9px] font-semibold">{p.label}</span>
              </div>
            ))}
          </div>

          {/* matching table */}
          <div className="bg-white border border-gray-100 rounded-xl overflow-hidden">
            <table className="w-full text-[10px] border-collapse min-w-[620px]">
              <thead>
                <tr className="bg-gray-50 border-b border-gray-100 text-gray-500 font-semibold text-left">
                  <th className="px-3 py-2.5 w-14 text-center">Table #</th>
                  <th className="px-3 py-2.5">Topic</th>
                  <th className="px-3 py-2.5 w-52">Assigned mentor</th>
                  <th className="px-3 py-2.5 w-40">Expertise match</th>
                  <th className="px-3 py-2.5 w-24 text-center">Status</th>
                </tr>
              </thead>
              <tbody className="divide-y divide-gray-50">
                {sessTopics.map(t=>{
                  const matchRec = matches.find(m=>m.topicId===t.id);
                  const mid      = matchRec?.mentorId ?? null;
                  const mentor   = mid ? mentors.find(m=>m.id===mid) : null;
                  const overAlloc= mid ? mentorAlloc(mid) > (mentor?.maxTables??1) : false;
                  const notAvail = mid && mentor && !mentor.avail.includes(sessDate);
                  return (
                    <tr key={t.id} className={`hover:bg-gray-50 transition-colors ${!mid?"bg-red-50/40":""}`}>
                      <td className="px-3 py-2.5 text-center font-bold text-gray-400">#{t.tableNum}</td>
                      <td className="px-3 py-2.5 font-semibold text-gray-800">{t.topic}</td>
                      <td className="px-3 py-2.5">
                        <select value={mid??""} onChange={e=>setMatchMentor(t.id,e.target.value||null)}
                          className="w-full text-[10px] px-2 py-1 border border-gray-200 rounded-lg focus:outline-none focus:border-emerald-400 bg-white">
                          <option value="">— unassigned —</option>
                          {availMentors.map(m=>(
                            <option key={m.id} value={m.id}>{m.name} ({m.org}) [{mentorAlloc(m.id)}/{m.maxTables}]</option>
                          ))}
                          {mid&&!availMentors.find(m=>m.id===mid)&&mentor&&<option value={mid}>{mentor.name} ⚠ not available</option>}
                        </select>
                      </td>
                      <td className="px-3 py-2.5">
                        {mentor ? (
                          <div className="flex flex-wrap gap-0.5">
                            {mentor.expertise.map(e=><span key={e} className="text-[8px] px-1 py-0.5 rounded bg-slate-100 text-slate-600">{e}</span>)}
                          </div>
                        ) : <span className="text-gray-300">—</span>}
                      </td>
                      <td className="px-3 py-2.5 text-center">
                        {!mid
                          ? <span className="text-[8px] font-bold px-1.5 py-0.5 rounded-full bg-red-100 text-red-600">Unmatched</span>
                          : overAlloc
                            ? <span className="text-[8px] font-bold px-1.5 py-0.5 rounded-full bg-amber-100 text-amber-600">Over limit</span>
                            : notAvail
                              ? <span className="text-[8px] font-bold px-1.5 py-0.5 rounded-full bg-amber-100 text-amber-600">Not available</span>
                              : <span className="text-[8px] font-bold px-1.5 py-0.5 rounded-full bg-emerald-100 text-emerald-700">Matched</span>
                        }
                      </td>
                    </tr>
                  );
                })}
                {sessTopics.length===0&&<tr><td colSpan={5} className="px-4 py-8 text-center text-gray-400">No topics defined for this session. Go to Step 2 to add topics.</td></tr>}
              </tbody>
            </table>
          </div>

          {/* Missing mentors summary */}
          {unmatchedTopics.length>0 && (
            <div className="bg-amber-50 border border-amber-200 rounded-xl p-4 space-y-2">
              <div className="flex items-center gap-2">
                <AlertTriangle size={13} className="text-amber-600"/>
                <p className="text-xs font-bold text-amber-800">{unmatchedTopics.length} topic{unmatchedTopics.length>1?"s":""} still need a mentor</p>
              </div>
              <p className="text-[10px] text-amber-700"><strong>{unmatchedTopics.length} table{unmatchedTopics.length>1?"s":""}</strong> on <strong>{sessDate}</strong> have no mentor assigned yet.</p>
              <div className="space-y-1">
                <p className="text-[9px] font-bold text-amber-700 uppercase tracking-wide">Suggested profiles to recruit:</p>
                <ul className="space-y-0.5">
                  {missingProfiles.map((p,i)=>(
                    <li key={i} className="flex items-center gap-1.5 text-[10px] text-amber-800">
                      <span className="w-1 h-1 rounded-full bg-amber-500 flex-shrink-0"/>
                      {p}
                    </li>
                  ))}
                </ul>
              </div>
            </div>
          )}
          {unmatchedTopics.length===0&&sessTopics.length>0&&(
            <div className="bg-emerald-50 border border-emerald-200 rounded-xl px-4 py-3 flex items-center gap-2">
              <Check size={13} className="text-emerald-600"/>
              <p className="text-xs font-semibold text-emerald-700">All topics are matched for this session.</p>
            </div>
          )}
        </div>
      )}
    </div>
  );
}

function SocialEventsPage() {
  const [seEvents,     setSeEvents]     = useState(SOCIAL_EVENTS);
  const [expanded,     setExpanded]     = useState<string|null>(null);
  const [invitesSent,  setInvitesSent]  = useState<Record<string,boolean>>({});
  const [audiences,    setAudiences]    = useState<Record<string,string[]>>(INIT_EVENT_AUDIENCES);
  const [showForm,     setShowForm]     = useState(false);
  const [draft,        setDraft]        = useState<SocialEventDraft>(BLANK_DRAFT);
  const [formErrors,   setFormErrors]   = useState<Partial<Record<keyof SocialEventDraft,string>>>({});

  const totalRsvp = seEvents.reduce((s,e)=>s+e.rsvp,0);
  const totalCap  = seEvents.reduce((s,e)=>s+e.capacity,0);

  function toggleLabel(eventId:string, key:string) {
    setAudiences(prev=>{
      const cur = prev[eventId] ?? [];
      return {...prev, [eventId]: cur.includes(key) ? cur.filter(k=>k!==key) : [...cur,key]};
    });
  }

  function setField<K extends keyof SocialEventDraft>(k:K, v:SocialEventDraft[K]) {
    setDraft(d=>({...d,[k]:v}));
    setFormErrors(e=>({...e,[k]:undefined}));
  }

  function saveEvent() {
    const errs: Partial<Record<keyof SocialEventDraft,string>> = {};
    if(!draft.name.trim())     errs.name     = "Name is required";
    if(!draft.date.trim())     errs.date     = "Date is required";
    if(!draft.time.trim())     errs.time     = "Time is required";
    if(!draft.venue.trim())    errs.venue    = "Venue is required";
    if(!draft.location.trim()) errs.location = "Location is required";
    if(!draft.capacity.trim()||isNaN(+draft.capacity)||+draft.capacity<1) errs.capacity = "Enter a valid capacity";
    if(Object.keys(errs).length) { setFormErrors(errs); return; }

    const newId = `SE-0${seEvents.length+1}`;
    const newEv = {
      id: newId, name:draft.name.trim(),
      date:draft.date.trim(), time:draft.time.trim(),
      venue:draft.venue.trim(), location:draft.location.trim(),
      type:draft.type, dressCode:draft.dressCode, status:draft.status,
      capacity:+draft.capacity, rsvp:0,
      description:draft.description.trim(),
      notes:draft.notes.trim(),
      costs:draft.costs
        .filter(r=>r.category.trim())
        .map(r=>({category:r.category.trim(), amount:+r.amount||0})),
    };
    setSeEvents(ev=>[...ev,newEv]);
    setAudiences(a=>({...a,[newId]:[]}));
    setDraft(BLANK_DRAFT);
    setFormErrors({});
    setShowForm(false);
    setExpanded(newId);
  }

  return (
    <div className="space-y-4">
      <SectionHeader title="Social Events"
        sub="Conference receptions, dinners, and networking sessions"
        action={
          <Button size="sm" onClick={()=>{setShowForm(s=>!s);setDraft(BLANK_DRAFT);setFormErrors({});}}
            className={`text-xs gap-1.5 ${showForm?"bg-gray-200 hover:bg-gray-300 text-gray-700":"bg-emerald-600 hover:bg-emerald-700 text-white"}`}>
            {showForm ? <><X size={13}/>Cancel</> : <><Plus size={13}/>Add Event</>}
          </Button>
        }/>

      {/* Stats */}
      <div className="grid grid-cols-4 gap-2">
        {[
          {l:"Events",       n:seEvents.length,                                            sub:"across 4 days",       txt:"text-gray-800",   bg:"bg-gray-50",   border:"border-gray-200"},
          {l:"Confirmed",    n:seEvents.filter(e=>e.status==="confirmed").length,           sub:`of ${seEvents.length} events`,    txt:"text-emerald-700",bg:"bg-emerald-50",border:"border-emerald-200"},
          {l:"Total RSVPs",  n:totalRsvp,                                                  sub:`of ${totalCap} seats`,txt:"text-blue-700",   bg:"bg-blue-50",   border:"border-blue-200"},
          {l:"Avg Fill Rate",n:totalCap>0?`${Math.round((totalRsvp/totalCap)*100)}%`:"—", sub:"across all events",   txt:"text-violet-700", bg:"bg-violet-50", border:"border-violet-200"},
        ].map(s=>(
          <div key={s.l} className={`border ${s.border} ${s.bg} rounded-xl p-3`}>
            <p className={`text-2xl font-bold ${s.txt}`}>{s.n}</p>
            <p className="text-[11px] font-medium text-gray-700 mt-0.5">{s.l}</p>
            <p className="text-[10px] text-gray-400 mt-0.5">{s.sub}</p>
          </div>
        ))}
      </div>

      {/* ── Add Event Form ── */}
      {showForm && (
        <div className="bg-white border-2 border-emerald-200 rounded-2xl overflow-hidden shadow-sm">
          {/* Form header */}
          <div className="flex items-center justify-between px-5 py-3.5 bg-gradient-to-r from-emerald-50 to-teal-50 border-b border-emerald-100">
            <div className="flex items-center gap-2">
              <div className="w-7 h-7 rounded-lg bg-emerald-600 flex items-center justify-center"><Plus size={14} className="text-white"/></div>
              <p className="text-sm font-bold text-gray-800">New Social Event</p>
            </div>
            <button onClick={()=>setShowForm(false)} className="text-gray-400 hover:text-gray-600"><X size={15}/></button>
          </div>

          <div className="p-5 space-y-4">
            {/* Event type pills */}
            <div className="space-y-1.5">
              <label className="text-[10px] font-bold text-gray-500 uppercase tracking-wide">Event type</label>
              <div className="flex gap-2 flex-wrap">
                {(["reception","dinner","mixer","celebration"] as SocialEventType[]).map(t=>{
                  const ts = SE_TYPE_STYLE[t];
                  return (
                    <button key={t} onClick={()=>setField("type",t)}
                      className={`flex items-center gap-1.5 px-3 py-1.5 rounded-lg border text-[10px] font-bold capitalize transition-all ${
                        draft.type===t ? `${ts.bg} ${ts.text} border-transparent shadow-sm` : "bg-white text-gray-500 border-gray-200 hover:border-gray-300"
                      }`}>
                      {SE_ICONS[t]} {ts.label}
                    </button>
                  );
                })}
              </div>
            </div>

            {/* Name + Status row */}
            <div className="grid grid-cols-3 gap-3">
              <div className="col-span-2 space-y-1">
                <label className="text-[10px] font-bold text-gray-500 uppercase tracking-wide">Event name *</label>
                <input value={draft.name} onChange={e=>setField("name",e.target.value)} placeholder="e.g. Welcome Reception"
                  className={`w-full text-xs px-3 py-2 border rounded-lg outline-none focus:ring-1 focus:ring-emerald-400 ${formErrors.name?"border-red-300 bg-red-50":"border-gray-200"}`}/>
                {formErrors.name && <p className="text-[9px] text-red-500">{formErrors.name}</p>}
              </div>
              <div className="space-y-1">
                <label className="text-[10px] font-bold text-gray-500 uppercase tracking-wide">Status</label>
                <div className="flex gap-1.5 pt-1">
                  {(["planning","confirmed"] as const).map(s=>(
                    <button key={s} onClick={()=>setField("status",s)}
                      className={`flex-1 text-[10px] font-bold py-1.5 rounded-lg border capitalize transition-all ${
                        draft.status===s
                          ? s==="confirmed"?"bg-emerald-100 text-emerald-700 border-emerald-200":"bg-amber-100 text-amber-700 border-amber-200"
                          : "bg-white text-gray-500 border-gray-200"
                      }`}>{s}</button>
                  ))}
                </div>
              </div>
            </div>

            {/* Date / Time / Dress code */}
            <div className="grid grid-cols-3 gap-3">
              <div className="space-y-1">
                <label className="text-[10px] font-bold text-gray-500 uppercase tracking-wide">Date *</label>
                <input value={draft.date} onChange={e=>setField("date",e.target.value)} placeholder="e.g. Apr 15"
                  className={`w-full text-xs px-3 py-2 border rounded-lg outline-none focus:ring-1 focus:ring-emerald-400 ${formErrors.date?"border-red-300 bg-red-50":"border-gray-200"}`}/>
                {formErrors.date && <p className="text-[9px] text-red-500">{formErrors.date}</p>}
              </div>
              <div className="space-y-1">
                <label className="text-[10px] font-bold text-gray-500 uppercase tracking-wide">Time *</label>
                <input value={draft.time} onChange={e=>setField("time",e.target.value)} placeholder="e.g. 19:00–21:00"
                  className={`w-full text-xs px-3 py-2 border rounded-lg outline-none focus:ring-1 focus:ring-emerald-400 ${formErrors.time?"border-red-300 bg-red-50":"border-gray-200"}`}/>
                {formErrors.time && <p className="text-[9px] text-red-500">{formErrors.time}</p>}
              </div>
              <div className="space-y-1">
                <label className="text-[10px] font-bold text-gray-500 uppercase tracking-wide">Dress code</label>
                <select value={draft.dressCode} onChange={e=>setField("dressCode",e.target.value)}
                  className="w-full text-xs px-3 py-2 border border-gray-200 rounded-lg outline-none focus:ring-1 focus:ring-emerald-400 bg-white">
                  {["Casual","Smart Casual","Business Casual","Formal","Black Tie"].map(d=><option key={d}>{d}</option>)}
                </select>
              </div>
            </div>

            {/* Venue / Location / Capacity */}
            <div className="grid grid-cols-3 gap-3">
              <div className="space-y-1">
                <label className="text-[10px] font-bold text-gray-500 uppercase tracking-wide">Venue *</label>
                <input value={draft.venue} onChange={e=>setField("venue",e.target.value)} placeholder="e.g. Rooftop Lounge"
                  className={`w-full text-xs px-3 py-2 border rounded-lg outline-none focus:ring-1 focus:ring-emerald-400 ${formErrors.venue?"border-red-300 bg-red-50":"border-gray-200"}`}/>
                {formErrors.venue && <p className="text-[9px] text-red-500">{formErrors.venue}</p>}
              </div>
              <div className="space-y-1">
                <label className="text-[10px] font-bold text-gray-500 uppercase tracking-wide">Location / Building *</label>
                <input value={draft.location} onChange={e=>setField("location",e.target.value)} placeholder="e.g. DWTC"
                  className={`w-full text-xs px-3 py-2 border rounded-lg outline-none focus:ring-1 focus:ring-emerald-400 ${formErrors.location?"border-red-300 bg-red-50":"border-gray-200"}`}/>
                {formErrors.location && <p className="text-[9px] text-red-500">{formErrors.location}</p>}
              </div>
              <div className="space-y-1">
                <label className="text-[10px] font-bold text-gray-500 uppercase tracking-wide">Capacity *</label>
                <input value={draft.capacity} onChange={e=>setField("capacity",e.target.value)} placeholder="e.g. 150" type="number" min={1}
                  className={`w-full text-xs px-3 py-2 border rounded-lg outline-none focus:ring-1 focus:ring-emerald-400 ${formErrors.capacity?"border-red-300 bg-red-50":"border-gray-200"}`}/>
                {formErrors.capacity && <p className="text-[9px] text-red-500">{formErrors.capacity}</p>}
              </div>
            </div>

            {/* Description */}
            <div className="space-y-1">
              <label className="text-[10px] font-bold text-gray-500 uppercase tracking-wide">Description</label>
              <textarea value={draft.description} onChange={e=>setField("description",e.target.value)}
                placeholder="Brief description of the event, agenda, or highlights…"
                rows={2} className="w-full text-xs px-3 py-2 border border-gray-200 rounded-lg outline-none focus:ring-1 focus:ring-emerald-400 resize-none"/>
            </div>

            {/* Notes */}
            <div className="space-y-1">
              <label className="text-[10px] font-bold text-gray-500 uppercase tracking-wide">Internal notes</label>
              <input value={draft.notes} onChange={e=>setField("notes",e.target.value)} placeholder="e.g. Invite-only, dietary restrictions collected, AV setup needed…"
                className="w-full text-xs px-3 py-2 border border-gray-200 rounded-lg outline-none focus:ring-1 focus:ring-emerald-400"/>
            </div>

            {/* Cost breakdown */}
            <div className="space-y-2 border-t border-gray-100 pt-3">
              <div className="flex items-center justify-between">
                <div>
                  <label className="text-[10px] font-bold text-gray-500 uppercase tracking-wide">Cost breakdown</label>
                  {draft.costs.length>0 && (
                    <span className="ml-2 text-[10px] font-semibold text-gray-700">
                      Total: <span className="text-emerald-700">AED {draft.costs.reduce((s,r)=>s+(+r.amount||0),0).toLocaleString()}</span>
                    </span>
                  )}
                </div>
                <button
                  onClick={()=>setField("costs",[...draft.costs,{id:`cr-${Date.now()}`,category:"",amount:""}])}
                  className="flex items-center gap-1 text-[10px] font-bold text-emerald-700 bg-emerald-50 hover:bg-emerald-100 border border-emerald-200 px-2.5 py-1 rounded-lg transition-colors">
                  <Plus size={10}/>Add item
                </button>
              </div>

              {draft.costs.length===0 && (
                <div className="flex items-center gap-2 px-3 py-3 bg-gray-50 border border-dashed border-gray-200 rounded-lg">
                  <DollarSign size={13} className="text-gray-300"/>
                  <p className="text-[10px] text-gray-400">No cost items yet — click "Add item" to break down the budget for this event.</p>
                </div>
              )}

              {draft.costs.length>0 && (
                <div className="border border-gray-200 rounded-xl overflow-hidden">
                  {/* column headers */}
                  <div className="grid grid-cols-[1fr_120px_28px] gap-0 bg-gray-50 border-b border-gray-100 px-3 py-1.5">
                    <p className="text-[9px] font-bold text-gray-400 uppercase tracking-wide">Category</p>
                    <p className="text-[9px] font-bold text-gray-400 uppercase tracking-wide text-right pr-1">Amount (AED)</p>
                    <span/>
                  </div>
                  <div className="divide-y divide-gray-50">
                    {draft.costs.map((row,ri)=>(
                      <div key={row.id} className="grid grid-cols-[1fr_120px_28px] gap-0 items-center px-3 py-1.5 bg-white group">
                        <input
                          value={row.category}
                          onChange={ev=>setField("costs",draft.costs.map((r,i)=>i===ri?{...r,category:ev.target.value}:r))}
                          placeholder="e.g. Catering & Drinks"
                          className="text-[11px] border-0 outline-none bg-transparent text-gray-800 placeholder:text-gray-300 pr-2"/>
                        <input
                          value={row.amount}
                          onChange={ev=>setField("costs",draft.costs.map((r,i)=>i===ri?{...r,amount:ev.target.value}:r))}
                          placeholder="0" type="number" min={0}
                          className="text-[11px] border-0 outline-none bg-transparent text-right font-mono text-gray-800 placeholder:text-gray-300 pr-1"/>
                        <button
                          onClick={()=>setField("costs",draft.costs.filter((_,i)=>i!==ri))}
                          className="w-5 h-5 flex items-center justify-center text-gray-300 hover:text-red-400 rounded transition-colors ml-auto">
                          <X size={10}/>
                        </button>
                      </div>
                    ))}
                  </div>
                  {/* total row */}
                  <div className="grid grid-cols-[1fr_120px_28px] gap-0 bg-gray-50 border-t border-gray-200 px-3 py-2">
                    <p className="text-[10px] font-bold text-gray-600">Total</p>
                    <p className="text-[11px] font-bold text-gray-800 text-right font-mono pr-1">
                      AED {draft.costs.reduce((s,r)=>s+(+r.amount||0),0).toLocaleString()}
                    </p>
                    <span/>
                  </div>
                </div>
              )}
            </div>

            {/* Actions */}
            <div className="flex items-center gap-2 pt-1 border-t border-gray-100">
              <button onClick={saveEvent}
                className="flex items-center gap-1.5 text-[11px] font-bold px-4 py-2 bg-emerald-600 hover:bg-emerald-700 text-white rounded-lg transition-colors">
                <CheckCircle2 size={12}/>Save Event
              </button>
              <button onClick={()=>{setShowForm(false);setDraft(BLANK_DRAFT);setFormErrors({});}}
                className="text-[11px] font-semibold px-4 py-2 border border-gray-200 text-gray-600 hover:border-gray-300 rounded-lg bg-white">
                Cancel
              </button>
              <p className="text-[9px] text-gray-400 ml-2">* Required fields</p>
            </div>
          </div>
        </div>
      )}

      {/* Event cards */}
      <div className="space-y-3">
        {seEvents.map(e=>{
          const isOpen     = expanded===e.id;
          const fill       = Math.round((e.rsvp/e.capacity)*100);
          const type       = SE_TYPE_STYLE[e.type];
          const eventAuds  = audiences[e.id] ?? [];
          const audLabels  = AUDIENCE_LABELS.filter(a=>eventAuds.includes(a.key));

          return (
            <div key={e.id} className="bg-white border border-gray-200 rounded-xl overflow-hidden hover:shadow-sm transition-shadow">

              {/* ── Card header ── */}
              <button onClick={()=>setExpanded(isOpen?null:e.id)} className="w-full text-left px-4 py-3.5 flex items-center gap-3">
                <div className={`w-10 h-10 rounded-xl ${type.bg} flex items-center justify-center text-xl flex-shrink-0`}>
                  {SE_ICONS[e.type]}
                </div>
                <div className="flex-1 min-w-0">
                  <div className="flex items-center gap-2 flex-wrap mb-0.5">
                    <p className="text-xs font-bold text-gray-800">{e.name}</p>
                    <span className={`text-[10px] font-semibold px-2 py-0.5 rounded-full ${type.bg} ${type.text}`}>{type.label}</span>
                    <span className={`text-[10px] font-semibold px-2 py-0.5 rounded-full ${SE_STATUS_STYLE[e.status]}`}>{e.status}</span>
                  </div>
                  <p className="text-[11px] text-gray-500 mb-1">{e.date} · {e.time} · {e.venue}, {e.location}</p>
                  {/* Audience labels shown in header */}
                  {audLabels.length>0 && (
                    <div className="flex items-center gap-1 flex-wrap">
                      <span className="text-[9px] font-semibold text-gray-400 uppercase tracking-wide mr-0.5">Guests:</span>
                      {audLabels.map(a=>(
                        <span key={a.key} className={`text-[9px] font-bold px-1.5 py-0.5 rounded-full ${a.bg} ${a.color}`}>{a.label}</span>
                      ))}
                    </div>
                  )}
                </div>
                {/* RSVP mini-bar */}
                <div className="flex-shrink-0 text-right min-w-[90px]">
                  <p className="text-[11px] font-bold text-gray-800">{e.rsvp}<span className="text-[10px] font-normal text-gray-400">/{e.capacity}</span></p>
                  <div className="w-20 h-1.5 bg-gray-100 rounded-full overflow-hidden mt-1 ml-auto">
                    <div className={`h-full rounded-full ${fill>=90?"bg-red-400":fill>=70?"bg-amber-400":"bg-emerald-400"}`} style={{width:`${fill}%`}}/>
                  </div>
                  <p className="text-[9px] text-gray-400 mt-0.5">{fill}% filled</p>
                </div>
                <ChevronRight size={13} className={`text-gray-300 flex-shrink-0 transition-transform ${isOpen?"rotate-90":""}`}/>
              </button>

              {/* ── Expanded details ── */}
              {isOpen && (
                <div className="px-4 pb-4 border-t border-gray-50 pt-3 space-y-3">
                  <p className="text-[11px] text-gray-700 leading-relaxed">{e.description}</p>

                  {/* Details row */}
                  <div className="grid grid-cols-3 gap-3">
                    {[
                      {label:"Dress Code", value:e.dressCode},
                      {label:"Capacity",   value:`${e.capacity} seats`},
                      {label:"RSVPs",      value:`${e.rsvp} confirmed`},
                    ].map(d=>(
                      <div key={d.label} className="bg-gray-50 rounded-lg px-3 py-2">
                        <p className="text-[9px] font-semibold text-gray-400 uppercase tracking-wide">{d.label}</p>
                        <p className="text-[11px] font-semibold text-gray-800 mt-0.5">{d.value}</p>
                      </div>
                    ))}
                  </div>

                  {/* ── Cost breakdown ── */}
                  {e.costs && (()=>{
                    const total = e.costs.reduce((s,c)=>s+c.amount,0);
                    return (
                      <div className="border border-gray-100 rounded-xl overflow-hidden">
                        <div className="flex items-center justify-between px-3 py-2 bg-gray-50 border-b border-gray-100">
                          <p className="text-[10px] font-bold text-gray-600 uppercase tracking-wide">Cost Breakdown</p>
                          <p className="text-[11px] font-bold text-gray-800">AED {total.toLocaleString()}</p>
                        </div>
                        <div className="divide-y divide-gray-50">
                          {e.costs.map(c=>{
                            const pct = Math.round((c.amount/total)*100);
                            return (
                              <div key={c.category} className="flex items-center gap-3 px-3 py-2 bg-white">
                                <p className="text-[10px] text-gray-600 w-36 flex-shrink-0">{c.category}</p>
                                <div className="flex-1 h-1.5 bg-gray-100 rounded-full overflow-hidden">
                                  <div className="h-full bg-emerald-400 rounded-full" style={{width:`${pct}%`}}/>
                                </div>
                                <p className="text-[10px] text-gray-400 w-6 text-right flex-shrink-0">{pct}%</p>
                                <p className="text-[10px] font-semibold text-gray-800 w-16 text-right flex-shrink-0">AED {c.amount.toLocaleString()}</p>
                              </div>
                            );
                          })}
                        </div>
                      </div>
                    );
                  })()}

                  {/* ── Invite audiences ── */}
                  <div className="border border-gray-100 rounded-xl p-3 space-y-2 bg-gray-50/40">
                    <p className="text-[10px] font-bold text-gray-600 uppercase tracking-wide">Invite groups</p>
                    <div className="flex flex-wrap gap-1.5">
                      {AUDIENCE_LABELS.map(a=>{
                        const on = eventAuds.includes(a.key);
                        return (
                          <button key={a.key} onClick={()=>toggleLabel(e.id,a.key)}
                            className={`flex items-center gap-1 text-[10px] font-semibold px-2.5 py-1 rounded-full border transition-all ${
                              on ? `${a.bg} ${a.color} border-transparent shadow-sm`
                                 : "bg-white text-gray-500 border-gray-200 hover:border-gray-300"
                            }`}>
                            {on && <Check size={9} strokeWidth={3}/>}
                            {a.label}
                            <span className={`text-[8px] opacity-60`}>{a.count}</span>
                          </button>
                        );
                      })}
                    </div>
                    {eventAuds.length>0 && (
                      <p className="text-[9px] text-gray-400">
                        ~{AUDIENCE_LABELS.filter(a=>eventAuds.includes(a.key) && a.key!=="all").reduce((s,a)=>s+a.count,0) + (eventAuds.includes("all")?312:0)} people invited
                      </p>
                    )}
                  </div>

                  {e.notes && (
                    <div className="flex items-start gap-2 px-3 py-2.5 bg-amber-50 border border-amber-100 rounded-lg">
                      <AlertCircle size={12} className="text-amber-500 mt-0.5 flex-shrink-0"/>
                      <p className="text-[10px] text-amber-800">{e.notes}</p>
                    </div>
                  )}

                  {/* Actions */}
                  <div className="flex gap-2 pt-1">
                    <button
                      onClick={()=>setInvitesSent(s=>({...s,[e.id]:true}))}
                      disabled={!!invitesSent[e.id]||eventAuds.length===0}
                      className={`flex items-center gap-1.5 text-[10px] font-semibold px-3 py-1.5 rounded-lg transition-colors ${
                        invitesSent[e.id]
                          ?"bg-gray-50 text-gray-400 border border-gray-200 cursor-not-allowed"
                          :eventAuds.length===0
                          ?"bg-gray-50 text-gray-300 border border-gray-200 cursor-not-allowed"
                          :"bg-emerald-600 hover:bg-emerald-700 text-white"
                      }`}>
                      <Send size={10}/>{invitesSent[e.id]?"Invites Sent":"Send Invites"}
                    </button>
                    <button className="flex items-center gap-1.5 text-[10px] font-semibold px-3 py-1.5 rounded-lg border border-gray-200 text-gray-700 hover:border-gray-300 bg-white">
                      <Edit size={10}/>Edit
                    </button>
                    <button className="flex items-center gap-1.5 text-[10px] font-semibold px-3 py-1.5 rounded-lg border border-gray-200 text-red-400 hover:border-red-200 bg-white ml-auto">
                      <Trash2 size={10}/>Cancel Event
                    </button>
                  </div>
                </div>
              )}
            </div>
          );
        })}
      </div>
    </div>
  );
}

