function SocialsPage() {
  return (
    <div className="space-y-5">
      <SectionHeader title="Socials" sub="Manage social media posts and engagement"
        action={<Button size="sm" className="bg-emerald-600 hover:bg-emerald-700 text-white text-xs gap-1.5"><Plus size={13}/>New Post</Button>} />
      <div className="grid grid-cols-3 gap-3">
        {[{l:"Followers",v:"24.3K",icon:Users},{l:"Engagement",v:"6.8%",icon:TrendingUp},{l:"Posts",v:"47",icon:Image}].map(s=>{
          const Icon = s.icon;
          return <Card key={s.l} className="border-gray-100 shadow-none"><CardContent className="p-4 flex items-center gap-3">
            <Icon size={18} className="text-gray-400"/>
            <div><div className="text-xs text-gray-500">{s.l}</div><div className="text-lg font-bold text-gray-900">{s.v}</div></div>
          </CardContent></Card>;
        })}
      </div>
      <div className="space-y-3">
        {posts.map((p,i)=>(
          <Card key={i} className="border-gray-100 shadow-none">
            <CardContent className="p-4">
              <div className="flex items-start gap-3">
                <div className="w-8 h-8 rounded-lg flex items-center justify-center flex-shrink-0 bg-gray-100">
                  {p.platform==="Twitter/X"?<Twitter size={15} className="text-gray-600"/>:
                   p.platform==="LinkedIn"?<Linkedin size={15} className="text-blue-600"/>:
                   <Instagram size={15} className="text-pink-500"/>}
                </div>
                <div className="flex-1 min-w-0">
                  <div className="flex items-center gap-2 mb-1">
                    <span className="text-xs font-semibold text-gray-700">{p.platform}</span>
                    <Pill label={p.status} color={p.status==="published"?"bg-green-100 text-green-700":p.status==="scheduled"?"bg-blue-100 text-blue-700":"bg-gray-100 text-gray-500"}/>
                  </div>
                  <p className="text-xs text-gray-600 line-clamp-2">{p.content}</p>
                  <div className="flex items-center gap-3 mt-2">
                    <span className="text-[11px] text-gray-400">{p.scheduled}</span>
                    <span className="text-[11px] text-gray-400">Reach: {p.reach}</span>
                  </div>
                </div>
                <div className="flex gap-1.5">
                  <button className="text-gray-400 hover:text-gray-600"><Edit size={13}/></button>
                  <button className="text-gray-400 hover:text-gray-600"><Send size={13}/></button>
                </div>
              </div>
            </CardContent>
          </Card>
        ))}
      </div>
    </div>
  );
}

