const PIPELINE_STAGES = ["Contact","Negotiating","Closed","Signed","Funded"] as const;
function pipelineStage(s:SpLead):number {
  if (s.fundsReceived==="yes")             return 5;
  if (s.signed)                            return 4;
  if (s.closedYes && !s.signed)            return 3;
  if (s.closedNo)                          return -1;
  if (s.negotiating)                       return 2;
  if (s.contactInitiated)                  return 1;
  return 0;
}

function SponsorsPage() {
  const [sTab,         setSTab]         = useState<"active"|"previous"|"rooms">("active");
  const [irDay,        setIrDay]        = useState<string>("Apr 15");
  const [activeLeads,  setActiveLeads]  = useState<SpLead[]>(SPR_ACTIVE);
  const [expandedRow,  setExpandedRow]  = useState<string|null>(null);
  const [catFilter,    setCatFilter]    = useState<string>("all");
  const [tierFilter,   setTierFilter]   = useState<string>("all");
  const [showAddForm,  setShowAddForm]  = useState(false);
  const [newSponsor,   setNewSponsor]   = useState({company:"",category:"Startup",member:"",tier:"Silver",price:"",leadContact:"",leadEmail:""});

  const filteredActive = activeLeads
    .filter(s=>catFilter==="all"||s.category===catFilter)
    .filter(s=>tierFilter==="all"||s.tier===tierFilter);

  const totalCommitted = activeLeads.filter(s=>s.signed).reduce((sum,s)=>sum+s.price,0);
  const totalReceived  = activeLeads.filter(s=>s.fundsReceived==="yes").reduce((sum,s)=>sum+s.price,0);
  const totalPending   = activeLeads.filter(s=>s.fundsReceived==="pending").reduce((sum,s)=>sum+s.price,0);
  const signedCount    = activeLeads.filter(s=>s.signed).length;
  const inPipelineCount= activeLeads.filter(s=>!s.signed&&!s.closedNo).length;

  const toggleCtk = (id:string) =>
    setActiveLeads(ls=>ls.map(l=>l.id===id?{...l,ctkSent:!l.ctkSent}:l));

  const updateStatus = (id:string, newStatus:string) =>
    setActiveLeads(ls=>ls.map(l=>l.id===id?{...l,status:newStatus}:l));

  const addSponsor = () => {
    if (!newSponsor.company.trim()) return;
    const id=`s${Date.now()}`;
    setActiveLeads(ls=>[...ls,{id,company:newSponsor.company,category:newSponsor.category,member:newSponsor.member,poc:"",status:"Added",contactInitiated:false,negotiating:false,closedNo:false,closedYes:false,signed:false,fundsReceived:"—",attendees:"",booth:null,interviews:false,tier:newSponsor.tier,price:Number(newSponsor.price)||0,leadContact:newSponsor.leadContact,leadEmail:newSponsor.leadEmail,expectations:"",comments:"",sendTiming:"",ctkSent:false}]);
    setNewSponsor({company:"",category:"Startup",member:"",tier:"Silver",price:"",leadContact:"",leadEmail:""});
    setShowAddForm(false);
  };

  return (
    <div className="space-y-4">
      <SectionHeader title="Sponsors" sub="Pipeline tracking for MENA Summit 2026 · Dubai"
        action={
          <button onClick={()=>setShowAddForm(o=>!o)}
            className="flex items-center gap-1.5 text-xs font-semibold px-3 py-1.5 rounded-lg bg-emerald-600 text-white hover:bg-emerald-700 transition-colors">
            <Plus size={12}/> Add Lead
          </button>
        }/>

      {/* ── Stats ── */}
      <div className="grid grid-cols-5 gap-2">
        {[
          {l:"Total committed",  v:`$${totalCommitted.toLocaleString()}`, sub:`${signedCount} signed`,        txt:"text-gray-900",    bg:"bg-white",       border:"border-gray-200"},
          {l:"Funds received",   v:`$${totalReceived.toLocaleString()}`,  sub:"cleared",                       txt:"text-emerald-700", bg:"bg-emerald-50",  border:"border-emerald-200"},
          {l:"Pending payment",  v:`$${totalPending.toLocaleString()}`,   sub:"awaiting transfer",             txt:"text-amber-700",   bg:"bg-amber-50",    border:"border-amber-200"},
          {l:"In pipeline",      v:String(inPipelineCount),               sub:"active leads",                  txt:"text-blue-700",    bg:"bg-blue-50",     border:"border-blue-200"},
          {l:"Previous leads",   v:String(SPR_PREV.length),              sub:"not converted",                  txt:"text-gray-500",    bg:"bg-gray-50",     border:"border-gray-200"},
        ].map(s=>(
          <div key={s.l} className={`border ${s.border} ${s.bg} rounded-xl p-3 shadow-sm`}>
            <p className={`text-xl font-bold ${s.txt}`}>{s.v}</p>
            <p className="text-[10px] text-gray-500 mt-0.5">{s.l}</p>
            <p className="text-[9px] text-gray-400 mt-0.5">{s.sub}</p>
          </div>
        ))}
      </div>

      {/* ── Add sponsor form ── */}
      {showAddForm && (
        <div className="bg-white border border-emerald-200 rounded-xl p-4 shadow-sm space-y-3">
          <div className="flex items-center justify-between">
            <p className="text-xs font-bold text-gray-800">New Lead</p>
            <button onClick={()=>setShowAddForm(false)}><X size={13} className="text-gray-400"/></button>
          </div>
          <div className="grid grid-cols-5 gap-2">
            <div className="col-span-2">
              <label className="text-[10px] font-semibold text-gray-500 block mb-1">Company *</label>
              <input value={newSponsor.company} onChange={e=>setNewSponsor(d=>({...d,company:e.target.value}))}
                placeholder="Company name" className="w-full border border-gray-200 rounded-lg px-2.5 py-1.5 text-xs focus:outline-none focus:border-emerald-400"/>
            </div>
            <div>
              <label className="text-[10px] font-semibold text-gray-500 block mb-1">Category</label>
              <select value={newSponsor.category} onChange={e=>setNewSponsor(d=>({...d,category:e.target.value}))}
                className="w-full border border-gray-200 rounded-lg px-2.5 py-1.5 text-xs bg-white focus:outline-none focus:border-emerald-400">
                {["Big tech","Startup","Operator","Educator","Gov/VC"].map(c=><option key={c}>{c}</option>)}
              </select>
            </div>
            <div>
              <label className="text-[10px] font-semibold text-gray-500 block mb-1">Tier</label>
              <select value={newSponsor.tier} onChange={e=>setNewSponsor(d=>({...d,tier:e.target.value}))}
                className="w-full border border-gray-200 rounded-lg px-2.5 py-1.5 text-xs bg-white focus:outline-none focus:border-emerald-400">
                {["Gold","Silver","Bronze","In-Kind","Paid","—"].map(t=><option key={t}>{t}</option>)}
              </select>
            </div>
            <div>
              <label className="text-[10px] font-semibold text-gray-500 block mb-1">Price (USD)</label>
              <input value={newSponsor.price} onChange={e=>setNewSponsor(d=>({...d,price:e.target.value}))}
                placeholder="0" className="w-full border border-gray-200 rounded-lg px-2.5 py-1.5 text-xs focus:outline-none focus:border-emerald-400"/>
            </div>
          </div>
          <div className="grid grid-cols-2 gap-2">
            <div>
              <label className="text-[10px] font-semibold text-gray-500 block mb-1">Lead Contact</label>
              <input value={newSponsor.leadContact} onChange={e=>setNewSponsor(d=>({...d,leadContact:e.target.value}))}
                placeholder="Contact person name" className="w-full border border-gray-200 rounded-lg px-2.5 py-1.5 text-xs focus:outline-none focus:border-emerald-400"/>
            </div>
            <div>
              <label className="text-[10px] font-semibold text-gray-500 block mb-1">Lead Email</label>
              <input value={newSponsor.leadEmail} onChange={e=>setNewSponsor(d=>({...d,leadEmail:e.target.value}))}
                placeholder="contact@company.com" type="email" className="w-full border border-gray-200 rounded-lg px-2.5 py-1.5 text-xs focus:outline-none focus:border-emerald-400"/>
            </div>
          </div>
          <div className="flex gap-2 justify-end">
            <button onClick={()=>setShowAddForm(false)} className="text-xs text-gray-500 px-3 py-1.5 border border-gray-200 rounded-lg hover:bg-gray-50">Cancel</button>
            <button onClick={addSponsor} className="text-xs font-bold px-3 py-1.5 bg-emerald-600 text-white rounded-lg hover:bg-emerald-700">Add lead</button>
          </div>
        </div>
      )}

      {/* ── Tabs ── */}
      <div className="flex gap-0.5 border-b border-gray-200">
        {([
          {k:"active"   as const, label:`🏆 Active Leads (${activeLeads.length})`},
          {k:"previous" as const, label:`📁 Previous Leads (${SPR_PREV.length})`},
          {k:"rooms"    as const, label:`🚪 Interview Rooms`},
        ]).map(t=>(
          <button key={t.k} onClick={()=>setSTab(t.k)}
            className={`px-3 py-2 text-xs font-medium border-b-2 -mb-px transition-colors ${
              sTab===t.k?"border-emerald-500 text-emerald-700 bg-white":"border-transparent text-gray-500 hover:text-gray-700"
            }`}>{t.label}
          </button>
        ))}
      </div>

      {/* ══════════ ACTIVE LEADS ══════════ */}
      {sTab==="active" && (
        <div className="space-y-3">
          {/* Filters */}
          <div className="flex items-center gap-2 flex-wrap">
            <span className="text-[10px] font-bold text-gray-400 uppercase tracking-wide">Filter:</span>
            {["all","Big tech","Startup","Operator","Educator","Gov/VC"].map(c=>(
              <button key={c} onClick={()=>setCatFilter(c)}
                className={`text-[10px] font-semibold px-2.5 py-1 rounded-full border transition-colors ${
                  catFilter===c?"bg-gray-800 text-white border-gray-800":"bg-white text-gray-500 border-gray-200 hover:border-gray-300"
                }`}>{c==="all"?"All categories":c}</button>
            ))}
            <span className="w-px h-4 bg-gray-200 mx-1"/>
            {["all","Gold","Silver","Bronze","In-Kind","Paid"].map(t=>(
              <button key={t} onClick={()=>setTierFilter(t)}
                className={`text-[10px] font-semibold px-2.5 py-1 rounded-full border transition-colors ${
                  tierFilter===t?"bg-gray-800 text-white border-gray-800":"bg-white text-gray-500 border-gray-200 hover:border-gray-300"
                }`}>{t==="all"?"All tiers":t}</button>
            ))}
          </div>

          {/* Main table */}
          <div className="bg-white border border-gray-200 rounded-xl overflow-hidden">
            <div className="overflow-x-auto" style={{maxHeight:"520px",overflowY:"auto"}}>
              <table className="w-full text-xs" style={{minWidth:"1200px"}}>
                <thead className="sticky top-0 z-10">
                  <tr className="bg-gray-50 border-b border-gray-100">
                    <th className="text-left px-3 py-2.5 text-[9px] font-bold text-gray-400 uppercase tracking-wide whitespace-nowrap w-10">#</th>
                    <th className="text-left px-3 py-2.5 text-[9px] font-bold text-gray-400 uppercase tracking-wide whitespace-nowrap min-w-[140px]">Company</th>
                    <th className="text-left px-3 py-2.5 text-[9px] font-bold text-gray-400 uppercase tracking-wide whitespace-nowrap">MenaML PoC</th>
                    <th className="text-left px-3 py-2.5 text-[9px] font-bold text-gray-400 uppercase tracking-wide whitespace-nowrap">Status</th>
                    <th className="text-left px-3 py-2.5 text-[9px] font-bold text-gray-400 uppercase tracking-wide whitespace-nowrap">Funds</th>
                    <th className="text-left px-3 py-2.5 text-[9px] font-bold text-gray-400 uppercase tracking-wide whitespace-nowrap">Tier</th>
                    <th className="text-left px-3 py-2.5 text-[9px] font-bold text-gray-400 uppercase tracking-wide whitespace-nowrap">Price</th>
                    <th className="text-left px-3 py-2.5 text-[9px] font-bold text-gray-400 uppercase tracking-wide whitespace-nowrap">Lead Contact</th>
                    <th className="text-left px-3 py-2.5 text-[9px] font-bold text-gray-400 uppercase tracking-wide whitespace-nowrap">Att.</th>
                    <th className="text-left px-3 py-2.5 text-[9px] font-bold text-gray-400 uppercase tracking-wide whitespace-nowrap">Booth</th>
                    <th className="text-left px-3 py-2.5 text-[9px] font-bold text-gray-400 uppercase tracking-wide whitespace-nowrap">Intv.</th>
                    <th className="text-left px-3 py-2.5 text-[9px] font-bold text-gray-400 uppercase tracking-wide whitespace-nowrap">Send timing</th>
                    <th className="text-left px-3 py-2.5 text-[9px] font-bold text-gray-400 uppercase tracking-wide whitespace-nowrap">CtK</th>
                    <th className="px-3 py-2.5 w-8"/>
                  </tr>
                </thead>
                <tbody>
                  {filteredActive.map((s,i)=>{
                    const stage = pipelineStage(s);
                    const tierStyle = SPR_TIER_STYLE[s.tier] || SPR_TIER_STYLE["—"];
                    const expanded = expandedRow===s.id;
                    return (
                      <Fragment key={s.id}>
                        <tr className={`border-b border-gray-50 border-l-2 ${tierStyle.border} cursor-pointer transition-colors ${
                          expanded?"bg-emerald-50/30":i%2===0?"bg-white hover:bg-gray-50/60":"bg-gray-50/20 hover:bg-gray-50/60"
                        }`} onClick={()=>setExpandedRow(expanded?null:s.id)}>
                          <td className="px-3 py-2.5 text-[10px] text-gray-400 font-mono">{i+1}</td>
                          <td className="px-3 py-2.5">
                            <div className="flex items-center gap-1.5">
                              <div className="w-6 h-6 rounded-md bg-gray-100 flex items-center justify-center text-[8px] font-bold text-gray-600 flex-shrink-0">
                                {s.company.slice(0,2).toUpperCase()}
                              </div>
                              <div>
                                <p className="text-[11px] font-bold text-gray-800 whitespace-nowrap">{s.company}</p>
                                <span className={`text-[8px] font-bold px-1.5 py-0.5 rounded-full ${SPR_CAT_COLOR[s.category]||"bg-gray-100 text-gray-500"}`}>{s.category}</span>
                              </div>
                            </div>
                          </td>
                          <td className="px-3 py-2.5 text-[10px] text-gray-500 whitespace-nowrap">{s.member}{s.poc&&<><br/><span className="text-[9px] text-gray-400">{s.poc}</span></>}</td>
                          <td className="px-3 py-2.5 max-w-[160px]">
                            <select value={s.status} onChange={e=>{e.stopPropagation(); updateStatus(s.id, e.target.value);}}
                              className="w-full px-2 py-1 text-[10px] border border-gray-200 rounded-md bg-white focus:outline-none focus:border-emerald-400">
                              {["Added","Contacted","Negotiating","Accepted","Rejected","Signed","Funded"].map(st=>(
                                <option key={st}>{st}</option>
                              ))}
                            </select>
                          </td>
                          <td className="px-3 py-2.5">
                            <span className={`text-[9px] font-bold px-1.5 py-0.5 rounded-full capitalize ${SPR_FUNDS_STYLE[s.fundsReceived]}`}>
                              {s.fundsReceived==="yes"?"Received":s.fundsReceived==="pending"?"Pending":s.fundsReceived==="no"?"Not rcvd":"—"}
                            </span>
                          </td>
                          <td className="px-3 py-2.5">
                            <span className={`text-[9px] font-bold px-1.5 py-0.5 rounded-full ${tierStyle.chip}`}>{s.tier}</span>
                          </td>
                          <td className="px-3 py-2.5 text-[11px] font-bold text-gray-700 whitespace-nowrap">
                            {s.price>0?`$${s.price.toLocaleString()}`:"—"}
                          </td>
                          <td className="px-3 py-2.5">
                            <p className="text-[10px] font-semibold text-gray-700 whitespace-nowrap">{s.leadContact||"—"}</p>
                            {s.leadEmail && <p className="text-[9px] text-gray-400 font-mono truncate max-w-[100px]">{s.leadEmail}</p>}
                          </td>
                          <td className="px-3 py-2.5 text-[10px] text-gray-600">{s.attendees||"—"}</td>
                          <td className="px-3 py-2.5 text-center">
                            {s.booth===true ? <CheckCircle2 size={13} className="text-emerald-500 mx-auto"/>
                             :s.booth===false? <XCircle size={13} className="text-gray-300 mx-auto"/>
                             :<span className="text-gray-300 text-[10px]">—</span>}
                          </td>
                          <td className="px-3 py-2.5 text-center">
                            {s.interviews===true ? <CheckCircle2 size={13} className="text-emerald-500 mx-auto"/>
                             :s.interviews===false? <XCircle size={13} className="text-gray-300 mx-auto"/>
                             :<span className="text-[10px] text-gray-500">{s.interviews}</span>}
                          </td>
                          <td className="px-3 py-2.5 text-[10px] text-gray-500 whitespace-nowrap">{s.sendTiming||"—"}</td>
                          <td className="px-3 py-2.5">
                            <button onClick={e=>{e.stopPropagation();toggleCtk(s.id);}}
                              className={`w-5 h-5 rounded border-2 flex items-center justify-center transition-all ${
                                s.ctkSent?"bg-emerald-500 border-emerald-500":"border-gray-300 hover:border-emerald-400"
                              }`}>
                              {s.ctkSent && <Check size={9} className="text-white"/>}
                            </button>
                          </td>
                          <td className="px-3 py-2.5">
                            <button className="text-gray-300 hover:text-gray-500"><Edit size={11}/></button>
                          </td>
                        </tr>

                        {/* Expanded row: expectations + comments */}
                        {expanded && (
                          <tr className="border-b border-emerald-100 bg-emerald-50/30">
                            <td colSpan={17} className="px-4 py-3">
                              <div className="grid grid-cols-2 gap-4">
                                <div>
                                  <p className="text-[9px] font-bold text-gray-400 uppercase tracking-wide mb-1">Expectations from sponsor</p>
                                  <p className="text-[11px] text-gray-700 leading-relaxed">{s.expectations||"No notes"}</p>
                                </div>
                                <div>
                                  <p className="text-[9px] font-bold text-gray-400 uppercase tracking-wide mb-1">Comments</p>
                                  <p className="text-[11px] text-gray-700 leading-relaxed">{s.comments||"No notes"}</p>
                                </div>
                              </div>
                            </td>
                          </tr>
                        )}
                      </Fragment>
                    );
                  })}
                </tbody>

                {/* Footer totals */}
                <tfoot>
                  <tr className="border-t border-gray-200 bg-gray-50 sticky bottom-0">
                    <td colSpan={6} className="px-3 py-2 text-[10px] font-semibold text-gray-500">{filteredActive.length} leads shown</td>
                    <td className="px-3 py-2 text-[11px] font-bold text-gray-800">
                      ${filteredActive.reduce((s,l)=>s+l.price,0).toLocaleString()}
                    </td>
                    <td colSpan={5}/>
                  </tr>
                </tfoot>
              </table>
            </div>
          </div>

          {/* Status distribution chart */}
          <div className="bg-white border border-gray-200 rounded-xl p-4">
            <p className="text-xs font-bold text-gray-700 mb-3">Status distribution</p>
            <div className="flex items-end gap-1.5">
              {["Added","Contacted","Negotiating","Accepted","Rejected","Signed","Funded"].map((status,si)=>{
                const n = activeLeads.filter(s=>s.status===status).length;
                const maxH = 60;
                const h = Math.max(12, (n/Math.max(1,activeLeads.length))*maxH);
                const colors = ["bg-gray-300","bg-blue-300","bg-indigo-400","bg-violet-400","bg-red-300","bg-emerald-500","bg-emerald-600"];
                return (
                  <div key={status} className="flex-1 flex flex-col items-center gap-1">
                    <span className="text-[10px] font-bold text-gray-700">{n}</span>
                    <div className={`w-full rounded-t-md ${colors[si]}`} style={{height:`${h}px`}}/>
                    <span className="text-[8px] text-gray-400 font-semibold text-center whitespace-nowrap">{status}</span>
                  </div>
                );
              })}
            </div>
          </div>
        </div>
      )}

      {/* ══════════ PREVIOUS LEADS ══════════ */}
      {sTab==="previous" && (
        <div className="bg-white border border-gray-200 rounded-xl overflow-hidden">
          <table className="w-full text-xs">
            <thead>
              <tr className="bg-gray-50 border-b border-gray-100">
                {["Company","Category","MenaML Team","Notes / Reason"].map((h,i)=>(
                  <th key={i} className="text-left px-3 py-2.5 text-[9px] font-bold text-gray-400 uppercase tracking-wide whitespace-nowrap">{h}</th>
                ))}
              </tr>
            </thead>
            <tbody>
              {SPR_PREV.map((p,i)=>(
                <tr key={p.id} className={`border-b border-gray-50 ${i%2===0?"bg-white":"bg-gray-50/20"}`}>
                  <td className="px-3 py-2.5">
                    <div className="flex items-center gap-1.5">
                      <div className="w-5 h-5 rounded bg-gray-100 flex items-center justify-center text-[7px] font-bold text-gray-500 flex-shrink-0">
                        {p.company.slice(0,2).toUpperCase()}
                      </div>
                      <span className="text-[11px] font-semibold text-gray-700 whitespace-nowrap">{p.company}</span>
                    </div>
                  </td>
                  <td className="px-3 py-2.5">
                    <span className={`text-[9px] font-bold px-1.5 py-0.5 rounded-full ${SPR_CAT_COLOR[p.category]||"bg-gray-100 text-gray-500"}`}>{p.category}</span>
                  </td>
                  <td className="px-3 py-2.5 text-[10px] text-gray-500">{p.member}{p.poc&&<span className="text-gray-400 ml-1">/ {p.poc}</span>}</td>
                  <td className="px-3 py-2.5 text-[10px] text-gray-500 max-w-[300px]">
                    <p className="line-clamp-2 leading-relaxed">{p.notes||"—"}</p>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      )}

      {/* ══════════ INTERVIEW ROOMS ══════════ */}
      {sTab==="rooms" && (()=>{
        const dayBookings = IR_BOOKINGS.filter(b=>b.day===irDay);
        const bookedCount = dayBookings.length;
        const totalSlots  = IR_ROOMS.length * IR_SLOTS.length;
        const availCount  = totalSlots - bookedCount;

        // unique sponsors on this day for legend
        const daySponsors = Array.from(new Set(dayBookings.map(b=>b.sponsor)));

        function getBooking(room:string, slot:string): IRBooking|undefined {
          return dayBookings.find(b=>b.room===room&&b.slot===slot);
        }

        return (
          <div className="space-y-4">
            {/* Summary tiles */}
            <div className="grid grid-cols-4 gap-3">
              {[
                {l:"Total slots",   v:totalSlots,   txt:"text-gray-800",    bg:"bg-white border-gray-200"},
                {l:"Booked",        v:bookedCount,  txt:"text-blue-700",    bg:"bg-blue-50 border-blue-200"},
                {l:"Available",     v:availCount,   txt:"text-emerald-700", bg:"bg-emerald-50 border-emerald-200"},
                {l:"Rooms",         v:IR_ROOMS.length, txt:"text-gray-700", bg:"bg-gray-50 border-gray-200"},
              ].map(t=>(
                <div key={t.l} className={`border rounded-xl p-3 ${t.bg}`}>
                  <p className={`text-2xl font-bold ${t.txt}`}>{t.v}</p>
                  <p className="text-[10px] text-gray-500 mt-0.5">{t.l}</p>
                </div>
              ))}
            </div>

            {/* Day selector */}
            <div className="flex items-center gap-2">
              <span className="text-[10px] font-bold text-gray-400 uppercase tracking-wide">Day:</span>
              <div className="flex gap-1">
                {IR_DAYS.map(d=>(
                  <button key={d} onClick={()=>setIrDay(d)}
                    className={`px-3 py-1.5 text-xs font-semibold rounded-lg border transition-colors ${
                      irDay===d?"bg-gray-800 text-white border-gray-800":"bg-white text-gray-500 border-gray-200 hover:border-gray-300 hover:text-gray-700"
                    }`}>{d}</button>
                ))}
              </div>

              {/* Legend */}
              <div className="ml-auto flex items-center gap-3">
                <div className="flex items-center gap-1.5">
                  <div className="w-3 h-3 rounded bg-emerald-100 border border-emerald-300"/>
                  <span className="text-[10px] text-gray-500">Available</span>
                </div>
                {daySponsors.map(sp=>{
                  const sample = dayBookings.find(b=>b.sponsor===sp);
                  if (!sample) return null;
                  const [bg,border] = [sample.color.split(" ")[0], sample.color.split(" ")[1]];
                  return (
                    <div key={sp} className="flex items-center gap-1.5">
                      <div className={`w-3 h-3 rounded ${bg} border ${border}`}/>
                      <span className="text-[10px] text-gray-500">{sp}</span>
                    </div>
                  );
                })}
              </div>
            </div>

            {/* Agenda grid */}
            <div className="bg-white border border-gray-200 rounded-xl overflow-hidden">
              {/* Header row: time slots */}
              <div className="grid border-b border-gray-200 bg-gray-50"
                style={{gridTemplateColumns:`180px repeat(${IR_SLOTS.length}, 1fr)`}}>
                <div className="px-3 py-2.5 text-[9px] font-bold text-gray-400 uppercase tracking-wide">Room</div>
                {IR_SLOTS.map(sl=>(
                  <div key={sl} className="px-2 py-2.5 text-[9px] font-bold text-gray-500 text-center border-l border-gray-100 whitespace-nowrap">{sl}</div>
                ))}
              </div>

              {/* Room rows */}
              {IR_ROOMS.map((room,ri)=>(
                <div key={room.id}
                  className={`grid border-b border-gray-100 last:border-b-0 ${ri%2===0?"bg-white":"bg-gray-50/30"}`}
                  style={{gridTemplateColumns:`180px repeat(${IR_SLOTS.length}, 1fr)`}}>
                  {/* Room name */}
                  <div className="px-3 py-3 border-r border-gray-100">
                    <p className="text-[11px] font-bold text-gray-800 leading-tight">{room.name}</p>
                    <p className="text-[9px] text-gray-400 mt-0.5">Cap. {room.capacity} pax</p>
                  </div>
                  {/* Slot cells */}
                  {IR_SLOTS.map(sl=>{
                    const booking = getBooking(room.id, sl);
                    return (
                      <div key={sl} className="px-1.5 py-2 border-l border-gray-100 flex items-stretch">
                        {booking ? (
                          <div className={`flex-1 rounded-lg border px-2 py-1.5 ${booking.color}`}>
                            <p className="text-[10px] font-bold leading-tight truncate">{booking.sponsor}</p>
                            <p className="text-[9px] leading-snug mt-0.5 opacity-80 line-clamp-2">{booking.purpose}</p>
                          </div>
                        ) : (
                          <div className="flex-1 rounded-lg border border-emerald-200 bg-emerald-50 flex items-center justify-center">
                            <span className="text-[9px] font-semibold text-emerald-600">Available</span>
                          </div>
                        )}
                      </div>
                    );
                  })}
                </div>
              ))}
            </div>
          </div>
        );
      })()}
    </div>
  );
}

// ─── Page: Budget ─────────────────────────────────────────────────────────────
const budgetItems = [
  { category:"Venue & A/V",    budgeted:30000, spent:28500, color:"bg-blue-400" },
  { category:"Speaker Travel", budgeted:18000, spent:14200, color:"bg-purple-400" },
  { category:"Accommodation",  budgeted:22000, spent:19800, color:"bg-teal-400" },
  { category:"Catering",       budgeted:15000, spent:0,     color:"bg-amber-400" },
  { category:"Marketing",      budgeted:8000,  spent:5600,  color:"bg-rose-400" },
  { category:"Swag & Badges",  budgeted:4000,  spent:1200,  color:"bg-indigo-400" },
];
function BudgetPage() {
  const totalBudget = budgetItems.reduce((s,i)=>s+i.budgeted,0);
  const totalSpent  = budgetItems.reduce((s,i)=>s+i.spent,0);
  return (
    <div className="space-y-5">
      <SectionHeader title="Budget" sub="Track expenses and financial planning"
        action={<Button size="sm" variant="outline" className="text-xs gap-1.5"><Download size={13}/>Export</Button>} />
      <div className="grid grid-cols-3 gap-3">
        {[
          {l:"Total Budget",v:`$${totalBudget.toLocaleString()}`,color:"text-gray-900"},
          {l:"Spent",v:`$${totalSpent.toLocaleString()}`,color:"text-red-600"},
          {l:"Remaining",v:`$${(totalBudget-totalSpent).toLocaleString()}`,color:"text-green-600"},
        ].map(s=>(
          <Card key={s.l} className="border-gray-100 shadow-none"><CardContent className="p-4">
            <div className="text-xs text-gray-500 mb-1">{s.l}</div>
            <div className={`text-2xl font-bold ${s.color}`}>{s.v}</div>
          </CardContent></Card>
        ))}
      </div>
      <Card className="border-gray-100 shadow-none">
        <CardContent className="p-5 space-y-4">
          {budgetItems.map(item=>(
            <div key={item.category} className="space-y-1.5">
              <div className="flex items-center justify-between">
                <span className="text-xs font-medium text-gray-700">{item.category}</span>
                <div className="flex items-center gap-3">
                  <span className="text-[11px] text-red-500">${item.spent.toLocaleString()} spent</span>
                  <span className="text-[11px] text-gray-400">of ${item.budgeted.toLocaleString()}</span>
                </div>
              </div>
              <div className="w-full h-2 bg-gray-100 rounded-full overflow-hidden">
                <div className={`h-full rounded-full ${item.color}`}
                  style={{width:`${item.budgeted>0?(item.spent/item.budgeted)*100:0}%`}}/>
              </div>
            </div>
          ))}
        </CardContent>
      </Card>
    </div>
  );
}

