// ─── EmailLibraryPage ─────────────────────────────────────────────────────────
type EmailTemplate = { id:string; subject:string; stage:string; audience:string; status:"sent"|"draft"|"scheduled"; sent?:string; opens?:string; preview:string };
const EMAIL_TEMPLATES: EmailTemplate[] = [
  { id:"e01", stage:"Pre-Event",  audience:"All Applicants",     status:"sent",      sent:"Mar 10", opens:"89%", subject:"Application Received — MENA Summit 2026",          preview:"Thank you for applying to MENA Summit 2026. We have received your application and will review it shortly…" },
  { id:"e02", stage:"Pre-Event",  audience:"Accepted Attendees", status:"sent",      sent:"Mar 12", opens:"76%", subject:"Congratulations — You've Been Accepted",            preview:"We are thrilled to inform you that your application has been accepted. Please complete your registration by…" },
  { id:"e03", stage:"Pre-Event",  audience:"Rejected Applicants",status:"sent",      sent:"Mar 13", opens:"61%", subject:"MENA Summit 2026 — Application Update",            preview:"Thank you for your interest in MENA Summit 2026. After careful consideration, we regret to inform you…" },
  { id:"e04", stage:"Pre-Event",  audience:"Speakers",           status:"sent",      sent:"Mar 14", opens:"92%", subject:"Speaker Confirmation Packet",                       preview:"Congratulations and welcome as a speaker. Attached you will find your speaker briefing, AV requirements and…" },
  { id:"e05", stage:"Pre-Event",  audience:"Sponsors",           status:"sent",      sent:"Mar 8",  opens:"88%", subject:"Sponsor Onboarding — Brand Assets & Requirements",  preview:"Thank you for sponsoring MENA Summit 2026. Please submit your brand assets by April 1 via the link…" },
  { id:"e06", stage:"Pre-Event",  audience:"Invited Experts",    status:"draft",     subject:"Travel & Logistics Details — Invited Experts",     preview:"Your travel and accommodation arrangements for MENA Summit 2026 are now confirmed. Please find your itinerary…" },
  { id:"e07", stage:"Pre-Event",  audience:"All Attendees",      status:"draft",     subject:"Practical Info — Hotel, Transport & Schedule",      preview:"The event is now three weeks away! Here is everything you need to know about getting to the venue, check-in…" },
  { id:"e08", stage:"Pre-Event",  audience:"All Attendees",      status:"scheduled", subject:"Final Reminder — 7 Days to MENA Summit",            preview:"We cannot wait to see you next week! Your badge will be ready at registration from 8:00 AM on Day 1…" },
  { id:"e09", stage:"During",     audience:"All Attendees",      status:"draft",     subject:"Day 1 — Schedule & Housekeeping",                   preview:"Good morning and welcome to Day 1 of MENA Summit 2026! Here is today's full schedule and a few housekeeping…" },
  { id:"e10", stage:"During",     audience:"Speakers",           status:"draft",     subject:"Speaker Green Room & AV Check Reminder",           preview:"A reminder that the green room is located on Level 2. Please arrive 30 minutes before your session for an AV…" },
  { id:"e11", stage:"Post-Event", audience:"All Attendees",      status:"draft",     subject:"Thank You — MENA Summit 2026 Wrap-Up",             preview:"What an incredible three days! Thank you for being part of MENA Summit 2026. We are proud to share that…" },
  { id:"e12", stage:"Post-Event", audience:"Speakers",           status:"draft",     subject:"Speaker Impact Report",                             preview:"Thank you for sharing your expertise at MENA Summit 2026. Your session attracted X attendees and your slides…" },
  { id:"e13", stage:"Post-Event", audience:"Sponsors",           status:"draft",     subject:"Sponsor Post-Event Report & Thank You",             preview:"On behalf of the MENA Summit 2026 team, thank you for your generous support. Attached is your sponsor impact…" },
  { id:"e14", stage:"Post-Event", audience:"All Attendees",      status:"draft",     subject:"Post-Event Survey — Share Your Feedback",           preview:"Your opinion matters! Please take 5 minutes to complete our post-event survey and help us improve next year…" },
];
const EMAIL_STAGE_CLS: Record<string,string> = {
  "Pre-Event":  "bg-blue-100 text-blue-700",
  "During":     "bg-violet-100 text-violet-700",
  "Post-Event": "bg-amber-100 text-amber-700",
};
const EMAIL_AUD_CLS: Record<string,string> = {
  "All Applicants":      "bg-gray-100 text-gray-600",
  "Accepted Attendees":  "bg-emerald-100 text-emerald-700",
  "Rejected Applicants": "bg-red-100 text-red-600",
  "Speakers":            "bg-violet-100 text-violet-700",
  "Sponsors":            "bg-amber-100 text-amber-700",
  "Invited Experts":     "bg-indigo-100 text-indigo-700",
  "All Attendees":       "bg-teal-100 text-teal-700",
};

function EmailLibraryPage() {
  const [stageFilter, setStageFilter]   = useState("All");
  const [audFilter,   setAudFilter]     = useState("All");
  const [preview,     setPreview]       = useState<EmailTemplate|null>(null);
  const stages    = ["All","Pre-Event","During","Post-Event"];
  const audiences = ["All",...Array.from(new Set(EMAIL_TEMPLATES.map(e=>e.audience)))];
  const filtered  = EMAIL_TEMPLATES.filter(e=>{
    const ms = stageFilter==="All"||e.stage===stageFilter;
    const ma = audFilter==="All"||e.audience===audFilter;
    return ms&&ma;
  });
  const sent      = EMAIL_TEMPLATES.filter(e=>e.status==="sent").length;
  const drafts    = EMAIL_TEMPLATES.filter(e=>e.status==="draft").length;
  const scheduled = EMAIL_TEMPLATES.filter(e=>e.status==="scheduled").length;
  return (
    <div className="flex gap-5" style={{height:"calc(100vh - 120px)"}}>
      {/* Left: list */}
      <div className="flex-1 overflow-y-auto space-y-4 pr-1">
        {/* Hero */}
        <div className="bg-gradient-to-r from-emerald-600 to-teal-600 rounded-2xl p-5 text-white">
          <p className="text-xs font-semibold text-white/70 mb-1">Engage</p>
          <h2 className="text-lg font-bold mb-1">Email Library</h2>
          <p className="text-sm text-white/80">Templates for every stage of the event lifecycle, by audience.</p>
          <div className="flex gap-3 mt-3 text-xs font-semibold flex-wrap">
            <span className="bg-white/20 px-2.5 py-1 rounded-full">{EMAIL_TEMPLATES.length} templates</span>
            <span className="bg-emerald-400/30 px-2.5 py-1 rounded-full">{sent} sent</span>
            <span className="bg-blue-300/30 px-2.5 py-1 rounded-full">{scheduled} scheduled</span>
            <span className="bg-white/10 px-2.5 py-1 rounded-full">{drafts} drafts</span>
          </div>
        </div>

        {/* Filters + action */}
        <div className="flex items-center gap-2 flex-wrap">
          <div className="flex gap-1 flex-wrap">
            {stages.map(s=>(
              <button key={s} onClick={()=>setStageFilter(s)}
                className={`text-[11px] font-semibold px-2.5 py-1 rounded-full border transition-colors ${
                  stageFilter===s?"bg-emerald-600 text-white border-emerald-600":"bg-white text-gray-500 border-gray-200 hover:border-gray-300"
                }`}>{s}</button>
            ))}
          </div>
          <div className="w-px h-4 bg-gray-200 mx-1"/>
          <div className="flex gap-1 flex-wrap">
            {audiences.map(a=>(
              <button key={a} onClick={()=>setAudFilter(a)}
                className={`text-[10px] font-semibold px-2 py-0.5 rounded-full border transition-colors ${
                  audFilter===a?"bg-slate-800 text-white border-slate-800":"bg-white text-gray-400 border-gray-200 hover:border-gray-300"
                }`}>{a}</button>
            ))}
          </div>
          <button className="flex items-center gap-1.5 text-xs font-semibold px-3 py-1.5 bg-emerald-600 text-white rounded-lg hover:bg-emerald-700 ml-auto">
            <Plus size={12}/> New Template
          </button>
        </div>

        {/* Cards */}
        <div className="space-y-2">
          {filtered.map(e=>(
            <button key={e.id} onClick={()=>setPreview(preview?.id===e.id?null:e)}
              className={`w-full text-left bg-white border rounded-xl px-4 py-3.5 shadow-sm hover:shadow transition-all ${
                preview?.id===e.id?"border-emerald-300":"border-gray-200"
              }`}>
              <div className="flex items-start gap-3">
                <Mail size={13} className={`mt-0.5 flex-shrink-0 ${preview?.id===e.id?"text-emerald-600":"text-gray-400"}`}/>
                <div className="flex-1 min-w-0">
                  <p className={`text-sm font-semibold truncate ${preview?.id===e.id?"text-emerald-700":"text-gray-800"}`}>{e.subject}</p>
                  <div className="flex items-center gap-1.5 mt-1.5 flex-wrap">
                    <span className={`text-[9px] font-bold px-1.5 py-0.5 rounded-full ${EMAIL_STAGE_CLS[e.stage]||"bg-gray-100 text-gray-600"}`}>{e.stage}</span>
                    <span className={`text-[9px] font-bold px-1.5 py-0.5 rounded-full ${EMAIL_AUD_CLS[e.audience]||"bg-gray-100 text-gray-600"}`}>{e.audience}</span>
                    {e.status==="sent" && <span className="text-[9px] font-bold px-1.5 py-0.5 rounded-full bg-emerald-100 text-emerald-700">Sent {e.sent} · {e.opens} open rate</span>}
                    {e.status==="scheduled" && <span className="text-[9px] font-bold px-1.5 py-0.5 rounded-full bg-blue-100 text-blue-700">Scheduled</span>}
                    {e.status==="draft" && <span className="text-[9px] font-bold px-1.5 py-0.5 rounded-full bg-gray-100 text-gray-500">Draft</span>}
                  </div>
                </div>
                <ChevronRight size={13} className={`text-gray-300 flex-shrink-0 mt-0.5 ${preview?.id===e.id?"text-emerald-400":""}`}/>
              </div>
            </button>
          ))}
          {filtered.length===0&&<p className="text-center py-8 text-gray-400 text-xs">No templates match this filter.</p>}
        </div>
      </div>

      {/* Right: preview */}
      {preview ? (
        <div className="w-80 flex-shrink-0 overflow-y-auto">
          <div className="bg-white border border-gray-200 rounded-2xl shadow-sm sticky top-0">
            <div className="px-5 py-4 bg-gray-50 border-b border-gray-100 flex items-start gap-2">
              <div className="flex-1">
                <p className="text-sm font-bold text-gray-900 leading-snug">{preview.subject}</p>
                <div className="flex gap-1.5 mt-1.5 flex-wrap">
                  <span className={`text-[9px] font-bold px-1.5 py-0.5 rounded-full ${EMAIL_STAGE_CLS[preview.stage]}`}>{preview.stage}</span>
                  <span className={`text-[9px] font-bold px-1.5 py-0.5 rounded-full ${EMAIL_AUD_CLS[preview.audience]||"bg-gray-100 text-gray-600"}`}>{preview.audience}</span>
                </div>
              </div>
              <button onClick={()=>setPreview(null)} className="p-1 rounded hover:bg-gray-200 text-gray-400"><X size={13}/></button>
            </div>
            <div className="p-5 space-y-4">
              <div>
                <p className="text-[10px] font-bold text-gray-400 uppercase tracking-wide mb-1.5">Preview</p>
                <p className="text-xs text-gray-600 leading-relaxed italic">"{preview.preview}"</p>
              </div>
              {preview.status==="sent"&&(
                <div className="grid grid-cols-2 gap-2">
                  {[{l:"Sent",v:preview.sent!},{l:"Open Rate",v:preview.opens!}].map(s=>(
                    <div key={s.l} className="bg-gray-50 rounded-lg p-2.5 text-center">
                      <p className="text-sm font-bold text-gray-800">{s.v}</p>
                      <p className="text-[10px] text-gray-400">{s.l}</p>
                    </div>
                  ))}
                </div>
              )}
              <div className="flex gap-2 pt-1">
                <button className="flex-1 text-xs font-semibold px-3 py-1.5 bg-emerald-600 text-white rounded-lg hover:bg-emerald-700">
                  {preview.status==="sent"?"View Full":"Edit Draft"}
                </button>
                {preview.status!=="sent"&&(
                  <button className="flex items-center gap-1 text-xs font-semibold px-3 py-1.5 border border-gray-200 text-gray-600 rounded-lg hover:bg-gray-50">
                    <Send size={11}/> Send
                  </button>
                )}
              </div>
            </div>
          </div>
        </div>
      ):(
        <div className="w-80 flex-shrink-0 flex items-center justify-center">
          <div className="text-center text-gray-300 p-8">
            <Mail size={32} className="mx-auto mb-3 opacity-40"/>
            <p className="text-sm font-semibold">Select a template</p>
            <p className="text-xs mt-1">Click any email to preview it here.</p>
          </div>
        </div>
      )}
    </div>
  );
}

// ─── PushNotificationsPage ────────────────────────────────────────────────────
type PushNotif = { id:string; title:string; body:string; target:"organizers"|"attendees"|"all"; status:"sent"|"scheduled"|"draft"; sentAt?:string; opened?:string };
const PUSH_SEED: PushNotif[] = [
  { id:"pn1", title:"Applications Now Open",         body:"Applications for MENA Summit 2026 are now open. Apply before March 1.",                  target:"all",        status:"sent",      sentAt:"Feb 5, 09:00",  opened:"74%" },
  { id:"pn2", title:"Acceptance Decisions Released",  body:"Check your portal — acceptance decisions for MENA Summit 2026 are now live.",             target:"all",        status:"sent",      sentAt:"Mar 12, 11:00", opened:"81%" },
  { id:"pn3", title:"Volunteer Briefing — This Friday",body:"Reminder: Volunteer briefing is this Friday at 18:00 on Zoom. Link in your portal.",     target:"organizers", status:"sent",      sentAt:"Mar 15, 09:30", opened:"92%" },
  { id:"pn4", title:"Travel Details Uploaded",        body:"Your travel itinerary has been added to your attendee portal. Please review and confirm.", target:"attendees",  status:"sent",      sentAt:"Mar 18, 14:00", opened:"67%" },
  { id:"pn5", title:"7-Day Countdown 🎉",              body:"MENA Summit 2026 is one week away! Full agenda and logistics info now available.",         target:"all",        status:"scheduled", sentAt:"Apr 7, 09:00" },
  { id:"pn6", title:"Day 1 Morning Briefing",          body:"Good morning! Registration opens at 08:00. See you at the Grand Ballroom entrance.",       target:"attendees",  status:"draft" },
];
const PN_TARGET_CLS: Record<string,string> = {
  all:        "bg-violet-100 text-violet-700",
  organizers: "bg-emerald-100 text-emerald-700",
  attendees:  "bg-blue-100 text-blue-700",
};

function PushNotificationsPage() {
  const [notifs,      setNotifs]     = useState<PushNotif[]>(PUSH_SEED);
  const [showForm,    setShowForm]   = useState(false);
  const [fTitle,      setFTitle]     = useState("");
  const [fBody,       setFBody]      = useState("");
  const [fTarget,     setFTarget]    = useState<"organizers"|"attendees"|"all">("all");
  const [fSchedule,   setFSchedule]  = useState(false);
  const [fDate,       setFDate]      = useState("");

  function sendNow() {
    if(!fTitle.trim()||!fBody.trim()) return;
    const n:PushNotif = { id:"pn"+Date.now(), title:fTitle.trim(), body:fBody.trim(), target:fTarget,
      status: fSchedule?"scheduled":"sent", sentAt: fSchedule?fDate:"Just now", opened: fSchedule?undefined:"—" };
    setNotifs(ns=>[n,...ns]);
    setShowForm(false); setFTitle(""); setFBody(""); setFDate(""); setFSchedule(false);
  }

  const sent      = notifs.filter(n=>n.status==="sent").length;
  const scheduled = notifs.filter(n=>n.status==="scheduled").length;
  const drafts    = notifs.filter(n=>n.status==="draft").length;

  return (
    <div className="space-y-5">
      {/* Hero */}
      <div className="bg-gradient-to-r from-indigo-600 to-blue-700 rounded-2xl p-5 text-white">
        <p className="text-xs font-semibold text-white/60 mb-1">Engage</p>
        <h2 className="text-lg font-bold mb-1">Push Notifications</h2>
        <p className="text-sm text-white/80">Send real-time alerts to organizers or attendees via the portal app.</p>
        <div className="flex gap-3 mt-3 text-xs font-semibold flex-wrap">
          <span className="bg-white/20 px-2.5 py-1 rounded-full">{notifs.length} total</span>
          <span className="bg-emerald-400/30 px-2.5 py-1 rounded-full">{sent} sent</span>
          {scheduled>0&&<span className="bg-amber-300/30 px-2.5 py-1 rounded-full">{scheduled} scheduled</span>}
          {drafts>0&&<span className="bg-white/10 px-2.5 py-1 rounded-full">{drafts} drafts</span>}
        </div>
      </div>

      {/* Create button */}
      <div className="flex justify-between items-center">
        <p className="text-xs font-semibold text-gray-500">Recent Notifications</p>
        <button onClick={()=>setShowForm(f=>!f)}
          className={`flex items-center gap-1.5 text-xs font-semibold px-3 py-1.5 rounded-lg border transition-colors ${
            showForm?"bg-gray-100 border-gray-200 text-gray-600":"bg-indigo-600 text-white border-indigo-600 hover:bg-indigo-700"
          }`}>
          {showForm?<><X size={12}/> Cancel</>:<><Plus size={12}/> Create Notification</>}
        </button>
      </div>

      {/* Create form */}
      {showForm && (
        <div className="bg-white border border-indigo-200 rounded-2xl p-5 shadow-sm space-y-4">
          <p className="text-sm font-bold text-indigo-700">New Push Notification</p>
          <div>
            <label className="block text-[10px] font-bold text-gray-500 uppercase tracking-wide mb-1">Title *</label>
            <input value={fTitle} onChange={e=>setFTitle(e.target.value)} placeholder="Short attention-grabbing title…"
              className="w-full text-xs border border-gray-200 rounded-lg px-3 py-2 focus:outline-none focus:border-indigo-400"/>
          </div>
          <div>
            <label className="block text-[10px] font-bold text-gray-500 uppercase tracking-wide mb-1">Message *</label>
            <textarea value={fBody} onChange={e=>setFBody(e.target.value)} rows={3} placeholder="Notification body text…"
              className="w-full text-xs border border-gray-200 rounded-lg px-3 py-2 focus:outline-none focus:border-indigo-400 resize-none"/>
            <p className="text-[10px] text-gray-400 mt-0.5">{fBody.length}/140 characters</p>
          </div>
          <div>
            <label className="block text-[10px] font-bold text-gray-500 uppercase tracking-wide mb-1.5">Send To *</label>
            <div className="flex gap-2">
              {(["all","organizers","attendees"] as const).map(t=>(
                <button key={t} onClick={()=>setFTarget(t)}
                  className={`flex-1 text-xs font-semibold py-2 rounded-lg border capitalize transition-colors ${
                    fTarget===t?"bg-indigo-600 text-white border-indigo-600":"bg-white text-gray-500 border-gray-200 hover:border-indigo-300"
                  }`}>{t==="all"?"Everyone":t}</button>
              ))}
            </div>
          </div>
          <div className="flex items-center gap-3">
            <label className="flex items-center gap-2 cursor-pointer">
              <input type="checkbox" checked={fSchedule} onChange={e=>setFSchedule(e.target.checked)} className="rounded"/>
              <span className="text-xs font-semibold text-gray-600">Schedule for later</span>
            </label>
            {fSchedule && (
              <input type="text" value={fDate} onChange={e=>setFDate(e.target.value)} placeholder="e.g. Apr 7, 09:00"
                className="flex-1 text-xs border border-gray-200 rounded-lg px-3 py-1.5 focus:outline-none focus:border-indigo-400"/>
            )}
          </div>
          <div className="flex gap-2 pt-1">
            <button onClick={sendNow}
              className="flex items-center gap-1.5 text-xs font-bold px-4 py-2 bg-indigo-600 text-white rounded-lg hover:bg-indigo-700">
              <Send size={12}/> {fSchedule?"Schedule":"Send Now"}
            </button>
            <button onClick={()=>setShowForm(false)} className="text-xs font-semibold px-3 py-2 border border-gray-200 text-gray-500 rounded-lg hover:bg-gray-50">Cancel</button>
          </div>
        </div>
      )}

      {/* Notification list */}
      <div className="space-y-2">
        {notifs.map(n=>(
          <div key={n.id} className="bg-white border border-gray-200 rounded-xl px-4 py-3.5 shadow-sm">
            <div className="flex items-start gap-3">
              <div className={`w-8 h-8 rounded-xl flex items-center justify-center flex-shrink-0 ${
                n.status==="sent"?"bg-indigo-100":n.status==="scheduled"?"bg-amber-100":"bg-gray-100"
              }`}>
                <Bell size={13} className={n.status==="sent"?"text-indigo-600":n.status==="scheduled"?"text-amber-600":"text-gray-400"}/>
              </div>
              <div className="flex-1 min-w-0">
                <div className="flex items-center gap-2 flex-wrap">
                  <p className="text-sm font-semibold text-gray-800">{n.title}</p>
                  <span className={`text-[9px] font-bold px-1.5 py-0.5 rounded-full ${PN_TARGET_CLS[n.target]}`}>
                    {n.target==="all"?"Everyone":n.target==="organizers"?"Organizers":"Attendees"}
                  </span>
                  <span className={`text-[9px] font-bold px-1.5 py-0.5 rounded-full ${
                    n.status==="sent"?"bg-emerald-100 text-emerald-700":n.status==="scheduled"?"bg-amber-100 text-amber-700":"bg-gray-100 text-gray-500"
                  }`}>{n.status}</span>
                </div>
                <p className="text-[11px] text-gray-500 mt-0.5 leading-snug">{n.body}</p>
                <div className="flex items-center gap-3 mt-1.5 text-[10px] text-gray-400">
                  {n.sentAt&&<span><Clock size={9} className="inline mr-0.5"/>{n.sentAt}</span>}
                  {n.opened&&<span className="text-emerald-600 font-semibold">{n.opened} opened</span>}
                </div>
              </div>
            </div>
          </div>
        ))}
      </div>
    </div>
  );
}

// ─── SurveysPage ───────────────────────────────────────────────────────────────
type Survey = { id:string; title:string; target:string; status:"active"|"closed"|"draft"; responses:number; total:number; closing?:string; questions:number };
const SURVEY_SEED: Survey[] = [
  { id:"sv1", title:"Pre-Event Attendee Expectations",    target:"Accepted Attendees", status:"active",  responses:184, total:280, closing:"Apr 5",  questions:10 },
  { id:"sv2", title:"Speaker Session Preferences",        target:"Speakers",           status:"active",  responses:22,  total:28,  closing:"Apr 3",  questions:7  },
  { id:"sv3", title:"Dietary & Accessibility Requirements",target:"All Attendees",     status:"active",  responses:201, total:312, closing:"Apr 8",  questions:5  },
  { id:"sv4", title:"Post-Event Attendee Feedback",       target:"All Attendees",      status:"draft",   responses:0,   total:312, questions:15 },
  { id:"sv5", title:"Speaker Satisfaction Survey",        target:"Speakers",           status:"draft",   responses:0,   total:28,  questions:8  },
  { id:"sv6", title:"Volunteer Experience Review",        target:"Volunteers",         status:"closed",  responses:34,  total:35,  questions:12 },
];
function SurveysPage() {
  const [surveys, setSurveys] = useState<Survey[]>(SURVEY_SEED);
  void setSurveys;
  const active = surveys.filter(s=>s.status==="active").length;
  const closed = surveys.filter(s=>s.status==="closed").length;
  const totalResp = surveys.reduce((a,s)=>a+s.responses,0);
  return (
    <div className="space-y-5">
      {/* Hero */}
      <div className="bg-gradient-to-r from-teal-600 to-cyan-700 rounded-2xl p-5 text-white">
        <p className="text-xs font-semibold text-white/60 mb-1">Engage</p>
        <h2 className="text-lg font-bold mb-1">Surveys</h2>
        <p className="text-sm text-white/80">Collect feedback and preferences from attendees, speakers, and volunteers.</p>
        <div className="flex gap-3 mt-3 text-xs font-semibold flex-wrap">
          <span className="bg-white/20 px-2.5 py-1 rounded-full">{surveys.length} surveys</span>
          <span className="bg-emerald-400/30 px-2.5 py-1 rounded-full">{active} active</span>
          <span className="bg-white/10 px-2.5 py-1 rounded-full">{closed} closed</span>
          <span className="bg-white/15 px-2.5 py-1 rounded-full">{totalResp} total responses</span>
        </div>
      </div>

      {/* Action */}
      <div className="flex justify-end">
        <button className="flex items-center gap-1.5 text-xs font-semibold px-3 py-1.5 bg-teal-600 text-white rounded-lg hover:bg-teal-700">
          <Plus size={12}/> Create Survey
        </button>
      </div>

      {/* Cards */}
      <div className="grid grid-cols-1 gap-3">
        {surveys.map(s=>{
          const pct = s.total>0?Math.round(s.responses/s.total*100):0;
          return (
            <div key={s.id} className="bg-white border border-gray-200 rounded-2xl p-5 shadow-sm">
              <div className="flex items-start gap-4">
                <div className="flex-1">
                  <div className="flex items-center gap-2 flex-wrap mb-1">
                    <h3 className="text-sm font-bold text-gray-900">{s.title}</h3>
                    <span className={`text-[9px] font-bold px-1.5 py-0.5 rounded-full ${
                      s.status==="active"?"bg-emerald-100 text-emerald-700":s.status==="closed"?"bg-gray-100 text-gray-500":"bg-amber-100 text-amber-700"
                    }`}>{s.status}</span>
                  </div>
                  <div className="flex items-center gap-3 text-[10px] text-gray-500 flex-wrap">
                    <span>Audience: <span className="font-semibold text-gray-700">{s.target}</span></span>
                    <span>{s.questions} questions</span>
                    {s.closing&&<span className="text-amber-600 font-semibold">Closes {s.closing}</span>}
                  </div>
                </div>
                <div className="text-right flex-shrink-0">
                  <p className="text-lg font-extrabold text-teal-700">{pct}%</p>
                  <p className="text-[10px] text-gray-400">{s.responses}/{s.total} responded</p>
                </div>
              </div>
              {s.status!=="draft"&&(
                <div className="mt-3">
                  <div className="h-1.5 bg-gray-100 rounded-full overflow-hidden">
                    <div className="h-full bg-teal-500 rounded-full transition-all" style={{width:`${pct}%`}}/>
                  </div>
                </div>
              )}
              <div className="flex gap-2 mt-3">
                <button className="text-[11px] font-semibold px-3 py-1.5 bg-teal-50 text-teal-700 border border-teal-200 rounded-lg hover:bg-teal-100">
                  {s.status==="draft"?"Edit & Launch":"View Results"}
                </button>
                <button className="text-[11px] font-semibold px-3 py-1.5 border border-gray-200 text-gray-500 rounded-lg hover:bg-gray-50 flex items-center gap-1">
                  <Share2 size={10}/> Share Link
                </button>
              </div>
            </div>
          );
        })}
      </div>
    </div>
  );
}

// ─── RegFormsPage ─────────────────────────────────────────────────────────────
type RegForm = { id:string; name:string; audience:string; status:"active"|"draft"|"closed"; submissions:number; capacity?:number; fields:string[]; deadline?:string };
const REG_FORMS_SEED: RegForm[] = [
  { id:"rf1", name:"General Attendee Registration",  audience:"Accepted Attendees",  status:"active",  submissions:192, capacity:312, deadline:"Apr 1",
    fields:["Full name","Email","Affiliation","Country","Dietary requirements","T-shirt size","Accessibility needs","Emergency contact"] },
  { id:"rf2", name:"Speaker Information Form",        audience:"Confirmed Speakers",  status:"active",  submissions:25,  capacity:28,  deadline:"Apr 1",
    fields:["Full name","Bio (150 words)","Headshot upload","Session title","Slide deck upload","AV requirements","Travel booked?","Hotel needed?"] },
  { id:"rf3", name:"Sponsor Onboarding Form",         audience:"Confirmed Sponsors",  status:"active",  submissions:11,  capacity:13,  deadline:"Apr 3",
    fields:["Company name","Contact name","Logo upload (SVG)","Brand guidelines PDF","Booth preferences","Guest pass count","Promo materials shipping"] },
  { id:"rf4", name:"Volunteer Registration",          audience:"Volunteers",          status:"closed",  submissions:45,  capacity:45,  deadline:"Mar 1",
    fields:["Full name","Email","Availability (days)","Role preference","Prior event experience","Languages spoken"] },
  { id:"rf5", name:"Poster Session Submission",       audience:"Poster Presenters",   status:"active",  submissions:28,  capacity:32,  deadline:"Apr 5",
    fields:["Full name","Email","Poster title","Abstract (250 words)","PDF upload","Co-authors","Research area"] },
  { id:"rf6", name:"Post-Event Certificate Request",  audience:"All Attendees",       status:"draft",   submissions:0,
    fields:["Full name","Email","Attendance confirmation","Sessions attended"] },
];
const RF_AUD_CLS: Record<string,string> = {
  "Accepted Attendees":  "bg-teal-100 text-teal-700",
  "Confirmed Speakers":  "bg-violet-100 text-violet-700",
  "Confirmed Sponsors":  "bg-amber-100 text-amber-700",
  "Volunteers":          "bg-emerald-100 text-emerald-700",
  "Poster Presenters":   "bg-orange-100 text-orange-700",
  "All Attendees":       "bg-blue-100 text-blue-700",
};
function RegFormsPage() {
  const [expanded, setExpanded] = useState<string|null>(null);
  const active  = REG_FORMS_SEED.filter(f=>f.status==="active").length;
  const totalSub= REG_FORMS_SEED.reduce((a,f)=>a+f.submissions,0);
  return (
    <div className="space-y-5">
      {/* Hero */}
      <div className="bg-gradient-to-r from-rose-600 to-pink-700 rounded-2xl p-5 text-white">
        <p className="text-xs font-semibold text-white/60 mb-1">Engage</p>
        <h2 className="text-lg font-bold mb-1">Registration Forms</h2>
        <p className="text-sm text-white/80">Custom forms for every participant category — collect the right info, from the right people.</p>
        <div className="flex gap-3 mt-3 text-xs font-semibold flex-wrap">
          <span className="bg-white/20 px-2.5 py-1 rounded-full">{REG_FORMS_SEED.length} forms</span>
          <span className="bg-emerald-400/30 px-2.5 py-1 rounded-full">{active} active</span>
          <span className="bg-white/15 px-2.5 py-1 rounded-full">{totalSub} submissions</span>
        </div>
      </div>

      {/* Action */}
      <div className="flex justify-end">
        <button className="flex items-center gap-1.5 text-xs font-semibold px-3 py-1.5 bg-rose-600 text-white rounded-lg hover:bg-rose-700">
          <Plus size={12}/> New Form
        </button>
      </div>

      {/* Form cards */}
      <div className="space-y-3">
        {REG_FORMS_SEED.map(form=>{
          const pct      = form.capacity?Math.round(form.submissions/form.capacity*100):null;
          const isOpen   = expanded===form.id;
          return (
            <div key={form.id} className={`bg-white border rounded-2xl shadow-sm overflow-hidden transition-all ${isOpen?"border-rose-300":"border-gray-200"}`}>
              <button onClick={()=>setExpanded(isOpen?null:form.id)}
                className="w-full flex items-start gap-4 px-5 py-4 text-left hover:bg-gray-50 transition-colors">
                <div className="flex-1">
                  <div className="flex items-center gap-2 flex-wrap mb-1">
                    <h3 className="text-sm font-bold text-gray-900">{form.name}</h3>
                    <span className={`text-[9px] font-bold px-1.5 py-0.5 rounded-full ${RF_AUD_CLS[form.audience]||"bg-gray-100 text-gray-600"}`}>{form.audience}</span>
                    <span className={`text-[9px] font-bold px-1.5 py-0.5 rounded-full ${
                      form.status==="active"?"bg-emerald-100 text-emerald-700":form.status==="closed"?"bg-gray-100 text-gray-500":"bg-amber-100 text-amber-700"
                    }`}>{form.status}</span>
                  </div>
                  <div className="flex items-center gap-3 text-[10px] text-gray-500 flex-wrap">
                    <span><span className="font-semibold text-gray-700">{form.submissions}</span> submissions{form.capacity?` / ${form.capacity}`:""}</span>
                    <span>{form.fields.length} fields</span>
                    {form.deadline&&<span className="text-rose-600 font-semibold">Deadline: {form.deadline}</span>}
                  </div>
                  {pct!==null&&(
                    <div className="mt-2 h-1.5 bg-gray-100 rounded-full overflow-hidden w-48">
                      <div className={`h-full rounded-full ${pct>=100?"bg-red-500":pct>=75?"bg-amber-500":"bg-rose-500"}`} style={{width:`${Math.min(pct,100)}%`}}/>
                    </div>
                  )}
                </div>
                <ChevronDown size={14} className={`text-gray-400 mt-0.5 flex-shrink-0 transition-transform ${isOpen?"rotate-180":""}`}/>
              </button>

              {isOpen&&(
                <div className="px-5 pb-5 border-t border-gray-100">
                  <p className="text-[10px] font-bold text-gray-400 uppercase tracking-wide mt-3 mb-2">Form Fields ({form.fields.length})</p>
                  <div className="grid grid-cols-2 gap-1.5">
                    {form.fields.map((f,i)=>(
                      <div key={i} className="flex items-center gap-1.5 text-[11px] text-gray-700 bg-gray-50 border border-gray-100 rounded-lg px-2.5 py-1.5">
                        <span className="w-4 h-4 rounded-full bg-rose-100 text-rose-700 text-[8px] font-bold flex items-center justify-center flex-shrink-0">{i+1}</span>
                        {f}
                      </div>
                    ))}
                  </div>
                  <div className="flex gap-2 mt-3">
                    <button className="text-[11px] font-semibold px-3 py-1.5 bg-rose-50 text-rose-700 border border-rose-200 rounded-lg hover:bg-rose-100">
                      <Edit size={10} className="inline mr-1"/>Edit Form
                    </button>
                    <button className="text-[11px] font-semibold px-3 py-1.5 border border-gray-200 text-gray-500 rounded-lg hover:bg-gray-50 flex items-center gap-1">
                      <Download size={10}/> Export CSV
                    </button>
                    {form.status==="active"&&(
                      <button className="text-[11px] font-semibold px-3 py-1.5 border border-gray-200 text-gray-500 rounded-lg hover:bg-gray-50 flex items-center gap-1">
                        <Share2 size={10}/> Share Link
                      </button>
                    )}
                  </div>
                </div>
              )}
            </div>
          );
        })}
      </div>
    </div>
  );
}

