function VideoPhotoPage() {
  const [contacts, setContacts] = useState<VPContact[]>(VP_SEED);
  const [editNotes, setEditNotes] = useState<string | null>(null);
  const [notesDraft, setNotesDraft] = useState("");
  const [search, setSearch] = useState("");
  const [roleFilter, setRoleFilter] = useState("All");

  const roles = ["All", ...Array.from(new Set(VP_SEED.map(c => c.role.split("—")[0].trim())))];
  const filtered = contacts.filter(c => {
    const q = search.toLowerCase();
    const matchQ = !q || c.name.toLowerCase().includes(q) || c.company.toLowerCase().includes(q) || c.role.toLowerCase().includes(q) || c.location.toLowerCase().includes(q);
    const matchR = roleFilter === "All" || c.role.toLowerCase().includes(roleFilter.toLowerCase());
    return matchQ && matchR;
  });

  const totalDays   = contacts.filter(c=>c.status==="confirmed").length;
  const totalBudget = contacts.reduce((s,c)=>s+c.dayRate, 0);
  const confirmed   = contacts.filter(c=>c.status==="confirmed").length;
  const pending     = contacts.filter(c=>c.status!=="confirmed").length;

  function saveNotes(id: string) {
    setContacts(cs => cs.map(c => c.id === id ? { ...c, notes: notesDraft } : c));
    setEditNotes(null);
  }
  function markConfirmed(id: string) {
    setContacts(cs => cs.map(c => c.id === id ? { ...c, status: "confirmed" } : c));
  }

  return (
    <div className="space-y-5">
      {/* Hero */}
      <div className="bg-gradient-to-r from-gray-800 to-slate-900 rounded-2xl p-5 text-white">
        <p className="text-xs font-semibold text-white/60 mb-1">Comms &amp; Branding</p>
        <h2 className="text-lg font-bold mb-1">Video Recording &amp; Photography</h2>
        <p className="text-sm text-white/80">All media crew for MENA Summit 2026 — contacts, schedules and pricing.</p>
        <div className="flex gap-3 mt-3 text-xs font-semibold flex-wrap">
          <span className="bg-white/20 px-2.5 py-1 rounded-full">{contacts.length} crew members</span>
          <span className="bg-emerald-400/30 px-2.5 py-1 rounded-full">{confirmed} confirmed</span>
          {pending > 0 && <span className="bg-amber-300/30 px-2.5 py-1 rounded-full">{pending} pending / tentative</span>}
          <span className="bg-white/10 px-2.5 py-1 rounded-full">AED {totalBudget.toLocaleString()} total day rates</span>
        </div>
      </div>

      {/* Summary cards */}
      <div className="grid grid-cols-4 gap-3">
        {[
          { label:"Total Crew",      value: contacts.length,                      sub:"photographers & videographers", cls:"text-slate-700",   bg:"bg-slate-50",   border:"border-slate-200" },
          { label:"Confirmed",       value: confirmed,                             sub:"contracts signed",              cls:"text-emerald-700", bg:"bg-emerald-50", border:"border-emerald-200" },
          { label:"Total Day Rates", value:`AED ${totalBudget.toLocaleString()}`, sub:"excl. travel & equipment",      cls:"text-violet-700",  bg:"bg-violet-50",  border:"border-violet-200" },
          { label:"Days On-Site",    value: totalDays,                             sub:"crew-days across event",        cls:"text-blue-700",    bg:"bg-blue-50",    border:"border-blue-200" },
        ].map(c => (
          <div key={c.label} className={`${c.bg} border ${c.border} rounded-xl p-3.5`}>
            <p className={`text-lg font-extrabold ${c.cls}`}>{c.value}</p>
            <p className="text-[11px] font-semibold text-gray-600 mt-0.5">{c.label}</p>
            <p className="text-[10px] text-gray-400">{c.sub}</p>
          </div>
        ))}
      </div>

      {/* Toolbar */}
      <div className="flex items-center gap-3 flex-wrap">
        <div className="relative flex-1 min-w-48">
          <Search size={12} className="absolute left-3 top-1/2 -translate-y-1/2 text-gray-400" />
          <input value={search} onChange={e => setSearch(e.target.value)} placeholder="Search name, company, role, location…"
            className="w-full text-xs border border-gray-200 rounded-lg pl-8 pr-3 py-2 focus:outline-none focus:border-slate-400 bg-white" />
        </div>
        <div className="flex gap-1 flex-wrap">
          {["All","Videographer","Photographer","Drone"].map(r => (
            <button key={r} onClick={()=>setRoleFilter(r)}
              className={`text-[11px] font-semibold px-2.5 py-1 rounded-full border transition-colors ${
                roleFilter===r ? "bg-slate-800 text-white border-slate-800" : "bg-white text-gray-500 border-gray-200 hover:border-gray-300"
              }`}>{r}</button>
          ))}
        </div>
        <button className="flex items-center gap-1.5 text-xs font-semibold px-3 py-1.5 bg-slate-800 text-white rounded-lg hover:bg-slate-900 ml-auto">
          <Plus size={12} /> Add Contact
        </button>
      </div>

      {/* Table */}
      <div className="bg-white border border-gray-200 rounded-2xl shadow-sm overflow-hidden">
        <div className="overflow-x-auto">
          <table className="w-full text-xs">
            <thead>
              <tr className="bg-gray-50 border-b border-gray-200">
                <th className="text-left px-4 py-3 text-[10px] font-bold text-gray-500 uppercase tracking-wide">Contact</th>
                <th className="text-left px-3 py-3 text-[10px] font-bold text-gray-500 uppercase tracking-wide">Role</th>
                <th className="text-left px-3 py-3 text-[10px] font-bold text-gray-500 uppercase tracking-wide">Location</th>
                <th className="text-left px-3 py-3 text-[10px] font-bold text-gray-500 uppercase tracking-wide">Working Hours</th>
                <th className="text-right px-3 py-3 text-[10px] font-bold text-gray-500 uppercase tracking-wide">Day Rate</th>
                <th className="text-right px-3 py-3 text-[10px] font-bold text-gray-500 uppercase tracking-wide">½-Day Rate</th>
                <th className="text-left px-3 py-3 text-[10px] font-bold text-gray-500 uppercase tracking-wide">Status</th>
                <th className="text-left px-3 py-3 text-[10px] font-bold text-gray-500 uppercase tracking-wide">Notes</th>
                <th className="px-3 py-3 w-8" />
              </tr>
            </thead>
            <tbody className="divide-y divide-gray-100">
              {filtered.map((c, i) => (
                <tr key={c.id} className={`hover:bg-gray-50/60 transition-colors ${i % 2 === 0 ? "bg-white" : "bg-gray-50/30"}`}>
                  {/* Contact */}
                  <td className="px-4 py-3">
                    <p className="font-semibold text-gray-900">{c.name}</p>
                    <p className="text-[10px] text-gray-400 mt-0.5">{c.company}</p>
                    <div className="flex flex-col gap-0.5 mt-1">
                      <a href={`mailto:${c.email}`} className="text-[10px] text-blue-500 hover:underline truncate max-w-[160px]">{c.email}</a>
                      <span className="text-[10px] text-gray-400">{c.phone}</span>
                    </div>
                  </td>

                  {/* Role */}
                  <td className="px-3 py-3">
                    <span className={`text-[10px] font-bold px-2 py-0.5 rounded-full ${
                      c.role.toLowerCase().includes("video") ? "bg-violet-100 text-violet-700"
                      : c.role.toLowerCase().includes("drone") ? "bg-sky-100 text-sky-700"
                      : "bg-pink-100 text-pink-700"
                    }`}>{c.role.split("—")[0].trim()}</span>
                    {c.role.includes("—") && <p className="text-[10px] text-gray-400 mt-1">{c.role.split("—")[1].trim()}</p>}
                  </td>

                  {/* Location */}
                  <td className="px-3 py-3">
                    <div className="flex items-center gap-1 text-gray-600">
                      <MapPin size={10} className="text-gray-400 flex-shrink-0" />
                      <span className="text-[11px]">{c.location}</span>
                    </div>
                  </td>

                  {/* Working hours */}
                  <td className="px-3 py-3">
                    <div className="flex items-start gap-1 text-gray-600">
                      <Clock size={10} className="text-gray-400 flex-shrink-0 mt-0.5" />
                      <span className="text-[11px] leading-snug">{c.workingHours}</span>
                    </div>
                  </td>

                  {/* Day rate */}
                  <td className="px-3 py-3 text-right font-bold text-gray-800">AED {c.dayRate.toLocaleString()}</td>

                  {/* Half-day rate */}
                  <td className="px-3 py-3 text-right text-gray-500">AED {c.halfDayRate.toLocaleString()}</td>

                  {/* Status */}
                  <td className="px-3 py-3">
                    <span className={`text-[10px] font-bold px-2 py-0.5 rounded-full border capitalize ${VP_STATUS_CLS[c.status]}`}>
                      {c.status}
                    </span>
                    {c.status !== "confirmed" && (
                      <button onClick={() => markConfirmed(c.id)} className="block mt-1 text-[9px] font-semibold text-emerald-600 hover:underline">
                        → Confirm
                      </button>
                    )}
                  </td>

                  {/* Notes */}
                  <td className="px-3 py-3 max-w-[200px]">
                    {editNotes === c.id ? (
                      <div className="flex items-center gap-1">
                        <input autoFocus value={notesDraft} onChange={e => setNotesDraft(e.target.value)}
                          onKeyDown={e => { if (e.key === "Enter") saveNotes(c.id); if (e.key === "Escape") setEditNotes(null); }}
                          className="flex-1 text-[11px] border border-slate-300 rounded px-1.5 py-0.5 focus:outline-none min-w-0" />
                        <button onClick={() => saveNotes(c.id)} className="text-emerald-600 hover:text-emerald-700"><Check size={11} /></button>
                        <button onClick={() => setEditNotes(null)} className="text-gray-400 hover:text-gray-600"><X size={11} /></button>
                      </div>
                    ) : (
                      <button onClick={() => { setEditNotes(c.id); setNotesDraft(c.notes); }}
                        className="text-left w-full group flex items-start gap-1">
                        <span className={`text-[11px] leading-snug ${c.notes ? "text-gray-600" : "text-gray-300 italic"}`}>
                          {c.notes || "Add note…"}
                        </span>
                        <Edit size={9} className="text-gray-300 group-hover:text-gray-500 flex-shrink-0 mt-0.5 opacity-0 group-hover:opacity-100 transition-opacity" />
                      </button>
                    )}
                  </td>

                  {/* Actions */}
                  <td className="px-3 py-3">
                    <button className="p-1 rounded hover:bg-gray-100 text-gray-400 hover:text-gray-600">
                      <MoreHorizontal size={13} />
                    </button>
                  </td>
                </tr>
              ))}
              {filtered.length === 0 && (
                <tr>
                  <td colSpan={9} className="text-center py-10 text-gray-400 text-xs">No contacts match your search.</td>
                </tr>
              )}
            </tbody>
            {/* Totals footer */}
            {roleFilter === "All" && !search && (
              <tfoot>
                <tr className="bg-slate-50 border-t-2 border-slate-200">
                  <td colSpan={4} className="px-4 py-2.5 text-xs font-bold text-slate-700">Total (Day Rates)</td>
                  <td className="px-3 py-2.5 text-right text-sm font-extrabold text-slate-800">
                    AED {contacts.reduce((s, c) => s + c.dayRate, 0).toLocaleString()}
                  </td>
                  <td className="px-3 py-2.5 text-right text-sm font-bold text-slate-600">
                    AED {contacts.reduce((s, c) => s + c.halfDayRate, 0).toLocaleString()}
                  </td>
                  <td colSpan={3} />
                </tr>
              </tfoot>
            )}
          </table>
        </div>
      </div>
    </div>
  );
}

// ─── MyTeamsPage ──────────────────────────────────────────────────────────────
function MyTeamsPage() {
  const [docs,        setDocs]        = useState<TeamDoc[]>(SEED_TEAM_DOCS);
  const [addingTeam,  setAddingTeam]  = useState<string|null>(null);
  const [selectedDoc, setSelectedDoc] = useState<TeamDoc|null>(null);
  const [fTitle,      setFTitle]      = useState("");
  const [fSummary,    setFSummary]    = useState("");
  const [fDecisions,  setFDecisions]  = useState("");
  const [fActions,    setFActions]    = useState("");

  function openForm(teamId: string) {
    setAddingTeam(teamId); setFTitle(""); setFSummary(""); setFDecisions(""); setFActions("");
  }
  function saveDoc(teamId: string) {
    if(!fTitle.trim()) return;
    const newDoc: TeamDoc = {
      id: "td"+Date.now(), teamId,
      title:     fTitle.trim(),
      date:      "Mar 19, 2026",
      author:    "Sara Al-Amri",
      summary:   fSummary.trim()||"No summary provided.",
      decisions: fDecisions.split("\n").map(s=>s.trim()).filter(Boolean),
      actions:   fActions.split("\n").map(s=>s.trim()).filter(Boolean),
    };
    setDocs(d=>[...d, newDoc]);
    setAddingTeam(null);
    setSelectedDoc(newDoc);
  }

  return (
    <div className="flex gap-5 h-full min-h-0" style={{height:"calc(100vh - 120px)"}}>

      {/* ── LEFT: team cards ── */}
      <div className="flex-1 overflow-y-auto space-y-5 pr-1">
        {/* Hero */}
        <div className="bg-gradient-to-r from-emerald-600 to-teal-600 rounded-2xl p-5 text-white">
          <p className="text-xs font-semibold text-white/70 mb-1">Sara Al-Amri · Organizer</p>
          <h2 className="text-lg font-bold mb-1">My Teams</h2>
          <p className="text-sm text-white/80">You are a member of {MY_TEAMS.length} teams for MENA Summit 2026.</p>
          <div className="flex gap-3 mt-3 text-xs font-semibold flex-wrap">
            {(["Team Lead","Member","Contributor"] as const).map(r=>(
              <span key={r} className="bg-white/20 px-2.5 py-1 rounded-full">{MY_TEAMS.filter(t=>t.role===r).length} {r}</span>
            ))}
            <span className="bg-white/10 px-2.5 py-1 rounded-full">{docs.length} meeting notes total</span>
          </div>
        </div>

        {/* One card per team */}
        {MY_TEAMS.map((team,ti)=>{
          const teamDocs = docs.filter(d=>d.teamId===team.id);
          const colours  = ["bg-emerald-500","bg-blue-500","bg-violet-500","bg-amber-500","bg-pink-500"];
          const isAdding = addingTeam===team.id;
          return (
            <div key={team.id} className={`bg-white border ${team.border} rounded-2xl overflow-hidden shadow-sm`}>

              {/* Header */}
              <div className={`${team.bg} px-5 py-4 flex items-start gap-3`}>
                <span className={`w-3 h-3 rounded-full ${team.dot} mt-1 flex-shrink-0`}/>
                <div className="flex-1">
                  <div className="flex items-center gap-2 flex-wrap">
                    <h3 className={`text-sm font-bold ${team.color}`}>{team.name}</h3>
                    <span className={`text-[9px] font-bold px-2 py-0.5 rounded-full border bg-white ${
                      team.role==="Team Lead" ? "text-emerald-700 border-emerald-300"
                      :team.role==="Member"  ? "text-blue-700 border-blue-200"
                      :                        "text-gray-600 border-gray-200"
                    }`}>{team.role}</span>
                  </div>
                  <p className="text-[11px] text-gray-500 mt-0.5">{team.description}</p>
                </div>
              </div>

              {/* Members */}
              <div className="px-5 py-3 border-t border-gray-100">
                <p className="text-[10px] font-bold text-gray-400 uppercase tracking-wide mb-2">Members</p>
                <div className="flex flex-wrap gap-1.5">
                  {team.members.map((m,i)=>{
                    const isSara = m==="Sara Al-Amri";
                    return (
                      <span key={i} className={`flex items-center gap-1.5 text-[10px] font-semibold px-2 py-0.5 rounded-full border ${
                        isSara?"bg-emerald-50 border-emerald-200 text-emerald-700":"bg-gray-50 border-gray-200 text-gray-600"
                      }`}>
                        <span className={`w-3.5 h-3.5 rounded-full ${colours[(ti*3+i)%colours.length]} flex items-center justify-center text-white text-[7px] font-bold`}>
                          {m.split(" ").map(n=>n[0]).join("").slice(0,2)}
                        </span>
                        {m}{isSara?" (you)":""}
                      </span>
                    );
                  })}
                </div>
              </div>

              {/* Meeting notes */}
              <div className="px-5 py-3 border-t border-gray-100">
                <div className="flex items-center justify-between mb-2">
                  <p className="text-[10px] font-bold text-gray-400 uppercase tracking-wide">
                    Meeting Notes <span className="text-gray-300 font-normal">({teamDocs.length})</span>
                  </p>
                  <button onClick={()=>isAdding?setAddingTeam(null):openForm(team.id)}
                    className={`flex items-center gap-1 text-[10px] font-semibold px-2.5 py-1 rounded-lg border transition-colors ${
                      isAdding ? "bg-gray-100 border-gray-200 text-gray-500"
                               : "bg-emerald-50 border-emerald-200 text-emerald-700 hover:bg-emerald-100"
                    }`}>
                    {isAdding ? <><X size={10}/> Cancel</> : <><Plus size={10}/> Add Note</>}
                  </button>
                </div>

                {/* Existing notes */}
                {teamDocs.length>0 && (
                  <div className="space-y-1.5 mb-2">
                    {teamDocs.map(doc=>(
                      <button key={doc.id} onClick={()=>setSelectedDoc(selectedDoc?.id===doc.id?null:doc)}
                        className={`w-full text-left flex items-start gap-2.5 px-3 py-2 rounded-xl border transition-all ${
                          selectedDoc?.id===doc.id
                            ? "bg-emerald-50 border-emerald-300"
                            : "bg-gray-50 border-gray-100 hover:border-gray-200 hover:bg-white"
                        }`}>
                        <FileText size={12} className={`mt-0.5 flex-shrink-0 ${selectedDoc?.id===doc.id?"text-emerald-600":"text-gray-400"}`}/>
                        <div className="flex-1 min-w-0">
                          <p className={`text-[11px] font-semibold truncate ${selectedDoc?.id===doc.id?"text-emerald-700":"text-gray-800"}`}>{doc.title}</p>
                          <p className="text-[10px] text-gray-400">{doc.date} · {doc.author}</p>
                        </div>
                        <ChevronRight size={11} className={`mt-0.5 flex-shrink-0 ${selectedDoc?.id===doc.id?"text-emerald-500":"text-gray-300"}`}/>
                      </button>
                    ))}
                  </div>
                )}
                {teamDocs.length===0 && !isAdding && (
                  <p className="text-[11px] text-gray-400 italic py-1">No meeting notes yet. Add the first one.</p>
                )}

                {/* Add form */}
                {isAdding && (
                  <div className="mt-2 p-4 bg-gray-50 border border-gray-200 rounded-xl space-y-3">
                    <p className="text-[10px] font-bold text-gray-600 uppercase tracking-wide">New Meeting Note</p>
                    <div>
                      <label className="block text-[10px] font-semibold text-gray-500 mb-1">Title *</label>
                      <input value={fTitle} onChange={e=>setFTitle(e.target.value)} placeholder="e.g. Weekly Sync — Apr 2"
                        className="w-full text-xs border border-gray-200 rounded-lg px-3 py-1.5 bg-white focus:outline-none focus:border-emerald-400"/>
                    </div>
                    <div>
                      <label className="block text-[10px] font-semibold text-gray-500 mb-1">Summary</label>
                      <textarea value={fSummary} onChange={e=>setFSummary(e.target.value)} rows={2} placeholder="What was discussed?"
                        className="w-full text-xs border border-gray-200 rounded-lg px-3 py-1.5 bg-white focus:outline-none focus:border-emerald-400 resize-none"/>
                    </div>
                    <div>
                      <label className="block text-[10px] font-semibold text-gray-500 mb-1">Decisions <span className="font-normal text-gray-400">(one per line)</span></label>
                      <textarea value={fDecisions} onChange={e=>setFDecisions(e.target.value)} rows={2} placeholder={"Decision A\nDecision B"}
                        className="w-full text-xs border border-gray-200 rounded-lg px-3 py-1.5 bg-white focus:outline-none focus:border-emerald-400 resize-none"/>
                    </div>
                    <div>
                      <label className="block text-[10px] font-semibold text-gray-500 mb-1">Action Items <span className="font-normal text-gray-400">(one per line)</span></label>
                      <textarea value={fActions} onChange={e=>setFActions(e.target.value)} rows={2} placeholder={"Sara: do X by Apr 5\nOmar: send Y"}
                        className="w-full text-xs border border-gray-200 rounded-lg px-3 py-1.5 bg-white focus:outline-none focus:border-emerald-400 resize-none"/>
                    </div>
                    <div className="flex gap-2 pt-1">
                      <button onClick={()=>saveDoc(team.id)}
                        className="flex items-center gap-1.5 text-[11px] font-bold px-3 py-1.5 bg-emerald-600 text-white rounded-lg hover:bg-emerald-700 transition-colors">
                        <CheckCircle2 size={11}/> Save Note
                      </button>
                      <button onClick={()=>setAddingTeam(null)}
                        className="text-[11px] font-semibold px-3 py-1.5 border border-gray-200 text-gray-500 rounded-lg hover:bg-gray-100 transition-colors">
                        Cancel
                      </button>
                    </div>
                  </div>
                )}
              </div>
            </div>
          );
        })}
      </div>

      {/* ── RIGHT: doc detail ── */}
      {selectedDoc ? (
        <div className="w-80 flex-shrink-0 overflow-y-auto">
          <div className="bg-white border border-gray-200 rounded-2xl shadow-sm overflow-hidden sticky top-0">
            {/* Detail header */}
            <div className="px-5 py-4 bg-gray-50 border-b border-gray-100 flex items-start gap-3">
              <FileText size={15} className="text-emerald-600 mt-0.5 flex-shrink-0"/>
              <div className="flex-1 min-w-0">
                <p className="text-sm font-bold text-gray-900 leading-snug">{selectedDoc.title}</p>
                <p className="text-[10px] text-gray-400 mt-0.5">{selectedDoc.date} · by {selectedDoc.author}</p>
              </div>
              <button onClick={()=>setSelectedDoc(null)} className="p-1 rounded-lg hover:bg-gray-200 text-gray-400">
                <X size={13}/>
              </button>
            </div>
            <div className="p-5 space-y-4">
              {/* Summary */}
              <div>
                <p className="text-[10px] font-bold text-gray-400 uppercase tracking-wide mb-1.5">Summary</p>
                <p className="text-xs text-gray-700 leading-relaxed">{selectedDoc.summary}</p>
              </div>
              {/* Decisions */}
              {selectedDoc.decisions.length>0 && (
                <div>
                  <p className="text-[10px] font-bold text-violet-600 uppercase tracking-wide mb-1.5">Decisions ({selectedDoc.decisions.length})</p>
                  <ul className="space-y-1">
                    {selectedDoc.decisions.map((d,i)=>(
                      <li key={i} className="flex items-start gap-2 text-xs text-gray-700">
                        <span className="w-4 h-4 rounded-full bg-violet-100 text-violet-700 text-[8px] font-bold flex items-center justify-center flex-shrink-0 mt-0.5">{i+1}</span>
                        {d}
                      </li>
                    ))}
                  </ul>
                </div>
              )}
              {/* Action items */}
              {selectedDoc.actions.length>0 && (
                <div>
                  <p className="text-[10px] font-bold text-amber-600 uppercase tracking-wide mb-1.5">Action Items ({selectedDoc.actions.length})</p>
                  <ul className="space-y-1.5">
                    {selectedDoc.actions.map((a,i)=>(
                      <li key={i} className="flex items-start gap-2 text-xs text-gray-700">
                        <CheckSquare size={11} className="text-amber-500 flex-shrink-0 mt-0.5"/>
                        {a}
                      </li>
                    ))}
                  </ul>
                </div>
              )}
              {selectedDoc.decisions.length===0 && selectedDoc.actions.length===0 && (
                <p className="text-xs text-gray-400 italic">No decisions or action items recorded.</p>
              )}
            </div>
          </div>
        </div>
      ) : (
        <div className="w-80 flex-shrink-0 flex items-center justify-center">
          <div className="text-center text-gray-300 p-8">
            <FileText size={32} className="mx-auto mb-3 opacity-40"/>
            <p className="text-sm font-semibold">Select a meeting note</p>
            <p className="text-xs mt-1">Click any note to read the full details here.</p>
          </div>
        </div>
      )}
    </div>
  );
}

// ─── MyTasksPage ───────────────────────────────────────────────────────────────
function MyTasksPage() {
  const [filter, setFilter] = useState<"all"|"todo"|"in-progress"|"done"|"core"|"organizer">("all");
  const filtered = MY_TASKS.filter(t=>{
    if(filter==="all") return true;
    if(filter==="core"||filter==="organizer") return t.assignerType===filter;
    return t.status===filter;
  });
  const open   = MY_TASKS.filter(t=>t.status!=="done").length;
  const done   = MY_TASKS.filter(t=>t.status==="done").length;
  const high   = MY_TASKS.filter(t=>t.priority==="High"&&t.status!=="done").length;
  return (
    <div className="space-y-5">
      {/* Hero */}
      <div className="bg-gradient-to-r from-slate-700 to-slate-900 rounded-2xl p-5 text-white">
        <p className="text-xs font-semibold text-white/60 mb-1">Sara Al-Amri · Organizer</p>
        <h2 className="text-lg font-bold mb-1">My Tasks</h2>
        <p className="text-sm text-white/70">Tasks assigned to you by the Core Team or fellow organizers.</p>
        <div className="flex gap-3 mt-3 text-xs font-semibold flex-wrap">
          <span className="bg-white/20 px-2.5 py-1 rounded-full">{open} open</span>
          <span className="bg-emerald-500/40 px-2.5 py-1 rounded-full">{done} done</span>
          {high>0 && <span className="bg-red-400/40 px-2.5 py-1 rounded-full">{high} high priority</span>}
          <span className="bg-white/10 px-2.5 py-1 rounded-full">{MY_TASKS.filter(t=>t.assignerType==="core").length} from Core Team</span>
          <span className="bg-white/10 px-2.5 py-1 rounded-full">{MY_TASKS.filter(t=>t.assignerType==="organizer").length} from Organizers</span>
        </div>
      </div>

      {/* Filter bar */}
      <div className="flex items-center gap-1.5 flex-wrap">
        <span className="text-xs text-gray-500 font-semibold mr-1">Filter:</span>
        {([
          { k:"all",         label:"All",           count: MY_TASKS.length },
          { k:"todo",        label:"To Do",         count: MY_TASKS.filter(t=>t.status==="todo").length },
          { k:"in-progress", label:"In Progress",   count: MY_TASKS.filter(t=>t.status==="in-progress").length },
          { k:"done",        label:"Done",          count: MY_TASKS.filter(t=>t.status==="done").length },
          { k:"core",        label:"Core Team",     count: MY_TASKS.filter(t=>t.assignerType==="core").length },
          { k:"organizer",   label:"Organizer",     count: MY_TASKS.filter(t=>t.assignerType==="organizer").length },
        ] as const).map(f=>(
          <button key={f.k} onClick={()=>setFilter(f.k as typeof filter)}
            className={`text-xs font-semibold px-3 py-1 rounded-full border transition-colors ${
              filter===f.k ? "bg-slate-900 text-white border-slate-900"
                           : "bg-white text-gray-500 border-gray-200 hover:border-gray-300"
            }`}>
            {f.label} <span className="opacity-60 ml-0.5">{f.count}</span>
          </button>
        ))}
      </div>

      {/* Task list */}
      <div className="space-y-3">
        {filtered.length===0 && (
          <div className="text-center py-12 text-gray-400 text-sm">No tasks match this filter.</div>
        )}
        {filtered.map(task=>(
          <div key={task.id} className={`bg-white border rounded-2xl p-4 shadow-sm transition-opacity ${task.status==="done"?"opacity-60":"opacity-100"}`}
            style={{borderColor: task.status==="done"?"#f3f4f6": task.priority==="High"?"#fecaca": task.priority==="Medium"?"#fde68a":"#e5e7eb"}}>
            <div className="flex items-start gap-3">
              {/* Status indicator */}
              <div className={`w-5 h-5 rounded-full border-2 flex items-center justify-center flex-shrink-0 mt-0.5 ${
                task.status==="done"       ? "bg-emerald-500 border-emerald-500"
                :task.status==="in-progress"? "border-blue-500 bg-blue-50"
                :                            "border-gray-300 bg-white"
              }`}>
                {task.status==="done"        && <CheckCircle2 size={11} className="text-white"/>}
                {task.status==="in-progress" && <div className="w-2 h-2 rounded-full bg-blue-500"/>}
              </div>

              <div className="flex-1 min-w-0">
                <p className={`text-sm font-semibold leading-snug ${task.status==="done"?"line-through text-gray-400":"text-gray-900"}`}>
                  {task.title}
                </p>

                {/* Chips row */}
                <div className="flex flex-wrap items-center gap-1.5 mt-2">
                  <span className={`text-[10px] font-bold px-2 py-0.5 rounded-full ${MY_TASK_STATUS_CLS[task.status]}`}>
                    {task.status==="todo"?"To Do":task.status==="in-progress"?"In Progress":"Done"}
                  </span>
                  <span className={`text-[10px] font-bold px-2 py-0.5 rounded-full ${MY_TASK_PRI_CLS[task.priority]}`}>
                    {task.priority} Priority
                  </span>
                  <span className="text-[10px] font-bold text-amber-700 bg-amber-50 border border-amber-200 px-2 py-0.5 rounded-full">
                    Due {task.dueDate}
                  </span>
                </div>

                {/* Assigned by */}
                <div className="flex items-center gap-2 mt-2.5">
                  <div className={`w-5 h-5 rounded-full flex items-center justify-center text-white text-[8px] font-bold flex-shrink-0 ${task.assignerType==="core"?"bg-emerald-600":"bg-blue-500"}`}>
                    {task.assignedBy.split(" ").map(n=>n[0]).join("").slice(0,2)}
                  </div>
                  <span className="text-[10px] text-gray-500">
                    Assigned by <span className="font-semibold text-gray-700">{task.assignedBy}</span>
                    <span className={`ml-1.5 text-[9px] font-bold px-1.5 py-0.5 rounded-full ${
                      task.assignerType==="core" ? "bg-emerald-100 text-emerald-700" : "bg-blue-100 text-blue-700"
                    }`}>
                      {task.assignerType==="core"?"Core Team":"Organizer"}
                    </span>
                  </span>
                </div>
              </div>
            </div>
          </div>
        ))}
      </div>
    </div>
  );
}

