export function Dashboard({ onLogout }: { onLogout?: () => void } = {}) {
  const [active, setActive] = useState<NavKey>("Overview");
  const [expandedNav, setExpandedNav] = useState<string | null>("Logistics");
  const [showUserMenu, setShowUserMenu] = useState(false);
  const [showMyTeams,  setShowMyTeams]  = useState(false);
  const [showMyTasks,  setShowMyTasks]  = useState(false);

  function renderPage() {
    switch (active) {
      case "Overview":       return <OverviewPage onNav={(k) => setActive(k)} />;
      case "Analytics":      return <AnalyticsPage />;
      case "Logistics":      return <LogisticsPage onNav={(k) => setActive(k as NavKey)} />;
      case "Venue":          return <VenuePage />;
      case "Flights":        return <FlightsPage />;
      case "Transportation": return <TransportationPage />;
      case "Accommodation":  return <AccommodationPage />;
      case "Catering":         return <CateringPage />;
      case "Volunteers":       return <VolunteersPage />;
      case "TechnicalSupport": return <TechnicalSupportPage />;
      case "Swag":             return <SwagPage />;
      case "CommsBranding":  return <CommsBrandingPage onNav={(k) => setActive(k as NavKey)} />;
      case "VenueBranding":  return <VenueBrandingPage />;
      case "VideoPhoto":     return <VideoPhotoPage />;
      case "Applications":   return <ApplicationsPage />;
      case "Registration":   return <RegistrationPage />;
      case "Badges":         return <BadgesPage />;
      case "Attendees":      return <AttendeesPage />;
      case "Agenda":         return <AgendaSummaryPage onNav={(k) => setActive(k as NavKey)} />;
      case "Schedule":       return <AgendaPage />;
      case "PosterSession":      return <PosterSessionPage />;
      case "MentorRoundTables":  return <MentorRoundTablesPage />;
      case "SocialEvents":       return <SocialEventsPage />;
      case "Invited Experts": return <InvitedExpertsPage />;
      case "Awards":         return <AwardsPage />;
      case "Socials":        return <SocialsPage />;
      case "Sponsors":       return <SponsorsPage />;
      case "Engage":             return <EmailLibraryPage />;
      case "EmailLibrary":       return <EmailLibraryPage />;
      case "PushNotifications":  return <PushNotificationsPage />;
      case "Surveys":            return <SurveysPage />;
      case "RegForms":           return <RegFormsPage />;
      case "MyTeams":        return <MyTeamsPage />;
      case "MyTasks":        return <MyTasksPage />;
      case "FAQ":            return <OrgFaqPage />;
      default:               return <OverviewPage onNav={(k) => setActive(k)} />;
    }
  }

  return (
    <div className="flex h-screen bg-gray-50 font-sans overflow-hidden">
      {/* Sidebar */}
      <aside className="w-60 bg-white border-r border-gray-200 flex flex-col shadow-sm flex-shrink-0">
        {/* Logo */}
        <div className="px-5 py-4 border-b border-gray-100">
          <div className="flex items-center gap-2.5">
            <div className="w-8 h-8 rounded-lg bg-gradient-to-br from-emerald-500 to-teal-600 flex items-center justify-center">
              <Globe size={17} className="text-white"/>
            </div>
            <div>
              <span className="text-base font-bold text-gray-900 tracking-tight">MenaML</span>
              <div className="text-[10px] text-gray-400 -mt-0.5">Event Management</div>
            </div>
          </div>
        </div>

        {/* Event selector */}
        <div className="px-4 py-3 border-b border-gray-100">
          <button className="w-full flex items-center gap-2 px-3 py-2 rounded-lg bg-gray-50 hover:bg-gray-100 transition-colors text-left">
            <div className="w-5 h-5 rounded bg-emerald-100 flex items-center justify-center flex-shrink-0">
              <Calendar size={11} className="text-emerald-600"/>
            </div>
            <div className="flex-1 min-w-0">
              <div className="text-xs font-semibold text-gray-800 truncate">MENA Summit 2026</div>
              <div className="text-[10px] text-gray-400">Apr 15–18, Dubai</div>
            </div>
            <ChevronDown size={13} className="text-gray-400 flex-shrink-0"/>
          </button>
        </div>

        {/* Nav */}
        <nav className="flex-1 overflow-y-auto py-2 px-2.5 space-y-0.5">
          {navItems.map((item) => {
            const Icon = item.icon;
            const isActive = active === item.label;
            const isExpanded = expandedNav === item.label;
            const childActive = item.children?.includes(active as NavKey);
            return (
              <div key={item.label}>
                <button
                  onClick={() => {
                    setActive(item.label as NavKey);
                    if (item.children) setExpandedNav(isExpanded ? null : item.label);
                  }}
                  className={`w-full flex items-center gap-2.5 px-3 py-1.5 rounded-lg text-sm transition-all ${
                    isActive || childActive
                      ? "bg-emerald-50 text-emerald-700 font-semibold"
                      : "text-gray-600 hover:bg-gray-50 hover:text-gray-900"
                  }`}
                >
                  <Icon size={15} className={isActive || childActive ? "text-emerald-600" : "text-gray-400"}/>
                  <span className="flex-1 text-left text-xs">{item.display ?? item.label}</span>
                  {item.badge && (
                    <Badge variant="secondary" className="text-[10px] h-4 px-1.5 bg-gray-100 text-gray-600">
                      {item.badge}
                    </Badge>
                  )}
                  {item.children && (
                    <ChevronRight size={13} className={`text-gray-300 transition-transform ${isExpanded ? "rotate-90" : ""}`}/>
                  )}
                </button>
                {item.children && isExpanded && (
                  <div className="ml-6 mt-0.5 space-y-0.5">
                    {item.children.map((child) => (
                      <button key={child} onClick={() => setActive(child as NavKey)}
                        className={`w-full text-left text-xs px-3 py-1.5 rounded-md flex items-center gap-2 transition-colors ${
                          active === child ? "text-emerald-700 font-semibold bg-emerald-50" : "text-gray-500 hover:text-gray-800 hover:bg-gray-50"
                        }`}>
                        <span className={`w-1 h-1 rounded-full flex-shrink-0 ${active === child ? "bg-emerald-500" : "bg-gray-300"}`}/>
                        {child}
                      </button>
                    ))}
                  </div>
                )}
              </div>
            );
          })}
          {/* ── Separator + personal links ── */}
          <div className="pt-2 mt-1 border-t border-gray-100 space-y-0.5">
            <p className="px-3 pt-1 pb-0.5 text-[9px] font-bold text-gray-400 uppercase tracking-widest">My Workspace</p>
            {([
              { key:"MyTeams" as NavKey, icon:Users,        label:"My Teams", badge: String(MY_TEAMS.length),                                             badgeCls:"bg-gray-100 text-gray-600" },
              { key:"MyTasks" as NavKey, icon:CheckSquare,  label:"My Tasks", badge: String(MY_TASKS.filter(t=>t.status!=="done").length)+" open",         badgeCls:"bg-blue-100 text-blue-600" },
            ]).map(item=>{
              const Icon = item.icon;
              const isActive = active===item.key;
              return (
                <button key={item.key} onClick={()=>setActive(item.key)}
                  className={`w-full flex items-center gap-2.5 px-3 py-1.5 rounded-lg text-sm transition-all ${
                    isActive ? "bg-emerald-50 text-emerald-700 font-semibold" : "text-gray-600 hover:bg-gray-50 hover:text-gray-900"
                  }`}>
                  <Icon size={15} className={isActive?"text-emerald-600":"text-gray-400"}/>
                  <span className="flex-1 text-left text-xs">{item.label}</span>
                  <Badge variant="secondary" className={`text-[10px] h-4 px-1.5 border-0 ${item.badgeCls}`}>{item.badge}</Badge>
                </button>
              );
            })}
          </div>
        </nav>

        {/* User + hamburger menu */}
        <div className="px-4 py-3 border-t border-gray-100 relative">
          <div className="flex items-center gap-2.5">
            <div className="w-7 h-7 rounded-full bg-gradient-to-br from-emerald-400 to-teal-500 flex items-center justify-center text-white text-[10px] font-bold flex-shrink-0">SA</div>
            <div className="flex-1 min-w-0">
              <div className="text-xs font-semibold text-gray-800">Sara Al-Amri</div>
              <div className="text-[10px] text-gray-400">Organizer</div>
            </div>
            <button onClick={()=>setShowUserMenu(o=>!o)}
              className={`p-1.5 rounded-lg transition-colors ${showUserMenu?"bg-emerald-100 text-emerald-700":"text-gray-400 hover:text-gray-600 hover:bg-gray-100"}`}>
              <MoreHorizontal size={14}/>
            </button>
          </div>

          {/* Dropdown */}
          {showUserMenu && (
            <div className="absolute bottom-full left-3 right-3 mb-1 bg-white border border-gray-200 rounded-xl shadow-lg overflow-hidden z-50">
              <button onClick={()=>{setActive("MyTeams");setShowUserMenu(false);}}
                className="w-full flex items-center gap-2.5 px-3.5 py-2.5 text-xs font-semibold text-gray-700 hover:bg-emerald-50 hover:text-emerald-700 transition-colors">
                <Users size={14} className="text-gray-400"/>
                My Teams
                <span className="ml-auto text-[9px] font-bold bg-gray-100 text-gray-500 px-1.5 py-0.5 rounded-full">{MY_TEAMS.length}</span>
              </button>
              <button onClick={()=>{setActive("MyTasks");setShowUserMenu(false);}}
                className="w-full flex items-center gap-2.5 px-3.5 py-2.5 text-xs font-semibold text-gray-700 hover:bg-emerald-50 hover:text-emerald-700 transition-colors">
                <CheckSquare size={14} className="text-gray-400"/>
                My Tasks
                <span className="ml-auto text-[9px] font-bold bg-blue-100 text-blue-600 px-1.5 py-0.5 rounded-full">{MY_TASKS.filter(t=>t.status!=="done").length} open</span>
              </button>
              <div className="border-t border-gray-100 mx-2"/>
              <button className="w-full flex items-center gap-2.5 px-3.5 py-2.5 text-xs text-gray-500 hover:bg-gray-50 transition-colors">
                <Settings size={13} className="text-gray-400"/> Settings
              </button>
              <button onClick={onLogout} className="w-full flex items-center gap-2.5 px-3.5 py-2.5 text-xs text-red-500 hover:bg-red-50 transition-colors">
                <LogOut size={13} className="text-red-400"/> Sign out
              </button>
            </div>
          )}
        </div>
      </aside>

      {/* Main */}
      <main className="flex-1 flex flex-col overflow-hidden min-w-0">
        {/* Topbar */}
        <header className="bg-white border-b border-gray-200 px-6 py-3 flex items-center gap-4 flex-shrink-0">
          <div className="flex-1 min-w-0">
            <h1 className="text-base font-bold text-gray-900">{pageTitles[active]}</h1>
            <p className="text-[11px] text-gray-500">MENA Summit 2026 · April 15–18, Dubai, UAE</p>
          </div>
          <div className="flex items-center gap-2 flex-shrink-0">
            <div className="relative">
              <Search size={13} className="absolute left-2.5 top-1/2 -translate-y-1/2 text-gray-400"/>
              <input className="pl-8 pr-3 py-1.5 text-xs border border-gray-200 rounded-lg bg-gray-50 w-40 focus:outline-none focus:ring-1 focus:ring-emerald-300" placeholder="Search…"/>
            </div>
            <button className="relative p-2 text-gray-500 hover:text-gray-700 hover:bg-gray-100 rounded-lg">
              <Bell size={15}/>
              <span className="absolute top-1.5 right-1.5 w-1.5 h-1.5 bg-red-500 rounded-full"/>
            </button>
            <Badge className="bg-emerald-100 text-emerald-700 text-[11px] font-medium border-0">28 days to event</Badge>
          </div>
        </header>

        {/* Content */}
        <div className="flex-1 overflow-y-auto p-6">
          {renderPage()}
        </div>
      </main>

      {/* ── My Teams panel ── */}
      {showMyTeams && (
        <div className="fixed inset-0 z-50 flex">
          <div className="absolute inset-0 bg-black/40" onClick={()=>setShowMyTeams(false)}/>
          <div className="relative ml-auto w-[420px] h-full bg-white shadow-2xl flex flex-col">
            <div className="flex items-center justify-between px-5 py-4 border-b border-gray-100">
              <div className="flex items-center gap-2">
                <Users size={16} className="text-emerald-600"/>
                <span className="text-sm font-bold text-gray-900">My Teams</span>
                <span className="text-[10px] font-bold bg-emerald-100 text-emerald-700 px-1.5 py-0.5 rounded-full">{MY_TEAMS.length}</span>
              </div>
              <button onClick={()=>setShowMyTeams(false)} className="p-1.5 rounded-lg hover:bg-gray-100 text-gray-400 hover:text-gray-600">
                <X size={15}/>
              </button>
            </div>
            <div className="flex-1 overflow-y-auto p-5 space-y-3">
              <p className="text-[10px] text-gray-400">Teams Sara Al-Amri is a member or lead of for MENA Summit 2026.</p>
              {MY_TEAMS.map(team=>(
                <div key={team.id} className={`border ${team.border} rounded-xl overflow-hidden`}>
                  <div className={`${team.bg} px-4 py-3 flex items-start gap-3`}>
                    <span className={`w-2.5 h-2.5 rounded-full ${team.dot} mt-1 flex-shrink-0`}/>
                    <div className="flex-1">
                      <div className="flex items-center justify-between gap-2">
                        <p className={`text-xs font-bold ${team.color}`}>{team.name}</p>
                        <span className={`text-[9px] font-bold px-2 py-0.5 rounded-full border ${
                          team.role==="Team Lead" ? "bg-white text-emerald-700 border-emerald-300"
                          : team.role==="Member"  ? "bg-white text-blue-700 border-blue-200"
                          : "bg-white text-gray-600 border-gray-200"
                        }`}>{team.role}</span>
                      </div>
                      <p className="text-[10px] text-gray-500 mt-0.5">{team.description}</p>
                    </div>
                  </div>
                  <div className="px-4 py-2.5 bg-white">
                    <p className="text-[9px] font-semibold text-gray-400 uppercase tracking-wide mb-1.5">Members ({team.members.length})</p>
                    <div className="flex flex-wrap gap-1.5">
                      {team.members.map((m,i)=>(
                        <div key={i} className="flex items-center gap-1 bg-gray-50 border border-gray-200 rounded-full px-2 py-0.5">
                          <div className={`w-3.5 h-3.5 rounded-full flex items-center justify-center text-white text-[7px] font-bold ${i===0?"bg-emerald-500":i===1?"bg-blue-500":i===2?"bg-violet-500":"bg-amber-500"}`}>
                            {m.split(" ").map(n=>n[0]).join("").slice(0,2)}
                          </div>
                          <span className={`text-[9px] ${m==="Sara Al-Amri"?"font-bold text-emerald-700":"text-gray-600"}`}>{m}</span>
                        </div>
                      ))}
                    </div>
                  </div>
                </div>
              ))}
            </div>
          </div>
        </div>
      )}

      {/* ── My Tasks panel ── */}
      {showMyTasks && (
        <div className="fixed inset-0 z-50 flex">
          <div className="absolute inset-0 bg-black/40" onClick={()=>setShowMyTasks(false)}/>
          <div className="relative ml-auto w-[480px] h-full bg-white shadow-2xl flex flex-col">
            <div className="flex items-center justify-between px-5 py-4 border-b border-gray-100">
              <div className="flex items-center gap-2">
                <CheckSquare size={16} className="text-emerald-600"/>
                <span className="text-sm font-bold text-gray-900">My Tasks</span>
                <span className="text-[10px] font-bold bg-blue-100 text-blue-700 px-1.5 py-0.5 rounded-full">{MY_TASKS.filter(t=>t.status!=="done").length} open</span>
              </div>
              <button onClick={()=>setShowMyTasks(false)} className="p-1.5 rounded-lg hover:bg-gray-100 text-gray-400 hover:text-gray-600">
                <X size={15}/>
              </button>
            </div>
            {/* Filter strip */}
            <div className="px-5 py-2.5 border-b border-gray-100 flex items-center gap-1.5 flex-wrap">
              <span className="text-[9px] text-gray-400 font-semibold mr-1">Assigned by:</span>
              <span className="text-[9px] bg-gray-100 text-gray-600 border border-gray-200 px-2 py-0.5 rounded-full font-semibold">{MY_TASKS.filter(t=>t.assignerType==="core").length} Core Team</span>
              <span className="text-[9px] bg-blue-50 text-blue-600 border border-blue-200 px-2 py-0.5 rounded-full font-semibold">{MY_TASKS.filter(t=>t.assignerType==="organizer").length} Organizers</span>
            </div>
            <div className="flex-1 overflow-y-auto p-5 space-y-2">
              <p className="text-[10px] text-gray-400 mb-3">Tasks assigned to Sara Al-Amri by the Core Team or other organizers.</p>
              {MY_TASKS.map(task=>(
                <div key={task.id} className={`bg-white border rounded-xl p-3.5 ${task.status==="done"?"opacity-60 border-gray-100":"border-gray-200"}`}>
                  <div className="flex items-start gap-2.5">
                    <div className={`w-4 h-4 rounded border-2 flex items-center justify-center flex-shrink-0 mt-0.5 ${task.status==="done"?"bg-emerald-500 border-emerald-500":"border-gray-300"}`}>
                      {task.status==="done" && <CheckCircle2 size={10} className="text-white"/>}
                    </div>
                    <div className="flex-1 min-w-0">
                      <p className={`text-[11px] font-semibold leading-tight ${task.status==="done"?"line-through text-gray-400":"text-gray-800"}`}>{task.title}</p>
                      <div className="flex flex-wrap items-center gap-1.5 mt-1.5">
                        <span className={`text-[9px] font-bold px-1.5 py-0.5 rounded-full ${MY_TASK_STATUS_CLS[task.status]}`}>
                          {task.status==="todo"?"To Do":task.status==="in-progress"?"In Progress":"Done"}
                        </span>
                        <span className={`text-[9px] font-bold px-1.5 py-0.5 rounded-full ${MY_TASK_PRI_CLS[task.priority]}`}>{task.priority}</span>
                        <span className="text-[9px] font-bold text-amber-600 bg-amber-50 border border-amber-200 px-1.5 py-0.5 rounded-full">Due {task.dueDate}</span>
                      </div>
                      <div className="flex items-center gap-1.5 mt-1.5">
                        <div className={`w-1.5 h-1.5 rounded-full flex-shrink-0 ${task.assignerType==="core"?"bg-emerald-500":"bg-blue-500"}`}/>
                        <span className="text-[9px] text-gray-500">
                          Assigned by <span className="font-semibold text-gray-700">{task.assignedBy}</span>
                          <span className={`ml-1 text-[8px] font-bold ${task.assignerType==="core"?"text-emerald-600":"text-blue-600"}`}>
                            ({task.assignerType==="core"?"Core Team":"Organizer"})
                          </span>
                        </span>
                      </div>
                    </div>
                  </div>
                </div>
              ))}
            </div>
          </div>
        </div>
      )}

    </div>
  );
}
